window.__LEX={"G2200":"<h1>zestos</h1>\n<p>Strong n° 2200 <i>Prononciation [dzes-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>bouillant, très chaud</li>\n<li>métaph. ferveur de l'esprit et zèle</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζεστός, ή, όν :<br>      1</b> qu’on fait bouillir, bouilli, APP. <i>Iber. 85 ;</i><br><b>      2</b> qui bout, bouillant, NIC. <i>fr. 3, 11 ;</i> STR. <i>578 ;</i> DIOSC. <i>1, 39, etc. ;</i><br><b>      3</b> brûlant (sable) DL. <i>6, 23</i>.<br><span><b>Étym</b>. <i>vb</i>. de ζέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζεστος - ζεστός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2201":"<h1>zeugos</h1>\n<p>Strong n° 2201 <i>Prononciation [dzyoo'-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>deux têtes de bétail (chevaux, mules ou bœufs) attelées ensemble, une paire ou un joug de bêtes</li>\n<li>une paire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζεῦγος, εος-ους (τὸ) :<br>   I. 1</b> attelage de deux animaux (bœufs, chevaux, mulets) IL. <i>18, 543 ;</i> THC. <i>4, 128 ; d’où</i> voiture traînée par des animaux attelés, chariot, HDT. <i>1, 31 ;</i> ἐπὶ ζεύγεος ἐλαύνειν, HDT. <i>1, 199 ;</i> ἐπὶ ζεύγους ἄγειν, AND. <i>7, 13 ;</i> HYPÉR. <i>Lyc. 5</i>, traîner sur un chariot ;<br><b>      2</b> <i>p. ext</i>. couple, paire, <i>en parl. d’animaux (faucons, etc</i>.) HDT. <i>3, 76, etc. ; de choses (chaussures, etc</i>.) AR. <i>Eq. 872, etc. ;</i> en parl. des Atrides, ESCHL. <i>Ag. 44 ; particul</i>. couple uni par mariage, EUR. <i>Ph. 331 ;</i> XÉN. <i>Œc. 7, 18 ;</i> LUC. <i>Am. 11 ;</i> κατὰ ζεῦγος <i>ou</i> κατὰ ζεύγη, PLUT. <i>M. 93</i> d ; ἐς ζεύγεα, LUC. <i>Syr. 12</i>, par couples, par paires ; <i>au pl</i>. ζεύγη, la double flûte, TH. <i>H.P. 4, 11, 4 ;</i><br><b>   II</b> <i>p. ext. en parl. de plus de deux animaux attelés ou de plus de deux pers. réunies :</i> ζ. τέθριππον, ESCHL. <i>fr. 368</i>, quadrige ; <i>fig</i>. ζ. τριπάρθενον, EUR. <i>fr. 359</i>, le groupe des trois jeunes filles, les trois Grâces.<br><span><b><span class=\"arrow\"></span></b> <i>Duel nom.-acc</i>. ζεύγει, CIA. <i>2, 652, b, 26 (v. Meisterh. p. 103, § 51, a, 6)</i>.<br><span><b>Étym</b>. ζεύγνυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζευγος - ζεῦγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G2202":"<h1>zeukteria</h1>\n<p>Strong n° 2202 <i>Prononciation [dzook-tay-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une bande, une ceinture, une attache, une sangle, une chaîne</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζευκτηρία, ας (ἡ)</b> lien, chaîne, NT. <i>Ap. 27, 40</i>.<br><span><b>Étym</b>. <i>fém. de</i> ζευκτήριος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζευκτηρια - ζευκτηρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2203":"<h1>Zeus</h1>\n<p>Strong n° 2203 <i>Prononciation [dzyooce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Jupiter ou Zeus = « un père des secours »\n<ol><li>Zeus, le dieu national des Grecs, correspondant au Jupiter des Romains</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ζεύς</b>, <i>voc</i>. <b>Ζεῦ</b>, <i>gén</i>. <b>Διός</b>, <i>dat</i>. <b>Διΐ</b>, <i>acc</i>. <b>Δία (ὁ) :<br>   I</b> Zeus, <i>fils de Kronos et de Rhéa, époux d’Hèra, dieu du ciel ; sel. les mythographes modernes, personnification du ciel divinisé (v. ci-dessous l’étymol.) et en même temps dieu suprême, père des dieux et des hommes, ordonnateur de toutes choses. Comme personnification du ciel, il réside dans l’éther, séjour de la lumière éternelle et se transporte parfois sur les sommets des montagnes où il est adoré, mais sans jamais descendre, comme les autres divinités, sur la terre ; dieu du ciel, il l’obscurcit à son gré par le retour périodique de la nuit, en assemblant les nuages</i> (<i>v</i>. νεφεληγερέτης), <i>en déchaînant la tempête</i> (<i>v</i>. αἰγίοχος) ; <i>il préside à tous les phénomènes atmosphériques : du ciel il lance la foudre, fait gronder le tonnerre, envoie la pluie qui féconde la terre, et, par suite, est honoré comme un dieu nourricier qui fait germer les moissons et qui produit les fruits et les fleurs ; du ciel aussi il envoie les vents propices ou les vents d’orage ; il fait briller l’arc-en-ciel, dont la personnification, Iris, est sa messagère. Comme dieu suprême, il est le dieu fort, capable de tenir suspendus à une chaîne d’or les dieux et déesses et tout l’univers. Supérieur aux autres divinités, même à Hadès et à Poséidon, bien qu’ils aient partagé avec lui les trois grandes régions de l’univers (ciel, terre et eau) il est le seul dieu tout-puissant, dont l’omnipotence n’est limitée que par les arrêts du destin</i> (μοῖρα), <i>càd. par les lois de la nature, mais sans qu’il y ait conflit entre ces deux pouvoirs ; car Zeus est en même temps le dieu souverainement sage, dont l’intelligence suprême s’harmonise avec les lois naturelles. Reconnu par les dieux comme leur père, càd. leur maître, il est aussi le père des hommes ; tout homme dépend de lui : c’est Zeus qui dispense aux mortels les dons du corps, de l’esprit ou du cœur, qui leur envoie le malheur et la prospérité, la gloire et le déshonneur ; maître des rois et des peuples leurs sujets, il les châtie s’ils violent la justice ; il conserve les sociétés humaines en protégeant les lois sur lesquelles reposent ces sociétés ; à ce titre, il est le dieu protecteur de la foi (v</i>. πίστιος<i>), de la parole jurée (v</i>. ὅρκιος<i>), de la justice, du foyer domestique, du mariage, des associations humaines sous toutes les formes, depuis le cercle étroit de la famille jusqu’à la cité et aux grandes confédérations helléniques ; il protège les humbles, les pauvres, les mendiants, et, comme tel, préside à l’hospitalité (v</i>. ξένιος<i>) ; s’il laisse l’homme égaré par le génie du mal (v</i>. Ἄτη<i>) commettre des fautes, il lui permet de se racheter par le repentir et la prière ; et ainsi, personnifiant tous les attributs de puissance, de force, d’ordre, d’intelligence, de bonté, de justice, il est l’expression la plus haute et la plus complète de la divinité, le dieu par excellence, HOM. etc. ; invoqué dans les prières :</i> Ζεῦ πάτερ, OD. <i>7, 331, etc</i>. Ζεῦ μέγιστε, IL. <i>2, 412 ;</i> Zeus, père (des dieux et des hommes)! Zeus très grand ! ὦ Ζεῦ βασιλεῦ, ESCHL. <i>Pers. 532 ;</i> AR. <i>Nub. 2, etc</i>. ô Zeus roi! Ζεῦ σῶτερ, AR. <i>Th. 1009,</i> Zeus sauveur! Ζεῦ Ζεῦ, ESCHL. <i>Ag. 973 ;</i> SOPH. <i>Ph. 989 ;</i> EUR. <i>El. 137, etc</i>. Zeus! Zeus! <i>invoqué avec d’autres dieux en gén</i>. OD. <i>12, 371, etc. ;</i> XÉN. <i>Cyr. 2, 2, 10 ;</i> PLAT. <i>Prot. 310</i> d, <i>etc. ; avec Hèra,</i> A. RH. <i>4, 95 ; avec Apollon,</i> SOPH. <i>Aj. 187, O.C. 623, etc. ; avec Hestia,</i> XÉN. <i>Cyr. 1, 6, 1, etc. ; de même dans des formules de serment :</i> πρὸς τοῦ Διός <i>ou</i> πρὸς Διός, AR. <i>Av. 130 ;</i> XÉN. <i>An. 5, 7, 32, etc</i>. au nom de Zeus ; μὰ <i>ou</i> νὴ τὸν Δία, <i>ou</i> μὰ <i>ou</i> νὴ Δία, XÉN. <i>Mem. 2, 7, 14 ; Cyr. 4, 3, 10 ;</i> PLAT. <i>Rsp. 426</i> b, <i>etc</i>. non <i>ou</i> oui par Zeus ! <i>comme personnification du ciel, en parl. de la pluie</i>, HDT. <i>2, 13 ;</i> Ζεὺς ὕει (<i>v</i>. ὕω) la pluie tombe du ciel, il pleut ;<br><b>   II</b> <i>p. anal. ou p. ext. :</i><br><b>      1</b> <i>en parl. d’Hadès</i> (Ζεὺς καταχθόνιος, Zeus souterrain) IL. <i>9, 457 ;</i> SOPH. <i>O.C. 1006, etc. ; ou de Poséidon</i>, PAUS. <i>2, 24, 4 ;</i> ORPH. <i>fr. 6 ;</i><br><b>      2</b> <i>en parl. de dieux étrangers (Ammon</i> PD. <i>P. 4, 28, etc. ; Bélus</i>, NONN. <i>D. 3, 291, etc</i>.) ;<br><b>      3</b> <i>par allus. ou ironiq. en parl. de rois ou de personnages célèbres (Xerxès</i>, HDT. <i>7, 56 ; Périclès,</i> CRAT. <i>dans</i> PLUT. <i>Per. 3, etc</i>.) ;<br><b>      4</b> <i>postér. surn. des empereurs romains = lat</i>. Jupiter, DP. <i>210 ;</i> OPP. <i>C. 1, 3 ;</i><br><b>      5</b> Διὸς ὁ ἀστήρ, ARSTT. <i>Meteor. 1, 6, etc. ;</i> ὁ τοῦ Διὸς ἀστήρ, CLÉOM. <i>13, 16</i>, la planète Jupiter ;<br><b>      6</b> Διὸς ἡμέρα, DC. <i>37, 18</i> = <i>lat</i>. Jovis dies, <i>franç</i>. jeudi.<br><span><b><span class=\"arrow\"></span></b> <i>Nom. éol</i>. Ζεῦς, ALC. <i>27</i> (Ζεύς <i>Bgk). Gén. éol</i>. Δίος, ALC. <i>31, 68 ;</i> SAPPH. <i>1 ;</i> THCR. <i>Idyl. 28, 5 ; 30, 31. Dat. contr</i>. Δί, PD. <i>O. 13, 150, etc. (Bœckh, forme confirmée par les inscr. ; v. Bull. de corr. hell. t. IV, p. 96, p. 433, n° 21, etc.) Acc. rare</i> Ζεῦν ÆSCHR. (ATH. <i>335</i> c). <i>Plur</i>. Δίες, PLUT. <i>M. 425</i> f. — <i>Déclin. réc. dans</i> SEXT. <i>M. 1, 177, 195</i>, Ζεύς, Ζέος, Ζέϊ, Ζέα, <i>d’après un th. fict</i>. Ζεϝ-, <i>c</i>. βασιλεύς <i>de</i> βασιλεϝ-.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *dieu-, ciel ; <i>cf. sscr</i>. dyáuḥ, <i>lat</i>. Jovis, <i>de</i> *diēus ; Ζεῦ πάτερ = <i>lat</i>. Jū-piter ; Ζῆν = <i>sscr</i>. dyā́m, <i>lat</i>. diem ; <i>p. les cas obliques</i> Διϝ-ός, <i>etc. cf. sscr</i>. diváḥ, <i>etc. ; v</i>. Ζήν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ζευς - Ζεύς</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2204":"<h1>zeo</h1>\n<p>Strong n° 2204 <i>Prononciation [dzeh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>bouillir de chaleur, être chaud\n<ol type=\"a\">\n<li>utilisé pour de l'eau</li>\n<li>métaph.\n<ol>\n<li>utilisé pour une bouillante colère, amour, zèle, ce qui est bien ou mal etc.</li>\n<li>fervent en esprit, dit du zèle pour ce qui est bien</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζέω</b> <span>(<i>impf</i>. ἔζεον, <i>f</i>. ζέσω, <i>ao</i>. ἔζεσα, <i>pf. inus. ; pass. ao</i>. ἐζέσθην)</span><br><b>   I <i>intr.</i></b> bouillir, <i>càd. :</i><br><b>      1</b> <i>propr</i>. bouillir, <i>en parl. de l’eau</i>, IL. <i>18, 349 ;</i> OD. <i>10, 360 ; p. ext. en parl. du vase dans lequel on fait bouillir un liquide</i>, IL. <i>21, 362 ;</i> EUR. <i>Cycl. 343 ; en parl. de terre</i>, HÉS. <i>Th. 695, 847 ; d’airain</i>, CALL. <i>Dian. 60 ;</i><br><b>      2</b> bouillonner, <i>en parl. de la mer, du sang, du vin ; avec un rég. :</i> λίμνη ζέουσα ὕδατος καὶ πηλοῦ, PLAT. <i>Phæd. 113</i> a, lac de boue et d’eau bouillonnante ; πίθος ζέων οἴνου, TH. <i>H.P. 9, 17, 3</i>, tonneau de vin bouillonnant ; <i>avec le dat</i>. ζ. αἵματι, ARSTD. <i>t. 1, 142 ;</i> LYC. <i>690</i>, bouillonner de sang ; φθειρσί, LUC. <i>Sat. 26</i>, fourmiller de poux ;<br><b>   II <i>tr.</i></b> faire bouillir <i>ou</i> faire bouillonner, A. RH. <i>3, 273 ; fig</i>. ANTH. <i>7, 385</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. p.-ê. contr</i>. (ζέω-ζῶ) <i>selon la règle des verbes monosyll. en</i> -έω, <i>mais sans ex. dans les inscr. att. (v. Meisterh. p. 140, 5). Prés. poét</i>. ζείω, IL. <i>21, 362 ;</i> A. RH. <i>1, 734 ;</i> CALL. <i>l. c. ; part. fém. dor</i>. ζέοισα, PD. <i>O. 1, 48. Impf. 3 sg. poét</i>. ζέεν, A. RH. <i>4, 955. Ao. poét</i>. ζέσσα, IL. <i>18, 349 ;</i> ANTH. <i>7, 208</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ies-, bouillir, écumer ; <i>cf. sscr</i>. yasati.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζεω - ζέω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2205":"<h1>zelos</h1>\n<p>Strong n° 2205 <i>Prononciation [dzay'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>agitation de l'esprit, ardeur, ferveur de l'esprit\n<ol type=\"a\">\n<li>zèle, ardeur dans l'étreinte, la poursuite, la défense\n<ol>\n<li>zèle en faveur d'une personne ou une chose</li>\n<li>la férocité de l'indignation, un zèle punitif</li>\n</ol>\n</li>\n<li>une rivalité sérieuse, jalousie, être envieux de</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζῆλος, ου (ὁ) :<br>   I. 1</b> ardeur, zèle, <i>en b. part, p. opp. à</i> φθόνος (<i>mais v. ci-dessous</i> <b>3</b>) PLAT. <i>Menex. 242</i> a ; ARSTT. <i>Rhet. 2, 11, 1 ; au plur</i>. PLAT. <i>Leg. 679</i> c ; <i>avec un rég. de pers. :</i> ζ. τινος, SOPH. <i>O.C. 943 ;</i> PLUT. <i>Thes. 25 ; ou</i> πρός τινα, LUC. <i>Demon. 57</i>, zèle pour qqn ; <i>avec un rég. de ch. :</i> τινος, PLUT. <i>Cor. 4, etc. ;</i> πρός τι, PLUT. <i>Per. 2</i>, pour qqe ch. ;<br><b>      2</b> <i>p. suite,</i> émulation, rivalité, SOPH. <i>O.C. 943 ;</i> PLUT. <i>Cor. 4, etc. ; d’où</i> objet d’envie, EUR. <i>Or. 973 ;</i><br><b>      3</b> <i>en mauv. part</i>, haine, jalousie, <i>c</i>. φθόνος, HÉS. <i>O. 193 ; joint à</i> φθόνος, PLAT. <i>Phil. 47</i> e, <i>50</i> b, <i>etc. ;</i> PLUT. <i>Cor. 10 ;</i><br><b>   II</b> objet d’émulation, sujet de gloire, SOPH. <i>Aj. 503 ;</i> DÉM. <i>267, 14 ; 300, 23 ; joint à</i> τιμή, DÉM. <i>641, 8, etc. ;</i><br><b>   III</b> exubérance de style, <i>en parl. des orateurs asiatiques</i>, STR. <i>648 ;</i> PLUT. <i>Ant. 2 ;</i><br><b>   IV</b> postér. ardeur (du feu) NT. <i>Hebr. 13, 27</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *ieh₂-, poursuivre, venger ; <i>cf</i>. ζητέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζηλος - ζῆλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 17 versets de 10 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (5)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G2206":"<h1>zeloo</h1>\n<p>Strong n° 2206 <i>Prononciation [dzay-lo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>brûler de zèle\n<ol type=\"a\">\n<li>bouillir d'envie, de haine, de colère\n<ol>\n<li>dans un bon sens, être zélé dans la poursuite du bien</li>\n</ol>\n</li>\n<li>désirer sincèrement, poursuivre\n<ol>\n<li>lutter pour, s'occuper sérieusement de quelque chose</li>\n<li>s'efforcer de faire quelque chose pour quelqu'un</li>\n<li>être l'objet de zèle pour les autres</li>\n</ol>\n</li>\n<li>envier</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζηλόω-ῶ</b>, avoir de l’ardeur, <i>d’où :</i><br><b>   I</b> rechercher avec ardeur :<br><b>      1</b> <i>avec un rég. de chose (la gloire, la vertu, etc.) acc</i>. DÉM. <i>22, 18 ; au pass</i>. PLAT. <i>Phædr. 232</i> a ;<br><b>      2</b> <i>avec un rég. de pers</i>. chercher à égaler, à imiter : τινα, THC. <i>2, 37, 64 ;</i> PLAT. <i>Rsp. 553</i>, qqn ;<br><b>   II</b> envier :<br><b>      1</b> <i>en b. part, càd</i>. louer, approuver : τι, THC. <i>5, 105</i>, qqe ch. ; τινά τινος, SOPH. <i>El. 1027 ;</i> AR. <i>Av. 1010 ;</i> τινά τι, SOPH. <i>Aj. 552</i>, qqe ch. de qqn ; louer qqn de qqe ch. ; <i>avec un part. :</i> σὲ ζηλῶ θανόντα, ESCHL. <i>Pers. 712 ; cf</i>. EUR. <i>Or. 52</i>, je t’envie d’être mort ; <i>avec une conj</i>. ζ. τινα ὁθούνεκα, ESCHL. <i>Pr. 330 ;</i> ὅτι, XÉN. <i>Hell. 6, 5, 45 ; ou</i> εἰ, SOPH. <i>fr. 516</i>, porter envie à qqn, <i>càd</i>. l’estimer heureux de ce que, <i>etc. ; abs</i>. EUR. <i>I.A. 16 ; iron</i>. ζηλῶ σε, EUR. <i>Med. 60</i>, je t’envie, <i>càd</i>. j’envie ton ignorance, j’ai pitié de ton ignorance ;<br><b>      2</b> <i>en mauv. part</i>, jalouser, envier, HH. <i>Cer. 168, 223 ;</i> HÉS. <i>O. 23 ;</i> THCR. <i>Idyl. 6, 26 ; abs</i>. NT. <i>Ap. 7, 9 ; 1Cor. 13, 4</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ζαλόω <span>[ᾱ]</span> THCR. <i>Idyl. 3, 50 ; 6, 26</i>.<br><span><b>Étym</b>. ζῆλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζηλοω - ζηλόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 6 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (3)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2207":"<h1>zelotes</h1>\n<p>Strong n° 2207 <i>Prononciation [dzay-lo-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui brûle de zèle, un zélote (celui qui est zélé)</li>\n<li>utilisé pour Dieu jaloux de toute rivalité et revendiquant sévèrement ce contrôle</li>\n<li>très fortement désireux, zélé pour une chose, qui ambitionne\n<ol type=\"a\">\n<li>acquérir une chose</li>\n<li>défendre et soutenir une chose avec véhémence</li>\n</ol>\n</li>\n<li>membre du parti zélote</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζηλωτής, οῦ (ὁ) :<br>   I</b> qui a du zèle, du goût pour : τινος, pour qqe ch. PLAT. <i>Prot. 343</i> a ; ISOCR. <i>4</i> b ; ESCHN. <i>50, 26 ; 51, 8</i>, pour qqn, LUC. <i>H. conscr. 15, etc. ; d’où eccl</i>. partisan zélé de, zélateur de, <i>gén</i>. SPT. <i>2Macc. 4, 2 ;</i> NT. <i>Matth. 10, 4 ; Marc. 3, 18 ; Luc. 6, 15, etc. ;</i> JOS. <i>A.J. 12, 6, 2 ; particul. en parl. des Juifs</i>, fanatique <i>ou</i> patriote, JOS. <i>B.J. 4, 3, 9 ; 7, 8, 1 ;</i><br><b>   II</b> jaloux, SPT. <i>Ex. 20, 5 ; 34, 14</i>.<br><span><b>Étym</b>. ζηλόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζηλωτης - ζηλωτής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT).\n<ul>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G2208":"<h1>Zelotes</h1>\n<p>Strong n° 2208 <i>Prononciation [dzay-lo-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>zélote = « celui qui est zélé »\n<ol>\n<li>celui qui brûle de zèle, un zélateur, fanatique</li>\n<li>utilisé par Dieu comme jaloux de tout rival</li>\n<li>désirer très fortement une chose\n<ol type=\"a\">\n<li>acheter une chose</li>\n<li>défendre et soutenir, lutter avec véhémence pour une chose</li>\n</ol>\n</li>\n<li>membre d'un parti de patriotes Juifs, créé afin de résister aux Romains et de protéger contre la violation de la religion, mais qui dégénéra en un corps d'assassins</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζηλωτής, οῦ (ὁ) :<br>   I</b> qui a du zèle, du goût pour : τινος, pour qqe ch. PLAT. <i>Prot. 343</i> a ; ISOCR. <i>4</i> b ; ESCHN. <i>50, 26 ; 51, 8</i>, pour qqn, LUC. <i>H. conscr. 15, etc. ; d’où eccl</i>. partisan zélé de, zélateur de, <i>gén</i>. SPT. <i>2Macc. 4, 2 ;</i> NT. <i>Matth. 10, 4 ; Marc. 3, 18 ; Luc. 6, 15, etc. ;</i> JOS. <i>A.J. 12, 6, 2 ; particul. en parl. des Juifs</i>, fanatique <i>ou</i> patriote, JOS. <i>B.J. 4, 3, 9 ; 7, 8, 1 ;</i><br><b>   II</b> jaloux, SPT. <i>Ex. 20, 5 ; 34, 14</i>.<br><span><b>Étym</b>. ζηλόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ζηλοτης - Ζηλωτής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2209":"<h1>zemia</h1>\n<p>Strong n° 2209 <i>Prononciation [dzay-mee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dommage, perte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζημία, ας (ἡ) :<br>      1</b> dommage, perte, <i>p. opp. à</i> κέρδος, XÉN. <i>Cyr. 2, 2, 12 ;</i> PLAT. <i>Leg. 835</i> b ; LYS. <i>109, 23 ;</i> ARSTT. <i>Nic. 5, 4, 5 ; ou à</i> ὠφέλεια, XÉN. <i>Mem. 2, 3, 6 ;</i> ζημίαν ποιεῖν, <i>abs</i>. AR. <i>Pl. 1124, ou</i> φέρειν τινι, PLAT. <i>Leg. 835</i> b, causer <i>ou</i> apporter du dommage à qqn ; ζημίαν λαϐεῖν, DÉM. <i>155, 12</i>, éprouver un dommage ; ζημίαν νομίζειν, ISOCR. <i>37</i> b ; IS. <i>65, 39, ou</i> ἡγεῖσθαι, XÉN. <i>Mem. 2, 3, 2,</i> regarder comme un dommage ;<br><b>      2</b> <i>particul</i>. amende pécuniaire : ζημίαν καταϐάλλειν, DÉM. <i>727, 4</i>, verser une amende ; ἀποτίνειν, HDT. <i>2, 65 ;</i> ἐκτίνειν, PLAT. <i>Leg. 774</i> e, payer, acquitter une amende ; ὀφείλειν, HDT. <i>3, 52</i>, devoir une amende, <i>d’où</i> être condamné à une amende ; ζημίαν ὀφείλειν τάλαντον, PLUT. <i>Lys. 27</i>, être condamné à une amende d’un talent ;<br><b>      3</b> <i>en gén</i>. peine, châtiment : ζημίαν ἐπιτιθέναι τινί, HDT. <i>1, 144 ;</i> PLAT. <i>Leg. 662</i> b ; τιθέναι, PLAT. <i>Leg. 860</i> e, infliger une peine à qqn ; ζημίᾳ τινὰ ζημιοῦν <i>ou</i> κολάζειν, PLAT. <i>Leg. 847</i> a, frapper qqn d’un châtiment ; <i>avec le nom de la peine :</i> θάνατον ζημίαν ἐπιτίθεσθαι, THC. <i>2, 24 ; ou</i> προθεῖναι, THC. <i>3, 44 ; ou</i> τάττειν, DÉM. <i>498, 7 ; ou</i> ποιεῖν, XÉN. <i>Mem. 2, 2, 3</i>, infliger <i>ou</i> fixer par une loi la peine de mort ; θάνατος ἡ ζημία ἐπικέεται, HDT. <i>2, 38 ;</i> θάνατός ἐστιν ἡ ζημία, XÉN. <i>Mem. 1, 2, 62</i>, on est puni de mort ;<br><b>      4</b> <i>en parl. de pers., t. de reproche</i>, fléau, peste, <i>avec un adj</i>. φανερὰ ζαμία (<i>dor</i>.) AR. <i>Ach. 737 ;</i> καθαρὰ <i>ou</i> λαμπρὰ ζ. ALCIPHR. <i>3, 21, 38</i>, vrai fléau ; <i>abs</i>. ALEX. (ATH. <i>104</i> e).<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ζημίη, HDT. <i>ll. cc. Dor</i>. ζαμία <span>[ζᾱ]</span> AR. <i>l. c</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζημια - ζημία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Philippiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2210":"<h1>zemioo</h1>\n<p>Strong n° 2210 <i>Prononciation [dzay-mee-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>affecter d'un dommage, endommager</li>\n<li>soutenir un dommage, subir un préjudice, souffrir une perte être dépouillé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζημιόω-ῶ</b> <span>(<i>f</i>. -ώσω, <i>ao</i>. ἐζημίωσα)</span><br><b>      1</b> causer du dommage à, léser : τινα, PLAT. <i>Leg. 846</i> a, qqn ; <i>à côté de</i> βλάψαι <i>et avec idée d’un dommage plus grave,</i> XÉN. <i>Cyr. 3, 1, 39 ;</i> πόλιν, LYS. <i>185, 37</i>, l’État ; <i>avec un adj. neutre,</i> οὐδὲν ζημ. τινα, ISOCR. <i>117</i> b, ne faire de tort à personne ; <i>au pass</i>. être lésé ; éprouver un dommage, une perte, <i>abs</i>. PLAT. <i>Gorg. 490</i> c ; <i>avec un adj. neutre,</i> ζ. μεγάλα, THC. <i>3, 40 ;</i> πολλά, PLAT. <i>Leg. 916</i> e, faire de grandes, de grosses pertes ;<br><b>      2</b> infliger une amende : ζημ. τινα πεντήκοντα τάλαντα, HDT. <i>6, 136 ; ou plus souv. avec le dat. :</i> χιλίῃσι δραχμῇσι, HDT. <i>6, 21 ;</i> μναῖς τρισί, PLAT. <i>Leg. 936</i> a, punir qqn d’une amende de 50 talents, de 1000 drachmes, de 3 mines ; μέχρι τοσούτου, PLAT. <i>Leg. 855</i> b, infliger une amende jusqu’à une somme aussi forte, jusqu’à une certaine somme ;<br><b>      3</b> <i>p. ext</i>. punir, <i>en gén</i>. HDT. <i>7, 35 ; 9, 77 ;</i> ζ. τινα θανάτῳ, HDT. <i>3, 27 ;</i> τινα φυγῇ, THC. <i>4, 65</i>, punir qqn de mort, de l’exil ; <i>au pass</i>. ζημιοῦσθαι θανάτῳ, ANT. <i>123, 24 ;</i> PLAT. <i>Pol. 297</i> e, être puni de mort ; ζημιοῦσθαι ζημίαις ἐσχάταις, LYS. <i>189, 16</i>, être puni des derniers châtiments.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. pass</i>. ζημιωθήσομαι, LYS. <i>181, 37 ;</i> IS. <i>81, 24 ;</i> XÉN. <i>Mem. 3, 9, 12 ; f. moy. ζημιώσομαι au sens pass</i>. HDT. <i>7, 39 ;</i> THC. <i>3, 40 ;</i> AND. <i>10, 11 ;</i> ISOCR. <i>378</i> c ; DÉM. <i>17, 3 ;</i> ARSTT. <i>Pol. 6, 5, 3, etc</i>.<br><span><b>Étym</b>. ζημία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζημιοω - ζημιόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2211":"<h1>Zenas</h1>\n<p>Strong n° 2211 <i>Prononciation [dzay-nas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Zénas (Angl. Zenas) = « don de Zeus (Jupiter) »\n<ol><li>un docteur de la loi Juive, et devenu ensuite Chrétien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ζημας - Ζηνᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G2212":"<h1>zeteo</h1>\n<p>Strong n° 2212 <i>Prononciation [dzay-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chercher dans le but de trouver\n<ol type=\"a\">\n<li>chercher une chose</li>\n<li>chercher à résoudre, par la pensée, la méditation, le raisonnement, en s'interrogeant</li>\n<li>rechercher, désirer, viser à, s'efforcer de</li>\n</ol>\n</li>\n<li>chercher, c.à.d exiger, demander\n<ol type=\"a\">\n<li>implorer, demander quelque chose de quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζητέω-ῶ</b> <span>(<i>impf</i>. ἐζήτουν, <i>f</i>. ζητήσω, <i>ao</i>. ἐζήτησα, <i>pf</i>. ἐζήτηκα)</span><br><b>   I</b> chercher, <i>en gén., p. opp. à</i> εὑρίσκω : εὑρήσεις ζητῶν, AR. <i>Pl. 104</i>, tu trouveras en cherchant ; μὴ ζητῶν, XÉN. <i>Ages. 8, 1</i>, sans chercher ;<br><b>   II</b> <i>particul. :</i><br><b>      1</b> chercher à rencontrer, aller à la recherche de : τινα, XÉN. <i>An. 2, 3, 2</i>, de qqn ; <i>en parl. de chasseurs :</i> ζ. τὸν λαγώ, XÉN. <i>Cyn. 6, 25</i>, chercher à retrouver le lièvre ;<br><b>      2</b> chercher à trouver, à connaître : τὸν αὐτόχειρα, SOPH. <i>O.R. 266</i>, le meurtrier ; τὸν δράσαντα, THC. <i>6, 27</i>, le coupable ; <i>particul. en parl. de recherches philosophiques :</i> ζ. τὰ θεῖα, XÉN. <i>Mem. 1, 1, 15</i>, s’occuper de recherches sur les choses divines ; ζητουμένης ἀρετῆς ὅ τι ἐστίν, PLAT. <i>Men. 79</i> d, si l’on cherche ce qu’est la vertu ; τὸ ζητούμενον, PLAT. <i>Theæt. 201</i> a ; ARSTT. <i>Top. 2, 2, 7, etc</i>. l’objet de la discussion, ce qui est en question ; <i>en parl. d’enquêtes judiciaires :</i> ζητεῖν περί τινος, DIN. <i>91, 20 ; 97, 14 ;</i> AND. <i>7, etc</i>. faire une enquête sur qqe ch. ;<br><b>      3</b> chercher à obtenir, <i>acc. :</i> ζ. πημάτων ἀπαλλαγήν, ESCHL. <i>Pr. 316</i>, chercher à obtenir la fin de ses souffrances ; <i>d’où demander :</i> τῶν πράξεων παρὰ τοῦ στρατηγοῦ λόγον ζητοῦντες, DÉM. <i>49, 18</i>, demandant compte au général de sa conduite ; <i>avec une prop. inf</i>. PLAT. <i>Rsp. 443</i> b, <i>ou simpl. un inf</i>. HDT. <i>3, 137 ;</i> ESCHL. <i>Pr. 776 ;</i> AR. <i>Pl. 370</i>, chercher à obtenir que, chercher à, s’efforcer de ;<br><b>   III</b> <i>p. suite,</i> regretter l’absence de, regretter, désirer : τι, HDT. <i>1, 94</i>, qqe ch. ; τινα, PLUT. <i>Galb. 8</i>, qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. impér. 2 sg. dor</i>. ζάτει <span>[ᾱ]</span> THCR. <i>Idyl. 21, 66 ; part. fém. dor</i>. ζατεῦσα <span>[ζᾱ]</span> THCR. <i>Idyl. 1, 83 (var</i>. ζάτοισα, <i>v</i>. *ζήτω). <i>Impf. 3 sg. ion</i>. ἐζήτεον, HDT. <i>1, 43 ; épq</i>. ζήτει, IL. <i>14, 258 ;</i> HH. <i>Merc. 22. Pass. fut</i>. ζητηθήσομαι, SEXT. <i>P. 1, 60 ; M. 8, 16. Fut. moy. au sens pass</i>. ζητήσομαι, SEXT. <i>M. 1, 28 ;</i> GAL. <i>1, 649</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *ieh₂-, chercher, enquérir ; <i>cf</i>. ζῆλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζητεω - ζητέω</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n118 fois dans 115 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (14)</li>\n<li>Marc (9)</li>\n<li>Luc (27)</li>\n<li>Jean (34)</li>\n<li>Actes (10)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (8)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (2)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2213":"<h1>zetema</h1>\n<p>Strong n° 2213 <i>Prononciation [dzay'-tay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une question, un débat\n<ol type=\"a\">\n<li>à propos de la loi</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζήτημα, ατος (τὸ) :<br>   I</b> recherche :<br><b>      1</b> <i>en gén</i>. EUR. <i>Bacch. 1218, au plur. ;</i><br><b>      2</b> recherche scientifique <i>ou</i> philosophique, question, PLAT. <i>Leg. 630</i> e, <i>891</i> c, <i>etc. ; avec περί et le gén. (cf. lat</i>. quæstio de) ;<br><b>   II</b> objet de recherche, SOPH. <i>O.R. 278 ;</i> EUR. <i>Bacch. 1139</i>.<br><span><b>Étym</b>. ζητέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζητημα - ζήτημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (5)</li>\n</ul>\n</td></tr>\n</table>","G2214":"<h1>zetesis</h1>\n<p>Strong n° 2214 <i>Prononciation [dzay'-tay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une recherche</li>\n<li>une enquête</li>\n<li>une question, un débat</li>\n<li>sujet de discussion ou de débat, matière à controverse</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζήτησις, εως (ἡ)</b> action de chercher, <i>d’où :</i><br><b>   I</b> recherche, <i>en gén. :</i> κατ' Εὐρώπης ζήτησιν, HDT. <i>2, 44</i> (s’embarquer et partir) à la recherche d’Europe ; ἀνδρὸς ζήτησις, SOPH. <i>Tr. 55</i>, recherche pour découvrir un homme ; ἡ ζ. τῶν δρασάντων, THC. <i>8, 66</i>, la recherche des coupables ; <i>avec un rég. de chose :</i> ζ. τῆς ἀληθείας, THC. <i>1, 20</i>, recherche de la vérité ;<br><b>   II</b> <i>particul. :</i><br><b>      1</b> inspection : ποιεῖσθαι ζήτησιν τῶν νεῶν, HDT. <i>6, 118</i>, faire la visite des navires ;<br><b>      2</b> recherche philosophique, PLAT. <i>Crat. 406</i> a, <i>etc. ;</i> περί τινος, PLAT. <i>Tim. 47</i> a ; περί τι, PLAT. <i>Rsp. 336</i> e, <i>368</i> e, sur qqe ch. ; <i>au pl</i>. PLAT. <i>Phæd. 66</i> d ;<br><b>      3</b> enquête judiciaire, DIN. <i>91, 20</i>.<br><span><b>Étym</b>. ζητέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζητησις - ζήτησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G2215":"<h1>zizanion</h1>\n<p>Strong n° 2215 <i>Prononciation [dziz-an'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ivraie, ressemblant au blé mais les grains en sont noirs</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζιζάνιον, ου (τὸ)</b> ivraie (<i>lolium temulentum</i> L.) <i>mauvaise herbe</i>, GEOP. <i>2, 43 ; au plur</i>. NT. <i>Matth. 13, 25 ;</i> GEOP. <i>10, 87</i>.<br><span><b>Étym</b>. <i>emprunt à une langue orientale (sumérien</i>).</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζιζανιον - ζιζάνιον</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (8)</li>\n</ul>\n</td></tr>\n</table>","G2216":"<h1>Zorobabel</h1>\n<p>Strong n° 2216 <i>Prononciation [dzor-ob-ab'-el]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Zorobabel (Angl. Zerubbabel) = « né à Babel, c.à.d Babylone »\n<ol><li>le chef de la tribu de Juda au temps du retour de la captivité à Babylone, dans la première année de Cyrus</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ζοροβαβελ</font> &lt; זרבבל - <font face=\"Georgia\">Ζοροβαβέλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2217":"<h1>zophos</h1>\n<p>Strong n° 2217 <i>Prononciation [dzof'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>obscurité, noirceur\n<ol type=\"a\">\n<li>utilisé pour l'obscurité du monde inférieur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζόφος, ου (ὁ) :<br>   I</b> ténèbres, obscurité, HÉS. <i>Sc. 227 ;</i> PD. <i>I. 4, 30 ; en prose,</i> PLUT. <i>Alc. 28 ;</i> LUC. <i>D. mort. 15, 2 ; Cat. 2 ; V.H. 1, 6 ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> ténèbres des enfers, IL. <i>21, 56, etc. ;</i> OD. <i>20, 356 ;</i> ESCHL. <i>Pers. 839 ; d’où</i> le royaume des enfers, IL. <i>15, 191 ;</i> OD. <i>11, 57 ;</i> Q. SM. <i>3, 256 ;</i><br><b>      2</b> région de la terre située dans l’obscurité, occident, OD. <i>3, 335 ; p. opp. à</i> ἠώς, OD. <i>10, 190 ;</i> πρὸς ζόφον, à l’occident, <i>p. opp. à</i> πρὸς ἠῶ τ' ἠέλιόν τε, IL. <i>12, 239 ;</i> OD. <i>13, 240 ;</i><br><b>   III</b> <i>fig</i>. obscurité (de l’âme) PLUT. <i>M. 48</i> c ; <i>en parl. du style,</i> DH. <i>ad Pomp. 2</i>.<br><span><b>Étym</b>. <i>cf</i>. δνόφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζοφος - ζόφος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Pierre (2)</li>\n<li>Jude (2)</li>\n</ul>\n</td></tr>\n</table>","G2218":"<h1>zugos</h1>\n<p>Strong n° 2218 <i>Prononciation [dzoo-gos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un joug\n<ol type=\"a\">\n<li>ce qui est posé sur le bétail attelé</li>\n<li>métaph., utilisé pour tout fardeau\n<ol>\n<li>celui de l'esclavage</li>\n<li>le joug des lois gênantes, en particulier la loi Mosaïque, et ce mot de joug est également appliqué aux commandements de Christ, mais c'est un joug léger, contrairement aux lois des Pharisiens qui étaient un véritable joug</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>une balance, composée de deux plateaux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζυγός, οῦ (ὁ)</b> <span>[ῠ]</span> (<i>au plur. confond sa déclin. avec celle de</i> ζυγόν) :<br><b>      1</b> joug, HH. <i>Cer. 217 (dans l’Iliade et l’Odyssée, les formes du sg. laissent le genre indistinct</i>) ; <i>en parl. du joug romain :</i> ἄγειν ὑπὸ τὸν ζυγόν, POL. <i>4, 82, 2</i>, faire passer sous le joug ;<br><b>      2</b> fléau d’une balance, <i>d’où</i> balance, PLAT. <i>Tim. 63</i> b.<br><span><b><span class=\"arrow\"></span></b> <i>Plur</i>. ζυγοί, <i>seul</i>. J. AFR. <i>p. 316 Veterum mathematicorum opera, Thévenot ;</i> SCH.-THC. <i>1, 29. Éol</i>. ζύγος, THCR. <i>Idyl. 30, 29</i>.<br><span><b>Étym</b>. <i>cf</i>. ζυγόν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζυγος - ζυγός</font>\n<br><br>vient de la racine de 'zeugnumi' (joindre, spécialement par un « joug »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Actes (1)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2219":"<h1>zume</h1>\n<p>Strong n° 2219 <i>Prononciation [dzoo'-may]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>levain</li>\n<li>métaph. de la corruption morale et mentale enracinée, en fonction de sa tendance à infecter les autres</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζύμη, ης (ἡ)</b> <span>[ῡ]</span> levain, ARSTT. <i>G.A. 3, 4, 3 ;</i> SPT. <i>Ex. 12, 15 ; fig</i>. levain de corruption, NT. <i>Matth. 16, 6</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *iuHs-, mélanger, mettre en mouvement ; <i>cf. lat</i>. jūs, <i>sscr</i>. yū́ṣ-, fermentation, brouet.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζυμη - ζύμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>1 Corinthiens (4)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G2220":"<h1>zumoo</h1>\n<p>Strong n° 2220 <i>Prononciation [dzoo-mo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire lever</li>\n<li>mélanger du levain avec de la pâte pour qu'elle fermente, et qu'elle lève</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζυμόω-ῶ</b> <span>[ῡ]</span> pétrir avec du levain, <i>d’où</i> faire fermenter, faire lever, NT. <i>1Cor. 5, 6 ; au pass</i>. fermenter, HPC. <i>Acut. 394 ;</i> PLUT. <i>M. 659</i> b ; SPT. <i>Ex. 12, 34, 39 ;</i> NT. <i>Luc. 13, 21, etc. ; d’où</i> avoir un goût aigre (<i>propr</i>. de ferment) ALEX. (ATH. <i>383</i> d).<br><span><b>Étym</b>. ζύμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζυμοω - ζυμόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G2221":"<h1>zogreo</h1>\n<p>Strong n° 2221 <i>Prononciation [dzogue-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre vivant, faire prisonnier</li>\n<li>prendre, attraper, capturer, s'emparer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζωγρέω-ῶ,<br>   I</b> prendre vivant, <i>d’où :</i><br><b>      1</b> prendre et laisser la vie sauve, <i>càd</i>., faire prisonnier, <i>p. opp. à</i> tuer, <i>acc</i>. IL. <i>6, 46, etc. ;</i> HDT. <i>1, 86</i>, etc. ; THC. <i>2, 92</i>, μηδαμῇ μηδαμῶς ζ. PLAT. <i>Leg. 868</i> b, ne pas faire de quartier, sous aucun prétexte ; <i>en parl. de navires capturés avec leurs équipages,</i> CHARIT. <i>7, 6 ;</i><br><b>      2</b> <i>p. suite</i>, faire prisonnier, <i>en gén</i>., mettre en prison, HDT. <i>3, 52 ;</i><br><b>   II</b> rendre à la vie, ranimer, <i>acc</i>. IL. <i>5, 698</i>.<br><span><b>Étym</b>. ζωός, ἀγρέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζωγρεω - ζωγρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2222":"<h1>zoe</h1>\n<p>Strong n° 2222 <i>Prononciation [dzo-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vie\n<ol type=\"a\">\n<li>l'état de celui qui possède de la vitalité, ou qui est animé</li>\n<li>toute âme vivante</li>\n</ol>\n</li>\n<li>vie\n<ol type=\"a\">\n<li>la plénitude absolue de vie, à la fois essentielle et morale, qui appartient à Dieu, et à Christ dans lequel le « logos » a mis la nature humaine</li>\n<li>la vie réelle et véritable, une vie active et vigoureuse, vouée à Dieu, bénie, même dans ce monde, pour ceux qui mettent leur confiance en Christ, et qui aboutira, après la résurrection, à de nouvelles accessions, dans un corps parfait, et pour l'éternité.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζωή, ῆς (ἡ)</b> vie, <i>càd. :</i><br><b>      1</b> l’existence, la vie, PD. <i>N. 8, 61 ;</i> HDT. <i>1, 85, etc. ; p. opp. à</i> θάνατος, PD. <i>N. 9, 68 ;</i> PLAT. <i>Phæd. 71</i> d ; τοῦ βίου ζωή, PLAT. <i>Tim. 44</i> c, souffle de vie, vie ;<br><b>      2</b> temps de la vie, SPT. <i>Gen. 8, 13 ;</i><br><b>      3</b> genre de vie : ζόην (<i>ion</i>.) τὴν αὐτὴν ζῆν, HDT. <i>4, 112</i>, vivre du même genre de vie ;<br><b>      4</b> moyens de vivre, ressources, OD. <i>14, 96, 208, 429 ;</i> τὴν ζόην ποιεῖσθαι ἔκ τινος, HDT. <i>8, 105 ;</i> THCR. <i>Beren. 2</i>, se créer avec qqe ch. les moyens de vivre.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ζωά, PD. <i>ll. cc. Ion</i>. ζόη, HDT. <i>ll. cc. ;</i> SOPH. <i>fr. 500. Dor</i>. ζόα, EUR. <i>H.f. 664 ;</i> THCR. <i>Epigr. 17, 9. Éol</i>. ζοΐα, THCR. <i>Idyl. 29, 5</i>.<br><span><b>Étym</b>. ζάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζωη - ζωή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n134 fois dans 126 versets de 22 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (4)</li>\n<li>Luc (6)</li>\n<li>Jean (36)</li>\n<li>Actes (8)</li>\n<li>Romains (14)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (6)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (3)</li>\n<li>Colossiens (2)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (2)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (13)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (15)</li>\n</ul>\n</td></tr>\n</table>","G2223":"<h1>zone</h1>\n<p>Strong n° 2223 <i>Prononciation [dzo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une ceinture, servant à ceindre les vêtements flottants, mais également à transporter des pièces de monnaie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζώνη, ης (ἡ) :<br>   I</b> ceinture, <i>particul. :</i><br><b>      1</b> ceinture de femme, IL. <i>14, 181 ;</i> OD. <i>5, 231, etc. ;</i> HDT. <i>1, 51, etc. ;</i> ζώνην λύειν, OD. <i>11, 245 ; cf</i>. PLUT. <i>Lyc. 15</i>, délier la ceinture (de l’épouse), <i>le jour du mariage ;</i> ζώνην λύσασθαι, délier sa ceinture, <i>càd</i>. s’unir à son époux, ANTH. <i>7, 324 ; ou</i> accoucher, CALL. <i>Del. 209 ;</i> ζ. ἀπολύσασθαι, OPP. <i>C. 3, 56, ou</i> καταθέσθαι, PD. <i>O. 6, 66</i>, accoucher ; ὑπὸ ζώνην τινὰ φέρειν, ESCHL. <i>Ch. 992 ; ou</i> ὑπὸ ζώνης, EUR. <i>Hec. 762 ; ou</i> ἐντὸς ζώνης, ESCHL. <i>Eum. 608</i>, porter un enfant dans son sein (<i>litt</i>. sous sa ceinture) ; ὑπὸ ζώνῃ θέσθαι, HH. <i>Ven. 255</i>, concevoir ;<br><b>      2</b> ceinture d’homme, <i>particul. en parl. des Orientaux</i>, XÉN. <i>An. 4, 7, 16 ;</i> PLAT. <i>Hipp. mi. 368</i> c ; ATH. <i>443</i> b ; ζώνην λύειν, HDT. <i>8, 120</i>, délier sa ceinture, <i>càd</i>. se mettre à l’aise pour une halte, <i>en parl. de voyageurs ou de soldats ;</i> λαϐεῖν τινα τῆς ζώνης, XÉN. <i>An. 1, 6, 10 ;</i> DS. <i>17, 30</i>, saisir qqn par la ceinture (pour l’arrêter <i>ou</i> le conduire au supplice) ;<br><b>      3</b> ceinture où l’on met son argent, bourse, PLUT. <i>M. 665</i> b ; NT. <i>Marc. 6, 8 ;</i> κῶμαι εἰς ζώνην δεδομέναι, XÉN. <i>An. 1, 4, 9 ; cf</i>. PLAT. <i>1 Alc. 123</i> b, villages donnés (à une reine de Perse) pour sa bourse, <i>càd</i>. comme présent ;<br><b>      4</b> ceinture qui soutient le poignard, <i>en parl. des barbares, d’où</i> service militaire, ANTH. <i>11, 238 ;</i> οἱ ὑπὸ ζώνην, ANON. (SUID.) les soldats (<i>cf. franç</i>. sous le harnais) ;<br><b>      5</b> <i>p. ext</i>. région du corps où se place la ceinture, taille, <i>d’où</i> allure, démarche, IL. <i>2, 479 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> tout objet qui entoure comme une ceinture, PLUT. <i>M. 935</i> a ; LUC. <i>Musc. enc. 3 ;</i><br><b>      2</b> zone terrestre <i>ou</i> céleste (ζ. εὔκρατος, zone tempérée ; διακεκαυμένη, zone torride ; κατεψυγμένη, zone glaciale) CLÉM. <i>9, 22, 27, 28 ;</i> STR. <i>1, 2, 24 ; 1, 4, 6 ; 2, 1, 13 ; 2, 2, 2 ; 2, 3, 1 ; 4, 5, 5 Kram. ;</i> PLUT. <i>M. 888</i> c, <i>896</i> b ;<br><b>      3</b> frise, cordon, <i>t. d’arch</i>. PAUS. <i>5, 10, 5 ;</i><br><b>      4</b> zona, sorte d’herpès <i>ou</i> d’érysipèle autour des reins, MÉD.<br><span><b>Étym</b>. ζώννυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζωνη - ζώνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Actes (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2224":"<h1>zonnumi</h1>\n<p>Strong n° 2224 <i>Prononciation [dzone'-noo-mi]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ceindre</li>\n<li>se ceindre soi-même</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζώννυμι</b> <span>(<i>f</i>. ζώσω, <i>ao</i>. ἔζωσα, <i>pf</i>. ἔζωκα ; <i>pass. ao</i>. ἐζώσθην, <i>pf</i>. ἔζωμαι, <i>mieux que</i> ἔζωσμαι, <i>pl.q.pf</i>. ἐζώσμην)</span> ceindre, <i>particul. pour le combat</i>, OD. <i>18, 75 ; pour une marche,</i> NT. <i>Joh. 21, 18 ;</i> ζ. τινά τι, SPT. <i>Lev. 817 ; 1Reg. 17, 39</i>, ceindre qqn de qqe ch. (d’une ceinture, <i>etc</i>.) ; <i>fig</i>. ζ. γαῖαν, ANTH. <i>9, 778</i>, ceindre la terre, <i>en parl. de l’Océan ;</i><br><b><i>Moy</i>. ζώννυμαι</b> <i>plus us</i>. <span>[ῠ]</span> <span>(<i>f</i>. ζώσομαι, <i>ao</i>. ἐζωσάμην)</span><br><b>      1</b> se ceindre <i>pour le combat ou pour la marche</i>, IL. <i>23, 685, etc. ;</i> OD. <i>24, 89 ;</i> ζωστῆρι, IL. <i>10, 78</i>, de son baudrier ; τὰς κοιλίας ζώναις, THPP. (ATH. <i>443</i> b) s’entourer le ventre d’une ceinture ;<br><b>      2</b> ceindre pour soi : ζώνην, IL. <i>14, 181 ;</i> μίτρην, IL. <i>5, 857</i>, ceindre une ceinture ; χαλκόν, IL. <i>23, 130</i>, ceindre son épée ; χιτῶνα, CALL. <i>Dian. 12 ;</i> PLUT. <i>Ant. 4</i>, s’envelopper d’une tunique.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. réc</i>. ζώσω, SPT. <i>Ex. 29, 9 ;</i> NT. <i>Joh. 21, 18. Ao</i>. ἔζωσα, A. RH. <i>1, 368 ;</i> SPT. <i>Ezech. 16, 10 ; épq</i>. ζῶσα, HÉS. <i>Th. 573. Pf. réc</i>. ἔζωκα, ANTH. <i>9, 778 ;</i> PAUS. <i>8, 40. Pass. moy. impf. poét</i>. ζωννύμην, IL. <i>10, 78 ; 2 sg</i>. ἐζώννυσο, NONN. <i>Jo. 21, 18. Impf. itér. 3 sg</i>. ζωννύσκετο, IL. <i>5, 857. Fut. réc</i>. ζώσομαι, THÉON <i>Prog. 124, 2. Ao</i>. ἐζωσάμην, COL. <i>207 ; épq</i>. ζωσάμην, IL. <i>14, 181 ;</i> OD. <i>18, 67 ;</i> HÉS. <i>O. 345. Pf. pass. ion</i>. ἔζωσμαι, HPC. <i>4, 134 Littré ; dans les inscr. att</i>. ἔζωμαι (<i>non</i> ἔζωσμαι) <i>seul. dans les composés : 3 sg</i>. ὑπέζωται, CIA. <i>2, 802, b, 27, c, 7 (349 av. J.C</i>.) ; διέζωται <i>et part. fém</i>. διεζωμέναι, CIA. <i>2, 736, b, 19, 16 (307 av. J.C</i>.) ; <i>v. Meisterh. p. 148, § 69, 3</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ieh₃s-, ceindre ; <i>cf. lituanien</i> juosti, <i>avestique</i> yāsta- = ζωστός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζωννυμι - ζώννυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2225":"<h1>zoogoneo</h1>\n<p>Strong n° 2225 <i>Prononciation [dzo-og-on-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apporter la vie, faire vivre</li>\n<li>donner la vie, engendrer</li>\n<li>préserver vivant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζωογονέω-ῶ :<br>   I</b> produire un être vivant, <i>d’où</i> engendrer des êtres vivants, TH. <i>C.P. 3, 22, 3 ; particul. en parl. de Zeus faisant sortir de sa tête Pallas vivante</i>, LUC. <i>D. deor. 8 ;</i><br><b>   II.1</b> rendre vivant, faire vivre, TH. <i>C.P. 4, 15, 2 ; au pass</i>. recevoir la vie, vivre, ARSTT. <i>fr. 294 ;</i> ISID. CHAR. (ATH. <i>93</i> d) ;<br><b>      2</b> conserver vivant, SPT. <i>Ex. 1, 17, 18 et 22 ; Judith 8, 19 ; 1Reg. 27, 9 et 11 ; 2Reg. 7, 4 ;</i> NT. <i>Luc. 17, 33 ;</i><br><b>      3</b> faire revivre, SPT. <i>1Reg. 2, 6</i>.<br><span><b>Étym</b>. ζωογόνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζωογονεω - ζῳογονέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2226":"<h1>zoon</h1>\n<p>Strong n° 2226 <i>Prononciation [dzo'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un être vivant</li>\n<li>un animal, une brute, une bête</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζῷον, ου (τὸ) :<br>      1</b> tout être vivant : πᾶν ὅ τι περ ἂν μετάσχῃ τοῦ ζῆν ζῷον ἂν λέγοιτο, PLAT. <i>Tim. 77</i> b, tout ce qui participe à la vie (τοῦ ζῆν) pourrait être appelé animal (ζῷον) ; AR. <i>Vesp. 551, etc. ; particul</i>. animal, <i>p. opp. aux plantes</i>, PLAT. <i>Phæd. 70</i> d, <i>110</i> e, <i>ou aux arbres</i>, PLAT. <i>Soph. 233</i> e ; <i>en parl. des hommes et des animaux, p. opp. aux reptiles,</i> PD. <i>O. 7, 95 ;</i><br><b>      2</b> <i>p. ext</i>. personnage <i>ou</i> figure (d’homme <i>ou</i> d’animal) représentés dans un tableau, HDT. <i>3, 88, etc. ;</i> PLAT. <i>Rsp. 515</i> a ; ζῷα ποιεῖν, PLUT. <i>Per. 13</i>, peindre <i>ou</i> représenter des figures, des personnages ; <i>même en parl. d’objets inanimés</i>, HDT. <i>1, 70 et 203 ; 2, 124 ; 3, 47 ;</i> PLAT. <i>Leg. 769</i> a ; ζῷα γραψάμενος (= ζωγραφησάμενος) τὴν ζεῦξιν τοῦ Βοσπόρου, HDT. <i>4, 88</i>, ayant représenté d’après nature le passage du Bosphore (le roi, l’armée).<br><span><b><span class=\"arrow\"></span></b> ζῷον (<i>non</i> ζῶον) CIA. <i>2, 701, 1, 81 (344 av. J.C.) ; v. Meisterh. p. 51, 8</i>.<br><span><b>Étym</b>. <i>contr. de</i> ζώϊον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζωον - ζῷον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n23 fois dans 20 versets de 4 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (20)</li>\n</ul>\n</td></tr>\n</table>","G2227":"<h1>zoopoieo</h1>\n<p>Strong n° 2227 <i>Prononciation [dzo-op-oy-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>produire la vie, engendrer ou porter un enfant</li>\n<li>donner la vie\n<ol type=\"a\">\n<li>vivifier par une puissance spirituelle</li>\n<li>rendre à la vie, ramener à la vie</li>\n<li>donner une meilleure vie en ce qui concerne la vie physique</li>\n<li>vie de l'esprit, revêtue de nouveaux et plus grands pouvoirs</li>\n</ol>\n</li>\n<li>métaph., la semence qui vient dans une vie, qui germe, qui pousse, qui croît</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζωοποιέω-ῶ :<br>      1</b> rendre vivant, animer, SPT. <i>4Reg. 5, 7 ; Neh. 9, 6 ; Ps. 70, 20 ;</i><br><b>      2</b> engendrer des êtres vivants, ARSTT. <i>H.A. 5, 27, 3 ; G.A. 1, 21, 8</i>.<br><span><b>Étym</b>. ζωοποιός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζωοποιεω - ζῳοποιέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 11 versets de 7 livres bibliques (NT)\n<ul>\n<li>Jean (3)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2228":"<h1>e</h1>\n<p>Strong n° 2228 <i>Prononciation [ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'un ou l'autre, ou, que</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>Η, η</b> (ἦτα) êta, <i>7<sup>e</sup> lettre de l’alphabet grec. Comme chiffre</i> ηʹ <i>= 8 ;</i> ͵η <i>= 8 000. L'</i>Η <i>était primitivement le signe de l’aspiration rude (p. suite, il vaut 100 dans de vieilles inscriptions, à cause de l’esprit rude de</i> ἑκατόν) ; <i>des deux moitiés de l’</i>Η, <i>l’une</i> ┣, <i>d’où</i> ῾, <i>a désigné l’esprit rude, l’autre</i> ┫, <i>d’où</i> ᾿, <i>l’esprit doux</i>.<br><br>\n➁ <b>ᾖ</b>, <i>3 sg. sbj. de</i> .<br><br>\n➂ <b>ἡ</b>, <i>fém. de l’art</i>. ὁ.<br><br>\n➃ <b>ἥ</b>, <i>fém. du relat</i>. ὅς.<br><br>\n➄ <b>ᾗ, <i>adv</i>.<br>      1</b> (<i>avec idée de lieu</i>) par où : ᾗ ἔμελλον οἱ Ἕλληνες παριέναι, XÉN. <i>An. 3, 4, 37,</i> par où les Grecs devaient s’avancer ; <i>cf</i>. IL. <i>13, 53, etc. ; en corrélat. avec</i> τῇ <i>antérieur,</i> IL. <i>15, 46 ;</i> SOPH. <i>El. 1435 ; avec</i> τῇδε, ESCHL. <i>Ch. 308 ; avec</i> ἐκείνῃ, PLAT. <i>Phæd. 82</i> d ; <i>qqf. suivi d’un gén. :</i> ᾗ ἕκαστος ἐτύγχανε τοῦ νάπους ὤν, XÉN. <i>An. 6, 3, 22,</i> dans la partie du bois où chacun se trouvait ;<br><b>      2</b> (<i>avec idée de manière</i>) de la manière que, selon que, comme : ᾗ Λοξίας ἐφήμισεν, ESCHL. <i>Ch. 558,</i> comme l’a prédit Loxias ; λουτροῖς τέ νιν ἐσθῆτί τ' ἐξήσκησαν, ᾗ νομίζεται, SOPH. <i>O.C. 1603,</i> elles le baignèrent et le parèrent de vêtements, comme c’est l’usage ; ᾗ βούλονται, THC. <i>8, 71,</i> à leur volonté ; ᾗ δυνατόν, autant qu’il est possible (<i>v</i>. δυνατός) ; <i>surt. avec un sup. :</i> ᾗ ἂν δύνωμαι τάχιστα, XÉN. <i>Cyr. 7, 1, 9,</i> le plus vite que je pourrai ; ᾗ ἐδύνατο τάχιστα, XÉN. <i>An. 1, 2, 4,</i> aussi vite qu’il était possible ; ᾗ δυνατὸν μάλιστα, XÉN. <i>An. 1, 3, 15,</i> le plus possible ; ᾗ ἄριστον, XÉN. <i>Cyr. 2, 4, 32,</i> le mieux possible ;<br><b>      3</b> autant que : ᾗ ὁ μὲν ἑκὼν φάγοι, XÉN. <i>Mem. 2, 1, 18,</i> autant qu’il voudrait bien manger ; ᾗ ἄνθρωπος, ARSTT. <i>Nic. 1, 6, 5,</i> en tant qu’homme.<br><span><b>Étym</b>. <i>dat. sg. fém. du relat</i>. ὅς.</span><br><br>\n➅ <b>ἤ</b>, <i>conj. ;</i><br><b>A</b> ou :<br><b>   I</b> <i>entre deux mots d’une même prop. :</i> χρηστὸς ἢ πονηρός, PLAT. <i>Prot. 313</i> a, bon ou méchant ; βελτίους ἢ χείρους, PLAT. <i>Rsp. 335</i> b, meilleurs ou pires ; σὺν τρισὶν ἢ τέτταρσι, XÉN. <i>An. 1, 8, 12,</i> avec trois ou quatre ; <i>qqf. dev. chacun des deux mots corresp. :</i> ἤ τις ἢ οὐδείς, HDT. <i>3, 140,</i> ou quelqu’un ou personne ; ἢ σέ γε Μοῦσ' ἐδίδαξε Διὸς παῖς, ἢ σέ γ' Ἀπόλλων, OD. <i>8, 488,</i> soit que tu aies eu pour t’enseigner la Muse, fille de Zeus, ou Apollon ; <i>répété trois ou quatre fois :</i> ἢ Ἀπόλλων ἢ Πὰν ἢ Ζεύς, ESCHL. <i>Ag. 55,</i> ou Apollon ou Pan ou Zeus ; γεωργὸς ἢ ἱππεὺς ἢ ἰατρὸς ἢ αὐλητὴς ἢ ἄλλ' ὁτιοῦν, XÉN. <i>Cyr. 1, 6, 22,</i> (si tu veux être) laboureur ou cavalier, ou médecin, ou joueur de flûte, ou n’importe quoi autre chose ; <i>qqf. avec</i> ἠέ <i>au lieu de</i> ἤ <i>au dernier terme :</i> τὸν δέ τις ἀθανάτων βλάψε φρένας, ἠέ τις ἀνθρώπων, OD. <i>14, 178,</i> quelque immortel ou quelqu’un parmi les hommes a troublé sa raison ; <i>de même</i> ἢ… ἠέ, IL. <i>15, 502 ;</i> ἢ… ἢ… ἢ… ἠέ, IL. <i>1, 145 ;</i> ἤ <i>peut être suivi de</i> καί <i>au dernier terme :</i> ἀλλ' ἄγε δή τινα μάντιν ἐρείομεν ἢ ἱερῆα ἢ καὶ ὀνειροπόλον, IL. <i>1, 62,</i> mais voyons, consultons donc un devin ou un prêtre, ou même un interprète de songes ;<br><b>   II</b> <i>entre deux prop. (dans cette construct</i>. ἤ <i>a souv. le sens de</i> ou alors, sinon) : ὅπως καὶ ὑμεῖς ἐμὲ ἐπαινέσετε, ἐμοὶ μελήσει, ἢ μηκέτι με Κῦρον νομίζετε, XÉN. <i>An. 1, 4, 16,</i> j’aurai à cœur que vous aussi ayez à vous louer de moi, ou alors croyez que je ne suis plus Cyrus ; ἔργον γε οὐδαμοῦ ληπτέον, ἢ εὐθὺς ἐλεγχθήσεται γελοῖος ὤν, XÉN. <i>Mem. 1, 7, 2,</i> il devra ne se mettre à l’œuvre nulle part, ou la preuve sera bientôt faite qu’il est ridicule ; <i>dev. les deux prop. corrél. :</i> ἢ παντάπασιν ἀμαχεὶ λάϐοιμεν ἂν τὸ ἄκρον ἢ ὀλίγοις τε καὶ ἀσθενέσι χρησαίμεθ' ἂν πολεμίοις, XÉN. <i>Cyr. 3, 2, 4,</i> ou nous pourrions prendre la hauteur absolument sans combat, ou nous aurions affaire à un ennemi peu nombreux et peu solide ; <i>en ce cas</i> ἤτοι <i>se substitue qqf. à</i> ἤ <i>au commenc. de la première prop. :</i> ἤτοι… ἤ, ESCHL. <i>Ag. 662 ;</i> SOPH. <i>Ant. 1182, etc</i>. ou… ou ; <i>et en poésie (mais non chez les Att.) au commenc. de la seconde :</i> ἢ… ἤτοι, PD. <i>N. 6, 8 ; fr. 103 (les Att. n’admettent</i> ἤτοι <i>au commenc. du second membre que si le premier ne commence pas par</i> ἤ, EUR. <i>Antiop. fr. 223, 9 Kannicht conj., v. Henri Weil, Revue des Études Grecques, t. 3, n° 12, 1890, p. 482</i>) ;<br><b>   III</b> <i>dans les prop. d’interrogation directe pour marquer le second terme d’une alternative, en corrélat. :</i><br><b>      1</b> <i>avec un premier membre sans particule interr</i>. τί χρή με στέγειν ἢ τί λέγειν πρὸς ἄνδρ' ὑπόπταν ; SOPH. <i>Ph. 136,</i> que dois-je cacher ou que dois-je dire à un homme défiant? <i>cf</i>. ESCHL. <i>Ch. 314 ;</i> SOPH. <i>O.R. 378, 1162 ;</i><br><b>      2</b> <i>avec un premier membre commenç. par</i> πότερον <i>ou</i> πότερα : πότερον ἐκείνους πάλιν καλῶμεν, ἢ ἐμοὶ ταῖσδέ τ' ἐξειπεῖν θέλεις ; SOPH. <i>Tr. 342,</i> devons-nous rappeler les autres, ou veux-tu t’expliquer seulement devant moi et ceux-ci? <i>de même</i> πότερα… ; PLAT. <i>Prot. 324</i> d ; <i>avec</i> πότερα <i>suivi des deux termes d’une alternative dont le second est annoncé par</i> ἤ, <i>puis d’un autre</i> ἤ <i>marquant une nouvelle alternative par oppos. aux deux termes réunis de la première :</i> πότερα δ' ἐν οἴκοις ἢ ἐν ἀγροῖς ὁ Λάϊος ἢ γῆς ἐπ' ἄλλης συμπίπτει φόνῳ ; SOPH. <i>O.R. 112,</i> est-ce (dans son pays) en sa demeure ou à la campagne, ou sur une terre étrangère que Laïos a succombé par un meurtre? ;<br><b>   IV</b> <i>dans les prop. d’interr. indir. :</i><br><b>      1</b> <i>avec</i> εἰ : εἰδῶμεν εἰ νικῶμεν ἢ νικώμεθα, ESCHL. <i>Ch. 890,</i> sachons si nous sommes vainqueurs ou vaincus ; νῦν ἔμαθον ὃ λέγεις· εἰ δὲ ἀληθὲς ἢ μή, πειράσομαι μαθεῖν, PLAT. <i>Rsp. 339</i> a, maintenant je sais ce que tu dis ; seulement cela est-il vrai ou non? c’est ce que je vais tâcher de savoir ;<br><b>      2</b> <i>avec un premier</i> ἤ : μερμήριξε ἢ Διὸς υἱὸν διώκοι, ἢ ὅγε Λυκίων ἀπὸ θυμὸν ἕλοιτο, IL. <i>5, 671,</i> il hésita s’il poursuivrait le fils de Zeus ou s’il ferait périr des Lyciens ; <i>après les verbes qui marquent le doute ou une éventualité incertaine, après</i> δίζε, IL. <i>16, 713 ; après la locut</i>. μετὰ φρεσὶ νόησον, IL. <i>20, 311 ; après</i> πειρηθῆναι, IL. <i>21, 226 ; après</i> ὁρμαίνω, OD. <i>15, 300 ; cf</i>. IL. <i>2, 300 ; 4, 15 ;</i> OD. <i>6, 142 ; 15, 300, etc. ;</i><br><b>      3</b> <i>avec un premier terme sans particule interr. :</i> οὐδέ τι ἴδμεν ζώει ὅγ' ἢ τέθνηκεν, OD. <i>4, 110,</i> et nous ignorons absolument s’il vit ou s’il est mort ; <i>cf</i>. ESCHL. <i>Pr. 782, etc. ;</i><br><b>      4</b> <i>en sous-entendant tout le premier membre d’une alternative :</i> τίπτ' εἰλήλουθας ; ἢ ἵνα ὕϐριν ἴδῃ Ἀγαμέμνονος ; IL. <i>1, 203,</i> pourquoi es-tu venue? est-ce (pour quelque autre chose? ou) pour voir l’outrage que m’a fait Agamemnon? <i>cf</i>. IL. <i>5, 466 ; 7, 26 ;</i> OD. <i>4, 710 ; 13, 376 (ttef. sel. les plus réc. éditeurs</i> ἦ <i>au lieu de</i> ἤ <i>dans tous ces passages</i>) ; τίς σοι διηγεῖτο ; ἢ αὐτὸς Σωκράτης ; PLAT. <i>Conv. 173</i> a, qui causait avec toi? n’était-ce pas Socrate en personne? (<i>litt</i>. était-ce un autre ou Socrate lui-même?) ; <i>particul. dans la locut. interr</i>. ἢ οὐκ (<i>au sens du lat</i>. nonne?) ἢ οὐκ ὀτρύνοντος ἀκούετε λαὸν ἅπαντα Ἕκτορος ; IL. <i>15, 506,</i> n’entendez-vous pas (<i>litt</i>. entendez-vous ou non) Hector qui pourchasse toute la foule (des Grecs) ? <i>cf</i>. IL. <i>5, 349 ; 23, 670 ;</i> PLAT. <i>Rsp. 370</i> b, <i>etc. ; qqf. avec le premier membre de l’alternative exprimé (cf. en lat. la prop. qui précède</i> annon) : ἔξεστι… ἢ οὐ ; NT. <i>Matth. 22, 17,</i> est-il permis… ou non? ;<br><b>B</b> que :<br><b>   I</b> <i>après un comparatif :</i> τὸν τοῦ ἀδίκου βίον φάσκων εἶναι κρείττω, ἢ τὸν τοῦ δικαίου, PLAT. <i>Rsp. 347</i> e, prétendant que la vie de l’homme injuste est préférable à celle du juste ; <i>qqf. par attraction et au lieu du nominatif, avec le même cas après</i> ἤ <i>qu’avant :</i> πηγαὶ ἑτέρου ποταμοῦ οὐκ ἐλάσσονος ἢ Μαιάνδρου (<i>au lieu de</i> Μαίανδρος) HDT. <i>7, 26,</i> les sources d’un autre fleuve non moindre que le Méandre ; <i>— entre deux adj. au comparatif :</i> στρατηγοὶ πλείονες ἢ βελτίονες, AR. <i>Ach. 1042,</i> généraux plus nombreux qu’habiles ; <i>cf</i>. OD. <i>1, 165 ;</i> HDT. <i>3, 65 ;</i> PLAT. <i>Rsp. 409</i> d, <i>Theæt. 144</i> b, <i>etc. ; de même avec deux adj. employés adverb. au comparatif :</i> φορτικώτερον ἢ φιλοσοφώτερον διαλέγεσθαι, PLUT. <i>Sol. 3,</i> discourir avec plus de licence blâmable que d’esprit philosophique ; <i>— qqf. sous-entendu après un comparatif devant un n. de nombre précédé d’une nég. :</i> ἀποκτείνουσιν οὐ μεῖον πεντακοσίους, XÉN. <i>An. 6, 2, 24,</i> ils n’en tuent pas moins de cinq cents (<i>litt</i>. cinq cents, pas moins) ; ἔτη μὴ ἔλαττον ἑξήκοντα γεγονώς, PLAT. <i>Leg. 759</i> d, n’étant pas âgé de moins de soixante ans ; <i>cf</i>. PLAT. <i>Ap. 17</i> d, <i>etc. ;</i><br><b>   II</b> <i>après un mot marquant une idée de comparaison, avec les verbes tels que</i> αἱρέομαι, βούλομαι… ἤ, j’aime mieux, je préfère… plutôt que, etc. (<i>v. ces mots</i>) ; φθάνειν ἤ, IL. <i>23, 445 ;</i> OD. <i>11, 58,</i> venir plus vite que ; ἐπιθυμεῖν ἤ, XÉN. <i>Cyr. 1, 4, 3,</i> désirer… plutôt que ; <i>après les adjectifs tels que</i> ἄλλος, ἕτερος, ἀντίος, ἐναντίος, ἴδιος, <i>etc. et les adverbes correspondants (v. ces mots</i>) ; <i>après les adj. et les adv. multiplicatifs :</i> διπλάσιος, πολλαπλάσιος, <i>etc. (v. ces mots</i>) ; <i>après les locut. marquant une idée de comparaison telles que :</i> οὐδ' ὅσον ἤ, THCR. <i>Idyl. 9, 21,</i> non autant que ; <i>particul. celles qui expriment une idée de temps :</i> πρὶν ἤ, πρόσθεν ἤ (<i>v. ces mots</i>) ; τῇ ὑστεραίᾳ ἤ, PLAT. <i>Conv. 173</i> a, le lendemain du jour où (<i>v</i>. ὑστεραῖος). <i>À ces construct. se rattache la loc. interr</i>. ἄλλο τι ἤ, <i>par laquelle on exclut, à l’aide de</i> ἄλλο, <i>toutes les suppositions contraires à celle que l’on regarde comme la seule vraisemblable et qui se trouve exprimée après</i> ἤ : ἄλλο τι ἢ περὶ πολλοῦ ποιεῖ ὅπως ὡς βέλτιστοι οἱ νεώτεροι ἔσονται ; PLAT. <i>Ap. 24</i> c, que fais-tu autre chose (<i>litt</i>. fais-tu qqe ch. autre) sinon tâcher de rendre les jeunes gens les meilleurs possible? <i>cf</i>. XÉN. <i>An. 2, 5, 10 ; 4, 7, 5, etc. Dans ces construct</i>. ἤ <i>se trouve qqf. suivi de diverses particules, par exemple : de</i> οὐ : ἢ οὐ, <i>au sens de</i> ἤ <i>seul :</i> ἐγνῶσθαι πόλιν ὅλην διαφθεῖραι μᾶλλον ἢ οὐ τοὺς αἰτίους, THC. <i>3, 36,</i> (la décision par laquelle) ils avaient condamné à périr une ville entière au lieu de frapper seulement les coupables (<i>v</i>. οὐ) ; <i>de</i> κατά : τὸ μὲν πρόσωπον καλλωπιζόμενον περιεργότερον ἢ κατὰ γυναῖκα σώφρονα, HDN <i>5, 8, 1,</i> le visage paré avec plus de soin qu’il ne convenait à une honnête femme (<i>v</i>. κατά) ; <i>de</i> ὡς <i>ou</i> ὥστε : μείζω ἢ ὡς τῷ λόγῳ τις ἂν εἴποι, DÉM. <i>68, 20,</i> actions trop grandes pour qu’on les puisse retracer par la parole, <i>etc</i>. (<i>v</i>. ὡς, ὥστε) ;<br><b>   III</b> <i>p. suite, après un posit. :</i> ὑμέας δίκαιον ἔχειν (<i>s.-e</i>. μᾶλλον) ἤ περ Ἀθηναίους, HDT. <i>9, 26,</i> il est juste que vous l’ayez plutôt que les Athéniens ; ἐμοὶ πικρὸς τέθνηκεν (<i>s.-e</i>. μᾶλλον) ἢ κείνοις γλυκύς, SOPH. <i>Aj. 966,</i> sa mort m’est amère plus qu’elle ne leur est douce ;<br><b>   IV</b> <i>après un superl. :</i> ἡ Αἴγυπτος πλεῖστα θωυμάσια ἔχει ἢ ἄλλη πᾶσα χώρη, HDT. <i>2, 35,</i> l’Égypte possède plus de choses merveilleuses qu’aucun autre pays ; πίθοιτό κεν ὔμμι μάλιστα ἢ ἐμοί, A. RH. <i>3, 91,</i> il vous écouterait plutôt que moi.<br><span><b>Étym</b>. <i>contraction de</i> ἠέ.</span><br><br>\n➅ <b>ἤ</b>, <i>exclamation pour appeler l’attention ;</i> ἢ ἢ σιώπα, AR. <i>Nub. 105</i> (ἠή <i>Dind</i>.) hé! silence.<br><br>\n➆ <b>ἦ</b>, <i>1 et 3 sg. impf. de</i> εἰμί.<br><i>3 sg. impf. de</i> ἠμί.<br><br>\n➇ <b>ἥ</b>, <i>particule épq</i>. comme, <i>dans la locut</i>. ἣ θέμις ἐστί, IL. <i>2, 73 ;</i> OD. <i>3, 45, etc</i>. comme c’est la règle.<br><br>\n➈ <b>ᾗ, 1</b> <i>dat. fém. du relat</i>. ὅς, ἥ, ὅ. ;<br><b>2</b>, <i>dat. sg. fém. de l’adj. possess</i>. ὅς <i>p</i>. ἑός.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">η - ἤ</font>\n<br><br>particule de distinction entre deux termes liés</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n351 fois dans 278 versets de 24 livres bibliques (NT)\n<ul>\n<li>Matthieu (69)</li>\n<li>Marc (31)</li>\n<li>Luc (46)</li>\n<li>Jean (12)</li>\n<li>Actes (37)</li>\n<li>Romains (29)</li>\n<li>1 Corinthiens (52)</li>\n<li>2 Corinthiens (12)</li>\n<li>Galates (8)</li>\n<li>Ephésiens (7)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (5)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (7)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (2)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (4)</li>\n<li>Jacques (6)</li>\n<li>1 Pierre (8)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (6)</li>\n</li>\n</ul>\n</td></tr>\n</table>","G2229":"<h1>e</h1>\n<p>Strong n° 2229 <i>Prononciation [ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>assurément, très certainement, tout à fait sûrement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἦ, <i>adv</i>.<br>      1</b> certes, sans doute, IL. <i>1, 229 ;</i> OD. <i>17, 371 ; joint à d’autres particules :</i> ἦ ἄρα, OD. <i>24, 193 ;</i> ἦ ἄρα δή, IL. <i>13, 446 ;</i> ἦ ἄρ, IL. <i>19, 56 ;</i> ἦ ῥα, IL. <i>16, 750 ;</i> ἦ ῥά νυ, IL. <i>12, 164 ;</i> ἦ δή, IL. <i>1, 518, etc. ;</i> ἦ δὴ μάν, IL. <i>17, 538 ;</i> ἦ δή που, IL. <i>21, 583 ;</i> ἦ μάν, IL. <i>2, 370 ; 13, 354 ;</i> ἦ μέν, IL. <i>1, 77 ; 14, 275 ;</i> ἦ μὲν δή, IL. <i>2, 798 ;</i> OD. <i>18, 257 ;</i> ἦ τε, IL. <i>11, 362 ;</i> ἦ θήν, IL. <i>13, 813, m. sign. ;</i> ἦ κάρτα, ESCHL. <i>Ag. 528, 1225 ;</i> SOPH. <i>Aj. 1338,</i> certes, tout à fait ; ἦ μάλα, IL. <i>3, 204 ; 18, 18 ;</i> OD. <i>16, 183, etc. m. sign. ;</i> ἦ μάλα δή, IL. <i>8, 102 ;</i> OD. <i>9, 507, m. sign. ;</i> ἦ γάρ, IL. <i>1, 232, 293, etc</i>. certes en effet ; <i>surt</i>. ἦ μήν, certes, en vérité, <i>qui s’emploie comme formule d’affirmation dans les serments, avec un inf. fut</i>. IL. <i>1, 77 ;</i> ESCHL. <i>Sept. 513 ;</i> XÉN. <i>An. 2, 3, 26 ; avec un inf. ao</i>. XÉN. <i>An. 2, 4, 17, etc. ;</i><br><b>      2</b> <i>avec interrog</i>. est-ce que ? <i>dans Hom. d’ord. après une prop. interr</i>. IL. <i>1, 203 ; 3, 400, etc. ;</i> OD. <i>4, 682, etc. ; qqf. sans prop. interr. antér</i>. IL. <i>5, 421, 762 ;</i> OD. <i>1, 158, etc. ; qqf. pour marquer une idée de colère ou de raillerie :</i> ἦ μοῦνοι φιλέουσ' ἀλόχους Ἀτρεῖδαι ; IL. <i>9, 340,</i> les Atrides sont-ils donc seuls à aimer leurs compagnes? <i>cf</i>. IL. <i>13, 446 ; 14, 265 ; 15, 132, etc. ; avec d’autres particules :</i> ἦ ῥα, IL. <i>5, 421, 762 ;</i> OD. <i>4, 672, etc. ;</i> ESCHL. <i>Pers. 633 ;</i> SOPH. <i>Aj. 172, 964 ;</i> ἦ ῥά νυ, IL. <i>4, 93 ;</i> ἦ ῥά γε, THCR. <i>Idyl. 4, 53 ;</i> ἦ ῥά γέ τοι, THCR. <i>Idyl. 2, 20 ; 3, 8,</i> est-ce que? ἦ ταῦτα δή, SOPH. <i>Ph. 565 ; El. 385 ;</i> ἦ ταῦτα δῆτα, SOPH. <i>O.R. 429, m. sign. ;</i> ἦ οὐ, ἦ οὐκ ; (<i>lat</i>. nonne?) IL. <i>15, 506 ;</i> OD. <i>16, 424 ;</i> THCR. <i>Idyl. 5, 116,</i> est-ce que… ne? ἦ μή, OD. <i>6, 200 ; 9, 405, m. sign</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les deux sens</i> ἦ <i>commence toujours la prop. ; dans Hom. et les poètes att., il peut se placer après un voc</i>. IL. <i>5, 425, 762 ;</i> OD. <i>4, 632 ;</i> SOPH. <i>O.C. 864, 1102</i>.<br><span><b>Étym</b>. <i>incert., cf. p.-ê</i>. ἤ 1.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">η - ἦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2230":"<h1>hegemoneuo</h1>\n<p>Strong n° 2230 <i>Prononciation [hayg-em-on-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être le chef, conduire la marche</li>\n<li>diriger, commander, conduire\n<ol type=\"a\">\n<li>être gouverneur d'une province</li>\n<li>se dit d'un proconsul (vice-consul)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡγεμονεύω<br>   I</b> être le guide de : τινί, OD. <i>3, 386 ;</i> HÉS. <i>Th. 387, etc</i>. de qqn ; ὁδόν, OD. <i>6, 261 ;</i> PD. <i>O. 6, 42,</i> montrer le chemin ; τινὶ ὁδόν, OD. <i>24, 225,</i> montrer à qqn le chemin (<i>propr</i>. marcher devant qqn pour lui montrer le chemin) ; ῥόον ὕδατι ἡγ. IL. <i>21, 258,</i> tracer à l’eau un courant ;<br><b>   II</b> <i>p. suite :</i><br><b>      1</b> conduire, diriger, commander : τινός, IL. <i>2, 527, etc. ;</i> HDT. <i>7, 99, etc. ;</i> XÉN. <i>Ages. 1, 3, etc. ; avec le dat</i>. τινί, IL. <i>2, 816,</i> qqn ; <i>abs</i>. HDT. <i>8, 2 ;</i> PLAT. <i>Rsp. 474</i> c ; <i>d’où au pass</i>. ἡγεμονεύεσθαι ὑπό τινος, THC. <i>3, 61,</i> être sous la domination de qqn ; <i>fig</i>. ἡγεμονεύειν ἐπιθυμίας καὶ ἔρωτος, PLAT. <i>Pol. 197</i> a, maîtriser ses désirs et les besoins des sens ; ἡγ. τῆς σκέψεως, PLAT. <i>Prot. 351</i> e, diriger la recherche ;<br><b>      2</b> <i>particul</i>. être gouverneur : τῆς Συρίας, NT. <i>Luc. 2, 2,</i> de la Syrie.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. dor</i>. ἁγεμόνευον <span>[ᾱ]</span> THCR. <i>Idyl. 11, 27 ; ao. inf. dor</i>. ἁγεμονεῦσαι <span>[ᾱγ]</span> PD. <i>O. 6, 42 ; 9, 5</i>.<br><span><b>Étym</b>. ἡγεμών.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηγεμονευω - ἡγεμονεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G2231":"<h1>hegemonia</h1>\n<p>Strong n° 2231 <i>Prononciation [hayg-em-on-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>commandement suprême, autorité, souveraineté, pouvoir absolu\n<ol type=\"a\">\n<li>le règne d'un empereur Romain</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡγεμονία, ας (ἡ) :<br>A</b> action de marcher en tête, de guider, de conduire, HDT. <i>2, 93 ; fig</i>. direction : τῇ τῶν δυναστευόντων ἡγεμονίᾳ, PLAT. <i>Leg. 711</i> c, par l’exemple des puissants ;<br><b>B</b> <i>p. suite, fig. :</i><br><b>   I</b> direction, autorité, prééminence, HDT. <i>1, 7 ; 3, 65, etc. ; en parl. de l’autorité d’un chef militaire,</i> THC. <i>4, 91 ;</i> XÉN. <i>An. 4, 7, 8 ;</i> PLAT. <i>Euthyd. 273</i> c ;<br><b>   II</b> <i>particul. dans la constitution des États grecs,</i> ἡ ἡγ. τῆς Ἑλλάδος, XÉN. <i>Hell. 7, 1, 33 ;</i> ARSTT. <i>Pol. 4, 11, 18 ; abs</i>. ἡ ἡγ. ARSTT. <i>Pol. 5, 4, 8 ;</i> ἡ ἡγ. τῶν Ἑλλήνων, POL. <i>1, 2, 3,</i> prééminence <i>ou</i> souveraineté d’un État grec sur toute la Grèce, sur les Grecs, hégémonie ;<br><b>   III</b> <i>à Rome :</i><br><b>      1</b> pouvoir absolu, <i>d’où</i> règne d’un empereur, NT. <i>Luc. 3, 1 ;</i><br><b>      2</b> commandement d’un chef de corps, <i>d’où</i> corps de troupes, division militaire, PLUT. <i>Cam. 23 ;</i><br><b>      3</b> principauté, préfecture, gouvernement, SPT. <i>Gen. 36, 30 ;</i> HDN <i>6, 7 ;</i><br><b>      4</b> magistrature, <i>en gén</i>. HDN <i>7, 5, 5 ;</i> ἡ μεγίστη ἡγ. καὶ ἀρχή, PLUT. <i>Mar. 36,</i> la magistrature suprême, <i>càd</i>. le consulat ;<br><b>   IV</b> <i>p. anal</i>. point capital (d’une chose) DIPH. (ATH. <i>132</i> d).<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. ἡγεμών.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηγεμονια - ἡγεμονία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2232":"<h1>hegemon</h1>\n<p>Strong n° 2232 <i>Prononciation [hayg-em-ohn']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>toute sorte de chef, un guide, un préfet, un président, un général, un souverain\n<ol type=\"a\">\n<li>un « legatus Caesaris », intendant administrant une province au nom et avec l'autorité de l'empereur Romain\n<ol>\n<li>le gouverneur d'une province</li>\n</ol>\n</li>\n<li>procureur, attaché à un proconsul, qui avait en charge les revenus impériaux\n<ol>\n<li>administrait également une partie de la justice.</li>\n</ol>\n</li>\n<li>premier, principal</li>\n<li>la ville principale, capitale de la région</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡγεμών, όνος (ὁ, ἡ) :<br>A</b> <i>subst. :</i><br><b>   I</b> qui conduit, <i>d’où :</i><br><b>      1</b> guide, OD. <i>10, 505 ; 15, 310 ;</i> HDT. <i>5, 14, etc. ;</i> XÉN. <i>Mem. 1, 3, 4 ;</i> SOPH. <i>Ant. 1017 ;</i> EUR. <i>Ph. 1616, etc. ; en parl. de choses :</i> ἀχαριστία ἐπὶ πάντα τὰ αἰσχρὰ ἡγεμών, XÉN. <i>Cyr. 1, 2, 7,</i> l’ingratitude conduit à toutes les actions honteuses ; πόνους τοῦ ζῆν ἡδέως ἡγεμόνας νομίζετε, XÉN. <i>Cyr. 1, 5, 12,</i> vous regardez la fatigue comme la source du bien-vivre ;<br><b>      2</b> <i>fig</i>. conducteur d’un char, SOPH. <i>O.R. 804 ;</i><br><b>      3</b> <i>fig</i>. qui prend l’initiative de, qui donne l’exemple de : ἠθῶν χρηστῶν, PLAT. <i>Leg. 670</i> d, d’un caractère honnête ;<br><b>   II</b> qui commande, <i>d’où :</i><br><b>      1</b> <i>en gén</i>. chef, IL. <i>2, 365 ; 11, 304, etc. ;</i> ἡγ. γῆς, SOPH. <i>O.R. 103 ; cf. O.C. 289,</i> chef d’un pays ; <i>p. opp. à</i> βασιλεύς : πάντων καὶ αὐτοῦ βασιλέως ἡγ. XÉN. <i>Hell. 3, 5, 14,</i> chef de tous et du roi lui-même ;<br><b>      2</b> <i>particul</i>. chef d’armée, HDT. <i>9, 33 ; joint à</i> στρατηγός <i>sans l’idée du grade hiérarchique qu’indique</i> στρατηγός, HDT. <i>7, 158 ;</i> PLUT. <i>Marc. 7, etc. ; avec l’idée d’une autorité supérieure à celle de</i> στρατηγός, THC. <i>8, 89 ;</i> PLUT. <i>Ages. 37 ;</i><br><b>      3</b> chef d’une association, DÉM. <i>565, 12 ;</i><br><b>      4</b> <i>à Rome,</i> empereur, PLUT. <i>Cic. 2 ; ou</i> gouverneur de province, NT. <i>Matth. 27, 2 ; Ap. 23, 24 ;</i><br><b>      5</b> <i>p. anal. en parl. de la reine des abeilles,</i> ARSTT. <i>H.A. 9, 42, 2 ; de l’animal (bélier, bœuf) chef du troupeau,</i> ARSTT. <i>H.A. 6, 19, 2, etc. ;</i><br><b>   III</b> <i>t. de métr</i>. ὁ ἡγ. (<i>s.-e</i>. πούς) DH. <i>Comp. 17,</i> le pyrrhique, <i>sorte de mètre ;</i><br><b>B</b> <i>adj</i>. chef, premier, principal, PLAT. <i>Criti. 119</i> a ; ναῦς ἡγεμών, ESCHL. <i>Suppl. 722,</i> vaisseau amiral.<br><span><b><span class=\"arrow\"></span></b> <i>Joint à un subst. neutre,</i> ἡγεμόσι μέρεσι, PLAT. <i>Tim. 91</i> e. <i>Dor</i>. ἁγεμών <span>[ᾱ]</span> ESCHL. <i>Pers. 640</i>.<br><span><b>Étym</b>. ἡγέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηγεμων - ἡγεμών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 21 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (7)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2233":"<h1>hegeomai</h1>\n<p>Strong n° 2233 <i>Prononciation [hayg-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mener, conduire\n<ol type=\"a\">\n<li>aller devant</li>\n<li>être un chef\n<ol>\n<li>diriger, commander</li>\n<li>avoir de l'autorité sur</li>\n<li>prince, pouvoir royal, gouverneur, vice-roi, chef, anciens ou responsables d'églises</li>\n<li>toute sorte de chefs, responsables, meneurs</li>\n<li>celui qui porte la parole</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>considérer, juger, penser, estimer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡγέομαι-οῦμαι</b> <span>(<i>f</i>. ἡγήσομαι, <i>ao</i>. ἡγησάμην, <i>pf</i>. ἥγημαι)</span><br><b>A</b> marcher devant, <i>càd. :</i><br><b>   I</b> <i>en gén</i>. conduire, guider :<br><b>      1</b> <i>au propre,</i> XÉN. <i>An. 2, 4, 5 ; p. opp. à</i> ἕπεσθαι, OD. <i>1, 125 ;</i> XÉN. <i>An. 2, 2, 8 ;</i> PLAT. <i>Phæd. 93</i> a ; <i>à</i> ἀκολουθεῖν, AR. <i>Pl. 15 ;</i> LUC. <i>Herm. 73 ; en parl. de l’ordre de marche d’une armée, p. opp. à</i> ὀπισθοφυλακεῖν, XÉN. <i>An. 4, 1, 15 ; avec</i> πρόσθεν, IL. <i>24, 96 ; ou</i> πάροιθε, EUR. <i>Ph. 834 ;</i> Τρωσὶ ποτὶ πτόλιν ἡγήσασθαι, IL. <i>22, 101,</i> conduire les Troyens vers la ville ; ἡγεῖσθαί τινι εἰς τὸ θέατρον, ESCHN. <i>64, 28,</i> conduire qqn au théâtre ; ἡγεῖσθαι ἐς, IL. <i>20, 144 ;</i> πρός, XÉN. <i>Ages. 10, 2 ;</i> ἐπί, OD. <i>13, 65,</i> conduire dans, vers, <i>etc. ; avec l’acc. du lieu où l’on va :</i> ἡγ. βωμούς, ESCHL. <i>Suppl. 501,</i> conduire vers des autels ; <i>avec l’acc. de la chose que l’on conduit :</i> πομπάς, DÉM. <i>571, 3,</i> conduire un cortège ; <i>avec l’acc. du lieu par où l’on passe :</i> ὁδὸν ἡγήσασθαι, OD. <i>10, 263 ; ou un double rég. de pers. et du lieu par où l’on passe,</i> τινὶ τὴν ὁδὸν ἡγ. HDT. <i>9, 15,</i> montrer le chemin à qqn, marcher devant lui (<i>cf. lat</i>. præire viam) ; <i>de pers. et du lieu où l’on va :</i> τινὶ πόλιν ἡγεῖσθαι, OD. <i>6, 114,</i> guider qqn vers la ville ; <i>abs</i>. ἡγούμενος, qui est en avant : σκέλη ἡγούμενα (<i>p. opp. à</i> ἑπόμενα) ARSTT. <i>Inc. an. 16, 2,</i> les jambes de devant ; <i>t. de gr. en parl. de la lettre initiale d’un mot,</i> D. THR. <i>633, 32 ;</i> DH. <i>5, 159 Reiske ; t. de log. en parl. de la</i> πρότασις <i>dans une proposition conditionnelle,</i> SEXT. <i>311, 26 Bkk. ;</i><br><b>      2</b> <i>fig. càd</i>. donner l’exemple de, le signal de : τινί τινος, PD. <i>P. 4, 442 ;</i> XÉN. <i>Cyr. 8, 7, 1,</i> donner à qqn le signal de qqe ch. ; τινὶ ὀρχηθμοῖο, OD. <i>23, 134 ;</i> ᾠδῆς, PLAT. <i>1 Alc. 125</i> c, donner le ton à qqn pour la danse, pour le chant ; <i>avec le dat</i>. κερδοσύνῃ ἡγ. τινι, IL. <i>22, 247,</i> donner à qqn l’exemple de la cupidité ; ἡγ. ἐς φιλότητα, HÉS. <i>O. 710,</i> faire le premier pas pour témoigner de l’affection ;<br><b>   II</b> conduire comme chef (une armée, une flotte, <i>etc.) d’où :</i><br><b>      1</b> commander comme chef militaire : ἡγ. νήεσσι ἐς Τροίην, IL. <i>16, 169,</i> diriger des vaisseaux contre Troie ; ἡγ. Τρώεσσιν, IL. <i>5, 211,</i> amener du secours aux Troyens ; <i>plus souv. avec le gén</i>. ἡγ. λαῶν, IL. <i>15, 311,</i> marcher devant l’armée ; ἡγ. τῆς Ἀσίης, HDT. <i>1, 95, etc. (cf</i>. HDT. <i>9, 1, etc</i>.) commander à l’Asie ; παντὸς τοῦ Ἑλλήνων στρατοῦ, HDT. <i>7, 161,</i> commander à toute l’armée des Grecs ;<br><b>      2</b> commander comme chef d’une cité, comme gouverneur d’un pays : ἡγ. πόλει, EUR. (ATH. <i>413</i> e) ; <i>d’ord. avec le gén</i>. τῆς πόλεως, XÉN. <i>Mem. 1, 7, 5,</i> gouverner la cité ; <i>abs</i>. οἱ ἡγούμενοι, SOPH. <i>Ph. 386,</i> les chefs de la cité ;<br><b>      3</b> commander, <i>au sens politique, càd</i>. exercer l’hégémonie, avoir la prééminence en Grèce, PLUT. <i>Them. 7, Arist. 24 ;</i><br><b>      4</b> <i>en gén</i>. diriger comme chef, <i>avec l’acc., fig</i>. ἡγ. τὰς τύχας, EUR. <i>Suppl. 226,</i> diriger la fortune ; <i>avec le gén</i>. ἡγούμενος τῶν ἡδονῶν, ἀλλ' οὐκ ἀγόμενος ὑπ' αὐτῶν, ISOCR. <i>198</i> a, gouvernant les plaisirs, mais ne se laissant pas conduire par eux : ἐὰν μὲν αὐτῶν ἡγῆται ἀμαθία, PLAT. <i>Euthyd. 281</i> d, si c’est l’ignorance qui les guide ; <i>cf</i>. PLAT. <i>Euthyd. 281</i> a, <i>Charm. 172</i> a ;<br><b>      5</b> <i>abs</i>. avoir le premier rang : ἐν τέχνῃ, SOSIPATER (ATH. <i>378</i> f) dans un art ; <i>en parl. de choses :</i> ἀλήθεια πάντων ἀγαθῶν ἡγεῖται, PLAT. <i>Leg. 730</i> c, la vérité est le principal de tous les biens ;<br><b>B</b> <i>après Homère,</i> croire, penser (<i>cf. lat</i>. duco) ; <i>avec une prop. inf</i>. ἡγ. τι εἶναι, HDT. <i>1, 126, etc</i>. penser que qqe ch. est ; ἡγ. θεοὺς βλέπειν πρὸς τὸν εὐσεϐῆ βροτῶν, SOPH. <i>O.C. 278,</i> penser que les dieux ont l’œil sur le mortel pieux ; ἡγ. τινα βασιλέα, HDT. <i>6, 52 ;</i> φίλην, LUC. <i>Pisc. 14,</i> regarder qqn comme roi, comme une amie ; αἰσχρὸν ἡγ. τι, SOPH. <i>Ph. 108,</i> regarder qqe ch. comme honteux ; θεοὺς ἡγεῖσθαι, EUR. <i>Hec. 800, Bacch. 1327 ;</i> AR. <i>Eq. 32 ;</i> PLAT. <i>Leg. 899</i> c ; δαίμονας ἡγ. PLAT. <i>Ap. 27</i> d, croire aux dieux, <i>propr</i>. croire qu’il y a des dieux ; ἡγ. τι περὶ πολλοῦ, HDT. <i>2, 115 ;</i> περὶ πλείονος, ISOCR. <i>386</i> e ; περὶ πλείστου, THC. <i>2, 89 ;</i> περὶ οὐδενός, LYS. <i>110, 31 ;</i> παρ' οὐδέν, DÉM. <i>282, 14 (décr</i>.) faire grand cas, plus grand cas, très grand cas, ne faire aucun cas de qqe ch. ; <i>au sens pass</i>. τὰ ἁγημένα (<i>dor</i>.) ORACL. (DÉM. <i>1072, 25</i>) ce qu’on croit.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér. dor. 2 sg</i>. ἅγεο <span>[ᾱ]</span> ANTH. <i>12, 119 ; part. ion</i>. ἡγεύμενος, HDT. <i>2, 93 ;</i> HPC. <i>1, 612. Impf. ion</i>. ἡγεύμην, HH. <i>Cer. 181 ;</i> HDT. <i>2, 115 ; 3 sg. dor</i>. ἁγεῖτο <span>[ᾱ]</span> PD. <i>P. 10, 45 ; N. 5, 45 ;</i> THCR. <i>Idyl. 11, 11. Pf. 3 pl. ion</i>. ἡγέαται, HDT. <i>1, 136 ; pf. dor</i>. ἅγημαι <span>[ᾱ]</span> PD. <i>P. 4, 248 ; cf. ci-dessus,</i> ORACL. (DÉM. <i>1072, 25</i>).<br><span><b>Étym</b>. <i>R. indo-europ</i>. *seh₂g-, retrouver <i>la trace,</i> chercher ; <i>cf. lat</i>. sāgiō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηγεομαι - ἡγέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>Comparer : , \n<br><br> – se réfère au jugement subjectif, qui peut ou non être conforme aux faits\n<br><br> – se réfère à l'apparence extérieure actuelle, généralement correcte, qui peut être décevante\n<br><br>Comparer : ,  (),  (), \n<br><br> et  implique de juger et de croire en ne s'appuyant pas sur sa sensibilité ou ses sentiments, mais sur une bonne considération des éléments extérieurs, l'estimation et la comparaison des faits.\n<br><br> et  à l'inverse, décrivent un jugement subjectif variant selon l'orientation ou le déroulement des faits dans leur relation entre eux.\n<br><br> dénote un jugement plus attentif et plus délibéré que ;\n<br><br> est un jugement subjectif qui a le sentiment plus que la pensée () comme base.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n28 fois dans 27 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (4)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (6)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n<li>Hébreux (6)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (4)</li>\n</ul>\n</td></tr>\n</table>","G2234":"<h1>hedeos</h1>\n<p>Strong n° 2234 <i>Prononciation [hay-deh'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avec plaisir, volontiers, agréablement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡδέως</b>, <i>adv. :</i><br><b>   I</b> agréablement, avec plaisir :<br><b>      1</b> <i>en parl. de pers</i>. βίοτον ἡδ. ἄγειν, EUR. <i>Cycl. 452,</i> mener une vie agréable ; ἡδ. εὕδειν, SOPH. <i>Tr. 175,</i> avoir un sommeil agréable ; ἡδ. δρᾶν τι, SOPH. <i>Ant. 70,</i> faire qqe ch. avec plaisir ; ἡδ. ὁρᾶν τινα, EUR. <i>I.A. 1122,</i> voir qqn avec plaisir ; ἡδ. ἔχειν, EUR. <i>I.A. 1122,</i> avoir l’air joyeux : ἡδ. ἔχειν τινί, DÉM. <i>60 ;</i> πρός τινα, ISOCR. <i>6</i> a ; ἐπί τινι, ISOCR. <i>12, 201 B.-Blass</i> être bien disposé pour qqn ; ἡδ. ἔχειν τι, EUR. <i>Ion 647, 1602 ;</i> ἡδ. ἔχειν τινός, HPC. <i>1089</i> g ; MACH. (ATH. <i>577</i> e, <i>581</i> c), se réjouir de qqe ch ; ἡδ. ἔχειν, <i>avec une prop. inf</i>. PLUT. <i>Galb. 21,</i> se réjouir de ce que, <i>etc. ;</i><br><b>      2</b> <i>en parl. de ch. :</i> ἡδ. ἔχειν, EUR. <i>I.A. 483,</i> être agréable ; ἡδ. μοί ἐστι, PLAT. <i>Hipp. ma. 300</i> c, il m’est agréable ;<br><b>   II</b> avec plaisir, volontiers : ἡδ. δέχεσθαι σιτία, HPC. <i>89</i> e, prendre volontiers des aliments ; ἡδ. ἀκούειν, PLAT. <i>Rsp. 470</i> a, écouter volontiers ; <i>cf</i>. AR. <i>Eq. 440 ;</i> ISOCR. <i>26</i> a, <i>etc</i>.<br><span>•<i> Cp</i>. ἥδιον, THC. <i>1, 90 ; 3, 82 ;</i> LYS. <i>111, 41</i>. <i>• Sup</i>. ἥδιστα, THC. <i>2, 49 ;</i> PLAT. <i>Theæt. 183</i> d, <i>etc</i>.<br><span><b>Étym</b>. ἡδύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηδεως - ἡδέως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2235":"<h1>ede</h1>\n<p>Strong n° 2235 <i>Prononciation [ay'-day]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>maintenant, déjà, dès lors</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἤδη</b>, <i>adv</i>., à partir d’ici, <i>d’où :</i><br><b>A</b> (<i>avec idée de lieu</i>) à partir de cet endroit, immédiatement : ἀπὸ ταύτης ἤδη Αἴγυπτος, HDT. <i>3, 5,</i> tout de suite après ce pays est l’Égypte ; <i>cf</i>. THC. <i>3, 95 ;</i> EUR. <i>Hipp. 1200 ;</i><br><b>B</b> (<i>avec idée de temps</i>) à partir de maintenant, <i>càd. :</i><br><b>   I</b> <i>en parl. du passé,</i> déjà : ἤδη ποτέ, IL. <i>1, 260, etc. ;</i> ποτ' ἤδη, ESCHL. <i>Eum. 50 ;</i> SOPH. <i>Aj. 1142,</i> déjà autrefois, parfois déjà ; ἤδη πάλαι, SOPH. <i>O.C. 510,</i> il y a déjà longtemps ; τότ' ἤδη, ESCHL. <i>Pr. 911,</i> déjà alors, alors déjà ;<br><b>   II</b> <i>en parl. du présent,</i> actuellement, <i>p. opp. au passé</i> (ἐν ὑστέρῳ χρόνῳ) SOPH. <i>O.C. 614 ; ou au futur</i> (τάχ', ἐσαῦθις) EUR. <i>Suppl. 551, etc. ;</i> ἤδη δέ, PLUT. <i>Pyrrh. fin,</i> dès ce moment ; ἤδη νῦν, ESCHL. <i>Ag. 1578 ;</i> ἤδη νυνί, AR. <i>Nub. 326 ; ou</i> νῦν ἤδη, SOPH. <i>Ant. 801 ;</i> νῦν… ἤδη, AR. <i>Pl. 316,</i> dès maintenant, tout de suite ; ἤδη γε, DÉM. <i>357, 16,</i> même maintenant ; ἤδη τότε, PLAT. <i>Rsp. 417</i> b, dès ce moment, dès lors ; νὺξ ἤδη τελέθει, IL. <i>7, 282,</i> voici la nuit qui approche ; <i>avec un n. de nombre :</i> ἤδη γὰρ τρίτον ἐστὶν ἔτος, OD. <i>2, 89,</i> car voici la troisième année ; ἔτος τόδ' ἤδη δέκατον, SOPH. <i>Ph. 312,</i> voici maintenant la dixième année ; <i>entre l’art. et le nom :</i> ἡ ἤδη χάρις, DÉM. <i>664, 23,</i> le service rendu en ce moment, l’obligation présente ; <i>cf</i>. XÉN. <i>An. 7, 7, 24 ;</i><br><b>   III</b> <i>en parl. du fut. :</i><br><b>      1</b> dorénavant, désormais, IL. <i>3, 98, etc. ;</i> PLAT. <i>Gorg. 486</i> e ;<br><b>      2</b> dès lors, <i>dans les locut. :</i> τότ' ἤδη, ISOCR. <i>238</i> b, <i>419</i> e, dès lors, <i>litt</i>. alors et dès ce moment ; τοτηνίκ' ἤδη, SOPH. <i>O.C. 440, m. sign. ;</i><br><b>      3</b> tout de suite, <i>devant un fut. :</i> ἤδη λέξω, DÉM. <i>72, 20,</i> je vais dire ; <i>cf</i>. XÉN. <i>Cyr. 8, 3, 1 ; ou après un impér. :</i> ἀπὸ νῦν με λείπετ' ἤδη, SOPH. <i>Ph. 1177,</i> dès maintenant laissez-moi tout de suite ; <i>abs</i>. οὐ τάχ' ἀλλ' ἤδη, AR. <i>Ran. 527,</i> non bientôt, mais tout de suite ;<br><b>      4</b> <i>dans un raisonnement :</i> πᾶς ἤδη ἂν εὕροι, PLAT. <i>Rsp. 398</i> c, tout homme trouverait donc ; οὐ μόνον, ἀλλ' ἤδη, XÉN. <i>Cyr. 8, 8, 6,</i> non seulement, mais encore (<i>litt</i>. en poursuivant, en continuant) ;<br><b>   IV</b> <i>avec le passé, le prés. ou le fut</i>. ἤδη <i>se construit qqf. avec un sup. :</i> ὡς τάχιστ' ἤδη, AR. <i>Th. 662,</i> le plus promptement possible ; <i>cf</i>. HDT. <i>8, 106 ;</i> THC. <i>6, 31</i>.<br><span><b>Étym</b>. ἦ 1, δή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηδη - ἤδη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – « maintenant, tout de suite » indique le temps étroitement lié avec le moment présent ; le temps strictement présent\n<br><br> – « maintenant, (déjà) », avec une référence suggérée à un autre moment ou à quelque espérance, le présent subjectif\n<br><br> – « maintenant, (à cette heure) », marque un moment défini ou une période de temps, le présent immédiat objectif.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n59 fois dans 54 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (8)</li>\n<li>Luc (8)</li>\n<li>Jean (16)</li>\n<li>Actes (3)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (4)</li>\n<li>Philippiens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (2)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2236":"<h1>hedista</h1>\n<p>Strong n° 2236 <i>Prononciation [hay'-dis-tah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>très volontiers</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἥδιστα</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηδιστα - ἥδιστα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2237":"<h1>hedone</h1>\n<p>Strong n° 2237 <i>Prononciation [hay-don-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>plaisir, jouissance</li>\n<li>les désirs du plaisir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡδονή, ῆς (ἡ) :<br>A</b> plaisir, jouissance, agrément, <i>particul. :</i><br><b>   I</b> le plaisir qu’on éprouve :<br><b>      1</b> <i>au plur</i>. plaisirs des sens : αἱ τοῦ σώματος ἡδοναί, XÉN. <i>Hell. 4, 8, 22 ; ou</i> αἱ περὶ τὸ σῶμα ἡδ. <i>Hell. 6, 1, 4 ; ou</i> αἱ κατὰ τὸ σῶμα ἡδ. PLAT. <i>Rsp. 428</i> d ; <i>ou</i> αἱ σωματικαὶ ἡδ. ARSTT. <i>Nic. 7, 8, 4,</i> les plaisirs du corps ; αἱ περὶ πότους καὶ περὶ ἐδωδὰς ἡδ. PLAT. <i>Rsp. 389</i> e, les jouissances du boire et du manger ; ἀκοῆς ἡδονή, THC. <i>3, 38,</i> le plaisir d’entendre ;<br><b>      2</b> <i>au plur</i>. désirs, XÉN. <i>Mem. 1, 2, 23 ;</i> NT. <i>Tit. 3, 3, etc. ;</i><br><b>      3</b> <i>au mor</i>. plaisir, jouissance : ἐν ἡδονῇ ἔχειν τινά, THC. <i>3, 9,</i> voir qqn avec plaisir ; ἡδονὴν ἔχειν τινός, SOPH. <i>O.C. 1604,</i> avoir satisfaction de qqe ch. ; ἐν ἡδονῇ ἐστί μοι, <i>inf</i>. HDT. <i>7, 160 ;</i> καθ' ἡδονήν ἐστί μοι, <i>inf</i>. ESCHL. <i>Pr. 261 ;</i> πρὸς ἡδονήν ἐστί μοι, ESCHL. <i>Pr. 494,</i> il m’est agréable de, <i>etc. ; abs</i>. καθ' ἡδονήν, SOPH. <i>Tr. 197 ;</i> DÉM. <i>98, 13 ;</i> πρὸς ἡδονήν, HDT. <i>3, 126 ; postér</i>. πρὸς ἡδονῆς, PARTH. <i>8 ;</i> LIB. <i>4, 181,</i> par plaisir, avec plaisir ; καθ' ἡδονὴν ποιεῖν, THC. <i>2, 53,</i> agir à son gré ; θᾶσσον ἢ καθ' ἡδονὴν ποδός, SOPH. <i>O.C. 890,</i> plus vite qu’au gré de mon pied ; μεθ' ἡδονῆς, THC. <i>4, 19,</i> avec plaisir ; ἡδονῇ, HDT. <i>2, 137 ;</i> SOPH. <i>O.R. 1339,</i> par plaisir ; ὑφ' ἡδονῆς δακρύειν, LUC. <i>Tox. 4,</i> pleurer de joie ; μαίνεσθαι ὑφ' ἡδονῆς, SOPH. <i>El. 1153,</i> être fou de joie ; ὑφ' ἡδονῆς φρένας ἐκϐάλλειν, SOPH. <i>Ant. 648,</i> perdre la raison par l’effet de la passion ; ἡδοναῖς, SOPH. <i>Tr. 147,</i> dans les plaisirs, au milieu des plaisirs ;<br><b>   II</b> le plaisir qu’on fait éprouver aux autres : ἡδονὴν παρέχειν, XÉN. <i>Cyr. 4, 1, 5,</i> procurer du plaisir ; ἡδονὴν πράττειν τινί, ESCHL. <i>Suppl. 1008 ; ou</i> ποιεῖν τινι, DÉM. <i>437, 3,</i> procurer du plaisir, une jouissance à qqn ; πρὸς ἡδονὴν λέγειν, HDT. <i>3, 126,</i> parler de manière à plaire ; τὰ πρὸς ἡδονὴν καὶ χάριν λεγόμενα, ISOCR. <i>290</i> a, ce qu’on dit pour plaire et être agréable ; <i>cf</i>. SOPH. <i>El. 921 ;</i> κότερα ἀληθηΐῃ χρήσομαι ἢ ἡδονῇ ; HDT. <i>7, 101,</i> parlerai-je franchement ou en vue de te plaire? καθ' ἡδονὰς ποιεῖν, DH. <i>7, 24 ; ou</i> λέγειν, DH. <i>11, 9,</i> agir <i>ou</i> parler de manière à être agréable ;<br><b>B</b> <i>chez les anc. phil. ion</i>. qualité sensible d’un objet (goût, saveur, odeur, <i>etc.) en ce sens, d’ord. joint à</i> χροίη (couleur) ANAXAG. <i>p. 86 ; cf</i>. ARSTT. <i>P.A. 2, 17, 6 ;</i> SOPATR. (ATH. <i>649</i> a).<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἁδονά <span>[ᾱδ]</span> EUR. <i>Ph. 319,</i> EL. <i>126 ; ou</i> ἡδονά, SOPH. <i>O.R. 1339 ;</i> EUR. <i>Ion 1448, 1461 ; Hel. 641 ; I.T. 842</i>.<br><span><b>Étym</b>. ἥδομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηδονη - ἡδονή</font>\n<br><br>vient de 'handano' (plaire)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Tite (1)</li>\n<li>Jacques (2)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2238":"<h1>heduosmon</h1>\n<p>Strong n° 2238 <i>Prononciation [hay-doo'-os-mon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>odeur douce, menthe de jardin\n<ol type=\"a\">\n<li>sorte de petite herbe odoriférante, que les Juifs utilisaient en l'éparpillant sur le sol de leurs maisons et synagogues</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡδύ·οσμος, ος, ον</b>, à l’odeur agréable, AR. <i>fr. 116 ; subst</i>. ὁ ἡδύοσμος, ARSTT. <i>Plant. 1, 7, 1 (cf</i>. STR. <i>344</i>) ; <i>et</i> τὸ ἡδύοσμον, TH. <i>H.P. 7, 7, 1,</i> menthe, <i>plante odoriférante</i>.<br><span><b>Étym</b>. ἡ. ὀσμή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηδυοσμον - ἡδύοσμον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2239":"<h1>ethos</h1>\n<p>Strong n° 2239 <i>Prononciation [ay'-thos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une demeure habituelle, lieu d'habitation, hanter, état coutumier</li>\n<li>coutume, usage, morale, caractère, mœurs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἦθος, εος-ους (τὸ) :<br>   I</b> <i>au pl</i>. séjour habituel, demeure, résidence, <i>en parl. d’animaux :</i> écurie, IL. <i>6, 511 ;</i> étable à porcs, OD. <i>14, 411 ;</i> repaire de lions, HDT. <i>7, 125 ; en parl. d’autres animaux,</i> ARSTT. <i>Mund. 6, 16 ; en parl. de poissons,</i> OPP. <i>H. 1, 93 ; en parl. d’hommes, de peuples,</i> HÉS. <i>O. 167 ;</i> HDT. <i>1, 15, etc. ;</i> ESCHL. <i>Suppl. 64 ;</i> EUR. <i>Hel. 274 ; abs</i>. région où le soleil se lève, HDT. <i>2, 142 ;</i> emplacement planté d’arbres, CALLISTR. <i>Stat. 7 ;</i><br><b>   II</b> caractère habituel, <i>d’où :</i><br><b>      1</b> coutume, usage, HÉS. <i>O. 136 ;</i> HDT. <i>2, 30 ;</i><br><b>      2</b> manière d’être <i>ou</i> habitudes d’une personne, caractère, HÉS. <i>O. 67, 78 ;</i> PD. <i>O. 11, 20 ;</i> ESCHL. <i>Pr. 184 ;</i> SOPH. <i>Aj. 595 ;</i> ἦθ. τῆς ψυχῆς, τῆς γνώμης, PLAT. <i>Rsp. 400</i> d ; DÉM. <i>1406, 5,</i> disposition de l’âme, de l’esprit ; τῆς πόλεως, ISOCR. <i>21</i> a, caractère de la cité ; <i>souv. en ce sens avec un adj. :</i> πρᾷος τὸ ἦθος, PLAT. <i>Phædr. 243</i> c, doux de caractère ; τὸ ἦθος ἀσθενής, ARSTT. <i>H.A. 9, 12, 1,</i> faible de caractère ; <i>de même avec</i> τῷ ἤθει, TH. <i>Char. 6 ;</i> τὰ ἤθεα, HPC. <i>1275 ;</i> τὰ ἤθη, PLAT. <i>Rsp. 535</i> b ; DL. <i>6, 64 ;</i> ἤθεσι, PLAT. <i>Leg. 773</i> c ; τοῖς ἤθεσι, DS. <i>5, 21 ;</i> ἐς τὰ ἤθη, LUC. <i>Pseud. 16 ;</i> κατὰ τὰ ἤθη, ATH. <i>1</i> e (bon, doux, faible, <i>etc</i>.) de caractère ; <i>t. de rhét</i>. impression morale (produite par un orateur, ARSTT. <i>Rhet. 1, 2, 3, etc. ; p. opp. à</i> πάθος, DH. <i>Comp. 22 ; ou</i> par une œuvre d’art, <i>etc</i>. PHILSTR. <i>683</i>) ;<br><b>      3</b> <i>p. ext</i>. mœurs, HÉS. <i>Th. 66 ;</i> HDT. <i>4, 106 ;</i> THC. <i>2, 61, etc</i>. ἤθη καὶ ἔθη, PLAT. <i>Leg. 968</i> d ; τρόποι καὶ ἤθη, <i>Leg. 896</i> e, le caractère et les mœurs ; <i>en parl. des mœurs d’animaux,</i> ESCHL. <i>Ag. 727 ;</i> EUR. <i>Hipp. 1219 ;</i> ARSTT. <i>H.A. 1, 1, 12 ; en parl. de choses :</i> ἦθ. τοῦ πυρετοῦ, GAL. nature de la fièvre.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *sued<sup>h</sup>-, coutume, usage ; <i>cf</i>. ἔθος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηθος - ἦθος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2240":"<h1>heko</h1>\n<p>Strong n° 2240 <i>Prononciation [hay'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être venu, être arrivé, être présent</li>\n<li>métaph.\n<ol type=\"a\">\n<li>venir à quelqu'un, chercher une intimité avec quelqu'un, devenir son disciple</li>\n<li>arriver sur quelqu'un d'une manière inattendue</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἥκω</b> <span>(<i>impf</i>. ἧκον, <i>f</i>. ἥξω, <i>ao.1</i> ἧξα, <i>pf</i>. ἧκα ; <i>pl.q.pf</i>. ἥκειν)</span><br><b>      1</b> être arrivé, être venu, être là, IL. <i>5, 478 ;</i> OD. <i>13, 325 (vulg</i>. ἵκω <i>Bkk</i>.) ; <i>avec une prép. :</i> ἐς τὴν Ἀττικήν, HDT. <i>8, 50 ;</i> ἐς τὰς Ἀθήνας, HDT. <i>8, 50 ;</i> χθονὸς ἐς πέδον, ESCHL. <i>Pr. 1,</i> arriver en Attique, à Athènes, sur le sol d’un pays ; ἥκ. εἴς τινα, ESCHL. <i>Ch. 3 ;</i> πρός τινα, ESCHL. <i>Ch. 659 ;</i> παρά τινα, HDT. <i>7, 157 ;</i> THC. <i>1, 137,</i> être arrivé <i>ou</i> se trouver près de qqn ; πρὸς πόλιν, SOPH. <i>O.C. 734,</i> près de la ville ; <i>ou sans prép. avec l’acc. du lieu où l’on arrive :</i> ἰσθμὸν Κιμμερικὸν ἥξεις, ESCHL. <i>Pr. 729,</i> tu arriveras dans l’isthme des Cimmériens ; ἥκειν χθόνα, EUR. <i>Bacch. 1,</i> arriver dans une contrée ; <i>avec un dat. de pers. :</i> ἥκουσιν αὐτῷ ἄγγελοι, XÉN. <i>Cyr. 5, 3, 26,</i> des messagers lui arrivent (<i>cf. ci-dessous avec un suj. de chose) ; avec un acc. de manière :</i> μακρὰν ὁδὸν ἥκ. XÉN. <i>Cyr. 5, 5, 42,</i> avoir fait une longue route ; <i>cf</i>. SOPH. <i>Ant. 975 ; avec un part. prés. :</i> ἥκω σαφῆ τἀκεῖθεν ἐκ στρατοῦ φέρων, ESCHL. <i>Sept. 40,</i> j’arrive apportant de l’armée des nouvelles sûres de ce qui s’y passe ; <i>ou fut. :</i> ἥκω φράσων, SOPH. <i>Tr. 1112,</i> je suis venu pour dire ; <i>avec un inf. :</i> μανθάνειν ἥκομεν, SOPH. <i>O.C. 12,</i> nous sommes venus pour apprendre ; <i>p. anal. en parl. de choses,</i> venir, arriver : <i>en parl. de mets qui arrivent sur la table,</i> ALEX. (ATH. <i>95</i> a) ; <i>de nouvelles :</i> ἐμοὶ ἀγγελίη ἥκει, HDT. <i>8, 140,</i> un message m’est arrivé ; <i>en parl. du temps, des événements :</i> ἥκει ἦμαρ, ESCHL. <i>Ag. 1301,</i> le jour est venu ; ἥκει δ' ὑμῖν ἐκεῖνος ὁ καιρὸς ἐν ᾧ, LYS. <i>127, 26,</i> il est venu pour vous ce temps où, <i>etc. ;</i> ἥξει καιρὸς ἐκεῖνος ὁπανίκα, THCR. <i>Idyl. 23, 33,</i> il viendra ce temps où, <i>etc. ;</i> ἥκοι ἂν νόσος, SOPH. <i>Aj. 186,</i> une maladie surviendrait ; ἥξει πόλεμος, THC. <i>2, 54,</i> une guerre surviendra ; ὃ καὶ νῦν ἥκει γενόμενον, POL. <i>26, 2, 11,</i> ce qui a même déjà commencé à se produire ; <i>avec un rég. :</i> τιμωρίαν ὑμῖν ἥξειν, PLAT. <i>Ap. 39</i> c, un châtiment vous atteindra ; <i>fig. dans un grand nombre de loc., particul. avec</i> εἰς τοῦτο, εἰς τοσοῦτον, <i>etc. :</i> εἰς τοσοῦτον ἀμαθίας ἥκω ὥστε, PLAT. <i>Ap. 25</i> e, j’en suis venu à ce point d’ignorance que ; ἐς τοσήνδ' ὕϐριν ἥκοντα, SOPH. <i>O.C. 1030,</i> qui en est venu à ce point d’arrogance ; ὡς δυνάμεως ἥκεις, PAUS. <i>4, 21, 10,</i> aussi loin que s’étend ton pouvoir ; διὰ μάχης ἥκειν, ESCHL. <i>Suppl. 475 ;</i> δι' ὀργῆς ἥκ. SOPH. <i>O.C. 905,</i> en être venu à combattre, à s’irriter ; <i>avec un adv</i>. εὖ <i>ou</i> καλῶς ἥκειν, HDT. <i>1, 30,</i> aller bien (<i>propr</i>. être arrivé dans une situation favorable) ; <i>d’où avec le gén</i>. εὖ ἥκειν τοῦ βίου, HDT. <i>1, 30 ;</i> χρημάτων, HDT. <i>5, 62 ;</i> μορφῆς, LUC. <i>Im. 11,</i> réussir en qqe ch., être bienvenu en fait de bonheur dans la vie, de fortune, de beauté ; avoir du bonheur, de la fortune, de la beauté ; ἥκει οὐχ ὁμοίως ὡρέων, HDT. <i>1, 149,</i> il ne jouit pas d’une température semblable, <i>en parl. d’un pays ;</i><br><b>      2</b> <i>p. ext</i>. aboutir à, se rapporter à, se rattacher à : ὅσα ἐπὶ τὴν πρεσϐείαν ἧκε, DÉM. <i>350, 14,</i> tout ce qui avait rapport à l’ambassade ; εἰς ἔμ' ἥκει τῆς πόλεως τὰ πράγματα, AR. <i>Pl. 919,</i> les affaires de la ville m’intéressent, me regardent ; <i>souvent au part</i>. τὰ εἴς τι ἥκοντα, PLAT. <i>Eryx. 392</i> e ; POL. <i>28, 15, 2 ; ou</i> τὰ πρός τι ἥκοντα, POL. <i>12, 15, 9,</i> ce qui concerne qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. dor</i>. ἡξῶ, THCR. <i>Idyl. 15, 144 ; pf. 1 pl. dor</i>. ἥκαμες, PLUT. <i>M. 225</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηκω - ἥκω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 25 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Jean (5)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Hébreux (3)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G2241":"<h1>eli</h1>\n<p>Strong n° 2241 <i>Prononciation [ay-lee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Eli = « mon Dieu »\n<ol><li>Eli, Eli, lama sabachthani. La forme en Hébreu de Elio, Elio, etc., est ici le Syro-Chaldéen (langage commun des Juifs du temps de Jésus) des premiers mots du <a class=\"ref\" data-r=\"PSA22\">Psaume 22</a> : « Mon Dieu, Mon Dieu, Pourquoi m'as-tu abandonné ... » <a class=\"ref\" data-r=\"PSA22.1\">Psaumes 22.1</a></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηλι</font> &lt; אלי - <font face=\"Georgia\">ἠλί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G2242":"<h1>Heli</h1>\n<p>Strong n° 2242 <i>Prononciation [hay-lee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Héli (Angl. Heli) = « celui qui monte »\n<ol><li>le père de Joseph, l'époux de Marie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">'Ηλι</font> &lt; עלי - <font face=\"Georgia\">Ἠλί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2243":"<h1>Helias</h1>\n<p>Strong n° 2243 <i>Prononciation [hay-lee'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Elie (Angl. Elijah) = « mon Dieu est l'Eternel »\n<ol><li>un prophète né à Thischbé (Elie le Thischbite), champion inflexible de la théocratie sous le règne des rois idolâtres Achab et Achazia. Il fut enlevé aux cieux sans voir la mort, et les Juifs espéraient son retour juste avant la venue du Messie, car Elie avait préparé les esprits des Israélites à recevoir ce Messie.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἠλίας</b> <i>ou</i> <b>Ἡλίας, ου (ὁ)</b> Élie <i>ou</i> Hélie, <i>prophète hébreu</i>.<br><span><b><span class=\"arrow\"></span></b> Ἠλ. ANTH. <i>1, 72, etc. ;</i> Ἡλ. ANTH. <i>8, 49, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">'ηλιας</font> &lt; אליהו - <font face=\"Georgia\">Ἠλίας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n29 fois dans 29 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (9)</li>\n<li>Luc (7)</li>\n<li>Jean (2)</li>\n<li>Romains (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2244":"<h1>helikia</h1>\n<p>Strong n° 2244 <i>Prononciation [hay-lik-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>âge, temps de vie, durée\n<ol type=\"a\">\n<li>âge, terme ou longueur de vie</li>\n<li>âge adulte, maturité</li>\n<li>âge convenable pour chaque chose</li>\n<li>métaph. l'état convenable atteint pour une chose</li>\n</ol>\n</li>\n<li>stature, c.à.d hauteur et grâce de la stature</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡλικία, ας (ἡ)</b> <span>[ῐκ]</span><br><b>A</b> âge, <i>d’où :</i><br><b>   I</b> <i>propr</i>. âge, temps de la vie, <i>en gén., d’où :</i><br><b>      1</b> la force de l’âge, la jeunesse : νέος ἡλικίην, HDT. <i>3, 134,</i> jeune ; ἡλικίᾳ ἔτι τότε ὢν νέος, THC. <i>5, 43,</i> étant alors encore jeune ; ἐν τῇ ἡλικίᾳ, THC. <i>8, 75 ;</i> DÉM. <i>42, 9,</i> (les hommes) dans la force de l’âge ; <i>en parl. de femmes,</i> âge nubile, HPC. <i>110</i> a ; DÉM. <i>1352, 12 ;</i> ESCHN. <i>26, 8 ; 27, 28 ;</i> PLUT. <i>Rom. 21 ;</i> εἰς τὴν ἡλικίαν ἀφικέσθαι, PLAT. <i>Men. 89</i> b ; εἰς ἡλικίαν ἐλθεῖν, PLAT. <i>Theæt. 142 fin,</i> être arrivé à l’âge mûr ; ἐν ἡλικίᾳ γενόμενος, XÉN. <i>Mem. 4, 2, 3,</i> parvenu à l’adolescence ; ἐν ἡλικίᾳ εἶναι, PLAT. <i>Charm. 154</i> b, être dans l’adolescence ; <i>au sens mor</i>. âge des passions, fougue de la jeunesse, HDT. <i>3, 36 ;</i><br><b>      2</b> <i>rar</i>. la vieillesse, PLAT. <i>Lach. 180 ;</i> προεληλυθὼς τῇ ἡλικίᾳ, XÉN. <i>Hell. 6, 1, 5,</i> étant avancé en âge ; ληρεῖς ὑφ' ἡλικίας, LUC. <i>Laps. 1,</i> l’âge (<i>càd</i>. la vieillesse) te fait radoter ;<br><b>      3</b> âge, <i>en gén</i>. IL. <i>22, 419 ; au sens collect. c</i>. ἥλικες, ceux du même âge, <i>particul</i>. les jeunes gens, IL. <i>16, 808 ; ou</i> les hommes qui ont l’âge du service militaire, LYS. <i>195, 17 ; en gén</i>. παῖδές τε καὶ ἄνδρες καὶ πᾶσα ἡλικία, PLAT. <i>Leg. 959</i> e, les enfants, les hommes et ceux de tout âge ;<br><b>   II</b> <i>p. ext</i>. période de temps, <i>d’où :</i><br><b>      1</b> âge, temps, époque : ἡλικίην κατὰ Λάϊον, HDT. <i>5, 59 ;</i> ἡ. κατὰ Οἰδίπουν, HDT. <i>5, 60,</i> au temps de Laïos, d’Œdipe ;<br><b>      2</b> <i>p. suite,</i> siècle, génération, HDT. <i>5, 59, etc. ;</i> ἡ νῦν ζῶσα ἡλικία, DÉM. <i>139, 13,</i> la génération présente ; πολλαῖς ἔμπροσθεν ἡλικίαις, PLUT. <i>Per. 27,</i> beaucoup de générations <i>ou</i> de siècles auparavant ;<br><b>B</b> croissance, développement, <i>comme signe de l’âge, d’où</i> grandeur, haute stature, HDT. <i>3, 16 ;</i> PLAT. <i>Euthyd. 271</i> b ; DÉM. <i>1024, 26 ;</i> LUC. <i>V.H. 1, 10 ; p. anal. en parl. de la hauteur d’une statue,</i> LUC. <i>Syr. 28</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἁλικία <span>[ᾱλ]</span> PD. <i>O. 4, 41 ; N. 9, 100 ; P. 4, 281 ; ion</i>. ἡλικίη, IL. <i>22, 419 ;</i> HDT. <i>3, 36 ; 5, 59 et 60 ; 7, 18, etc</i>.<br><span><b>Étym</b>. ἡλίκος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηλικια - ἡλικία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2245":"<h1>helikos</h1>\n<p>Strong n° 2245 <i>Prononciation [hay-lee'-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>du même âge que, aussi grand que\n<ol type=\"a\">\n<li>combien est grand</li>\n<li>combien est petit</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡλίκος, η, ον</b> <span>[ῐ]</span> <i>adj. relat. de</i> τηλίκος, combien grand <i>ou</i> petit (aussi grand <i>ou</i> petit) que :<br><b>   I</b> <i>d’ord</i>. aussi grand que :<br><b>      1</b> <i>en parl. de la taille d’un homme,</i> AR. <i>Ran. 55 ; en parl. d’animaux,</i> ARSTT. <i>G.A. 4, 5 ; dans le disc. indir</i>. εἴσει ἡλίκος γέγονε, PLAT. <i>Charm. 154</i> b, tu vas savoir combien il est devenu grand ;<br><b>      2</b> <i>en parl. de l’âge :</i> de quel âge, du même âge que ; ἄνδρα ἡλίκον Θουκυδίδην, AR. <i>Ach. 703,</i> un homme de l’âge de Thoukydidès, <i>càd</i>. aussi âgé que Thoukydidès ; <i>suivi d’un pron. pers. au même cas :</i> οἱ ἡλίκοι ἐγώ (= τηλίκοι ἡλίκοι ἐγώ) PLAT. <i>Lach. 180</i> d, ceux qui sont du même âge que moi ; <i>dans le disc. indir</i>. ὁρᾷς μὲν ἡμᾶς ἡλίκοι προσήμεθα βωμοῖσι, SOPH. <i>O.R. 15,</i> tu vois de quels âges différents nous sommes, assis auprès de tes autels ;<br><b>      3</b> <i>en parl. de la puissance :</i> τηλικοῦτος ἡλίκος οὐδείς πω βασιλεὺς γέγονε, DÉM. <i>1, 9,</i> aussi grand que ne l’est encore devenu aucun roi ; ἡλίκων ἤδη καὶ ὅσων κύριός ἐστι Φίλιππος, DÉM. <i>67, 1,</i> de quels puissants États et de combien Philippe est déjà le maître ;<br><b>      4</b> <i>pour marquer l’étonnement :</i> θαυμάσι' ἡλίκα, DÉM. <i>348, 24,</i> merveilleusement grand ; μέγιστα ἡλίκα ἀγαθά, LUC. <i>M. cond. 13,</i> avantages extraordinairement grands ; <i>de même</i> θαυμαστὸς ἡλίκος, DÉM. <i>738, 20</i> (<i>v</i>. θαυμαστός) merveilleusement grand ;<br><b>   II</b> combien petit, LUC. <i>Herm. 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἁλίκος <span>[ᾱ]</span> ARCHIM. π. ἑλ. <i>p. 102, 4 ;</i> THCR. <i>Idyl. 14, 55 ; 19, 6 ; 23, 4</i>.<br><span><b>Étym</b>. ὁ-, ἁ- <span>[ᾱ]</span>, <i>thème du pron. relat., v</i>. ὅς¹, <i>cf</i>. πηλίκος, τηλίκος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηλικος - ἡλίκος</font>\n<br><br>vient de 'helix' (un camarade, c.à.d. du même âge)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Colossiens (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2246":"<h1>helios</h1>\n<p>Strong n° 2246 <i>Prononciation [hay'-lee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le soleil</li>\n<li>les rayons du soleil levant</li>\n<li>la lumière du soleil</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἥλιος, ου (ὁ) :<br>   I</b> soleil, HOM. <i>etc. ;</i> ἡλίου κύκλος, ESCHL. <i>Pr. 91 ;</i> SOPH. <i>Ant. 416 ;</i> EUR. <i>Ion 41,</i> le disque du soleil ; <i>au plur</i>. ὁρᾶν μοι δύο ἡλίους δοκῶ, EUR. <i>Bacch. 916,</i> il me semble voir deux soleils ; ἀκτὶς ἡλίου, ESCHL. <i>Ag. 676 ;</i> ἀκτῖνες ἡλίου, EUR. <i>Bacch. 677 ;</i> ESCHL. <i>Pr. 797,</i> les rayons du soleil ; ἡλίου αὐγαί, ESCHL. <i>Pers. 70 ;</i> λαμπάδες, EUR. <i>Ion 1467 ;</i> λαμπτῆρες, EUR. <i>Rhes. 59 ;</i> σέλας, ESCHL. <i>Eum. 916 ;</i> SOPH. <i>El. 17 ;</i> EUR. <i>El. 866 ;</i> φάος, HÉS. <i>O. 154 ;</i> φῶς, EUR. <i>Rhes. 447, etc. ;</i> φέγγος, ESCHL. <i>Pers. 377 ;</i> SOPH. <i>El. 380 ;</i> EUR. <i>Hec. 248 ;</i> φλόξ, ESCHL. <i>Pr. 22 ;</i> EUR. <i>I.T. 1207,</i> l’éclat, les flambeaux, la lumière, la flamme du soleil ; ἡλίου βολαί, EUR. <i>Or. 1259, Ph. 172 ;</i> τόξα, EUR. <i>H.f. 1090,</i> les traits, les flèches du soleil ; ἁλίου ἅρμα, EUR. <i>Or. 1007,</i> le char du soleil ; ἡλίου θάλπος, EUR. <i>Cycl. 540 ;</i> θάλπη, ESCHL. <i>Sept. 446 ;</i> καύματα, SOPH. <i>O.C. 350,</i> la chaleur du soleil ; ἅμ' ἠελίῳ ἀνιόντι, DS. <i>15, 18 ;</i> ἅμα τῷ ἡλίῳ ἀνίσχοντι, PAUS. <i>10, 23, 4,</i> au lever du soleil ; <i>ou simpl</i>. ἅμα ἡλίῳ, LIB. <i>1, 286,</i> avec le soleil ; ἠέλιος δ' ἀνόρουσε, OD. <i>3, 1,</i> et le soleil se leva ; ἔστ' ἂν αὑτὸς ἥλιος ταύτῃ μὲν αἴρῃ, τῇδε δ' αὖ δύνῃ πάλιν, SOPH. <i>Ph. 1330,</i> tant que le même soleil se lèvera de ce côté, et se couchera ensuite de celui-ci ; ἀφ' ἡλίου ἀνιόντος μέχρι δυομένου, ESCHN. <i>72, 27,</i> depuis le lever jusqu’au coucher du soleil ; τινὲς αὐτῶν οὔτε ἀνατέλλοντα τὸν ἥλιον οὔτε δυόμενον ἑωράκασι, ATH. <i>526</i> b, quelques-uns d’entre eux n’ont jamais vu le soleil se lever ni se coucher ; δύσετό τ' ἠέλιος, OD. <i>2, 388,</i> et le soleil se plongea (dans l’Océan) ; ἐς ἠέλιον καταδύντα, IL. <i>1, 601,</i> vers le coucher du soleil ; μικρὸν πρὸ δύντος ἡλίου, XÉN. <i>Hell. 7, 2, 22,</i> peu avant le coucher du soleil ; <i>en parl. d’une éclipse de soleil :</i> τὸν ἥλιον ἐκλιπεῖν συνέϐη καὶ γενέσθαι σκότον, PLUT. <i>Per. 35,</i> il arriva en même temps que le soleil s’éclipsa et que l’obscurité se fit ; περὶ ἡλίου ἔκλειψιν, XÉN. <i>Hell. 2, 3, 4,</i> pendant une éclipse de soleil ;<br><b>   II</b> <i>p. suite, l’idée du soleil sert à exprimer :</i><br><b>      1</b> <i>l’idée de vie sur terre :</i> ὁρᾶν φάος ἠελίοιο, IL. <i>18, 61, etc</i>. voir la lumière du soleil ; ὑπ' ἠελίῳ, IL. <i>4, 44 ;</i> ὑφ' ἡλίῳ, EUR. <i>Alc. 151 ;</i> ὑπὸ ἡλίου, THC. <i>2, 102 ;</i> ὑπὸ τὸν ἥλιον, DÉM. <i>316, 16 ;</i> PLUT. <i>Luc. 30,</i> habiter, résider, être vu sous le soleil, <i>càd. sur terre ;</i> οὐκέτ' εἶναι ὑφ' ἁλίῳ, EUR. <i>Alc. 394,</i> n’être plus sous le soleil, avoir cessé de vivre ;<br><b>      2</b> <i>la région du ciel où le soleil se lève, l’orient :</i> πρὸς ἠῶ τ' ἠέλιόν τε, IL. <i>12, 239, etc. ;</i> OD. <i>13, 240, etc. (p. opp. à</i> πρὸς ζόφον) vers l’orient et la région du soleil ; <i>ou</i> πρὸς ἠῶ τε καὶ ἡλίου ἀνατολάς (<i>p. opp. à</i> πρὸς ἑσπέρην) HDT. <i>7, 58 ; ou</i> πρὸς ἠῶ τε καὶ ἥλιον ἀνατέλλοντα, HDT. <i>4, 40, m. sign. ;</i> οἱ ἀπὸ ἡλίου ἀνατολέων, HDT. <i>7, 70,</i> ceux de l’orient ;<br><b>      3</b> <i>l’idée de la course du soleil pour marquer la durée : soit la durée d’un jour,</i> SOPH. <i>El. 424 ;</i> ἁλίῳ ἀμφ' ἑνί, PD. <i>O. 13, 51 (cf</i>. EUR. <i>Rhes. 447</i>) pendant un seul jour ; <i>au plur</i>. EUR. <i>Hel. 658 ;</i> ἡλίους δέκα, LUC. <i>Philopatr. 26 ;</i> δώδεχ' ἡλίους, <i>Philopatr. 4,</i> dix, douze soleils, <i>càd</i>. jours ; ἐπὶ πολλοῖς ἡλίοις, LIB. (EUST.-DP. <i>39</i>) pendant de nombreux jours ; <i>soit la révolution d’une année ;</i> ἑξηκοστὸν ἥλιον κάμψαι, HÉROD. ATT. (STOB. <i>Fl. 116, 21</i>) avoir franchi dans sa course le 60<sup>e</sup> soleil, <i>càd</i>. la 60<sup>e</sup> année ;<br><b>      4</b> <i>l’idée de chaleur :</i> ὁ ἥλιος πολύς, LUC. <i>Nav. 35,</i> forte chaleur ; πολὺν τὸν ἥλιον ἐπὶ τῷ σώματι ἐμφαίνειν, LUC. <i>Ind. 3,</i> avoir le corps brûlé par le soleil ; <i>au plur</i>. οἱ ἥλιοι, la chaleur du soleil (<i>p. opp. à</i> τὸ πνῖγος) THC. <i>7, 87 ;</i> ARSTT. <i>G.A. 5, 5, 9 ; H.A. 8, 7 ;</i> EL. <i>N.A. 16, 17 ; V.H. 13, 1 ;</i><br><b>      5</b> <i>fig</i>. chaleur de l’âme, joie, bonheur, PLUT. <i>M. 994</i> e ; <i>cf</i>. ARTÉM. <i>2, 36</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans Hom. d’ord. épq</i>. ἠέλιος, (<i>v. ci-dessus). Dor</i>. ἀέλιος <span>[ᾱ]</span> PD. <i>P. 4, 257 ; dans les chœurs de Soph. et d’Eur. (jamais dans Eschl</i>.) SOPH. <i>Ant. 100, 809 ; O.C. 1245 ;</i> EUR. <i>El. 739 ; avec</i> <span>[ᾰ]</span> ἀέλιον, SOPH. <i>Tr. 835 ;</i> ἀελίου, EUR. <i>Med. 1252 ; autre forme dor</i>. ἅλιος <span>[ᾱ]</span> SOPH. <i>Tr. 96, El. 824</i>.<br><span><b>Étym</b>. <i>pour</i> *σᾱϝέλιος, *ἀϝέλιος, <i>d’où</i> ἠέλιος, <i>att</i>. ἥλιος, <i>de indo-europ</i>. *seh₂u-el-, soleil ; <i>cf. sscr</i>. sū́rya-, sū́ra-, <i>lat</i>. sōl, <i>angl</i>. sun.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηλιος - ἥλιος</font>\n<br><br>vient de 'hele' (un rayon, peut-être parent de la variante de )</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n32 fois dans 32 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (4)</li>\n<li>Luc (3)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (13)</li>\n</ul>\n</td></tr>\n</table>","G2247":"<h1>helos</h1>\n<p>Strong n° 2247 <i>Prononciation [hay'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un clou</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>*ἠλός</b> (<i>seul. voc</i>. ἠλέ) <i>c</i>. ἠλεός ; <i>sel. d’autres,</i> ἠλέ <i>apocope de</i> ἠλεέ, <i>v</i>. ἠλεός.<br><br>\n➁ <b>ἧλος, ου (ὁ) :<br>   I</b> clou :<br><b>      1</b> clou servant d’ornement (sur un sceptre, sur une épée, <i>etc.) touj. en ce sens dans Hom</i>. (IL. <i>1, 246 ; 11, 29, etc</i>.) ; ATH. <i>488</i> b ;<br><b>      2</b> clou pour clouer (clou de fer <i>ou</i> cheville de bois) PD. <i>P. 4, 125 ;</i> XÉN. <i>Cyn. 9, 12, etc. ; particul</i>. clou pour chaussures, TH. <i>Char. 4 ;</i> ATH. <i>539</i> c ; <i>prov</i>. <span>ἄλλῳ ἥλῳ ἐκκρούειν τὸν ἧλον</span>, LUC. <i>Laps. 4,</i> chasser un clou par un autre ; <span>ἥλῳ ὁ ἧλος</span> (<i>s.-e</i>. ἐκκρούεται) ARSTT. <i>Pol. 5, 11, 3,</i> un clou chasse l’autre ;<br><b>   II</b> <i>fig</i>. toute excroissance en forme de clou (cor aux pieds, verrue, <i>etc</i>.) TH. <i>Ign. 37 ;</i> NIC. <i>Th. 272 ; joint à</i> τύλος, DIOSC. <i>2, 30, 69 ; particul</i>. sorte de champignon parasite sur certains arbres (sur l’olivier, <i>etc</i>.) TH. <i>H.P. 4, 14, 3</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἇλος, PD. <i>P. 4, 125 ;</i> ANTH. <i>6, 96 et 110</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηλος - ἧλος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2248":"<h1>hemas</h1>\n<p>Strong n° 2248 <i>Prononciation [hay-mas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>nous, notre, nos, etc.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡμᾶς</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημας - ἡμᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n177 fois dans 164 versets de 23 livres bibliques (NT).\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (5)</li>\n<li>Luc (17)</li>\n<li>Jean (2)</li>\n<li>Actes (29)</li>\n<li>Romains (13)</li>\n<li>1 Corinthiens (8)</li>\n<li>2 Corinthiens (23)</li>\n<li>Galates (5)</li>\n<li>Ephésiens (12)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (10)</li>\n<li>2 Thessaloniciens (4)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (5)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (4)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (6)</li>\n<li>3 Jean (2)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G2249":"<h1>hemeis</h1>\n<p>Strong n° 2249 <i>Prononciation [hay-mice']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>nous, notre, etc.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡμεῖς</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημεις - ἡμεῖς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n127 fois dans 121 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (3)</li>\n<li>Luc (5)</li>\n<li>Jean (18)</li>\n<li>Actes (21)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (17)</li>\n<li>2 Corinthiens (16)</li>\n<li>Galates (7)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (7)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Tite (2)</li>\n<li>Hébreux (6)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (9)</li>\n<li>3 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2250":"<h1>hemera</h1>\n<p>Strong n° 2250 <i>Prononciation [hay-mer'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le jour, pour le jour naturel, ou l'intervalle entre le lever et le coucher du soleil, en opposition à la nuit\n<ol type=\"a\">\n<li>pendant le jour</li>\n<li>métaphore : « le jour » est considéré comme le moment d'obtention de l'indulgence, car le crime et les mauvaises actions sont perpétrés la nuit, dans l'obscurité</li>\n</ol>\n</li>\n<li>le jour civil, d'une durée de vingt quatre heures (incluant la nuit)\n<ol type=\"a\">\n<li>l'usage oriental de ce terme diffère de notre langage occidental. Ainsi toute partie d'un jour est comptée comme un jour entier, ainsi l'expression trois jours et trois nuits correspond seulement à un jour entier, plus une partie de deux autres jours.</li>\n</ol>\n</li>\n<li>le dernier jour de cet âge présent, le Christ reviendra des cieux, ressuscitera les morts, accomplira le jugement final, et rendra parfait son royaume</li>\n<li>la durée de temps en général, les jours, ou l'âge dans cette vie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡμέρα, ας (ἡ)</b> jour :<br><b>      1</b> <i>p. opp. à la nuit (dans Hom. seul. au nom. sg. ion</i>. ἡμέρη, IL. <i>8, 541, etc. ;</i> OD. <i>24, 514, etc. et pl</i>. ἡμέραι, OD. <i>14, 93, etc. ; d’ord</i>. ἦμαρ) ; ἅμα ἡμέρᾳ, XÉN. <i>An. 6, 3, 6 ;</i> ἅμ' ἡμέρῃ διαφωσκούσῃ, HDT. <i>3, 86 ;</i> ἅμα τῇ ἡμέρᾳ, XÉN. <i>An. 6, 1, 6 ;</i> ESCHN. <i>64, 28,</i> au point du jour ; ἐπεὶ ἡμέρα ὑπεφαίνετο, XÉN. <i>Cyr. 4, 5, 14,</i> comme le jour commençait à paraître ; διέλαμψεν ἡμέρα, AR. <i>Pl. 744,</i> le jour commença à briller ; ἀφ' ἡμέρας, POL. <i>8, 27, 11 ; 29, 1, 4 et 6 ;</i> DS. <i>Exc. p. 577, 32 ;</i> ἐξ ἡμέρας, SOPH. <i>El. 780,</i> de jour ; πρὸς ἡμέραν, XÉN. <i>Hell. 2, 4, 6 ;</i> LYS. <i>92 fin,</i> vers le jour ; τῆς ἡμέρας ὀψέ, XÉN. <i>Hell. 2, 1, 23,</i> tard sur le soir ; οὔθ' ἡμέρας οὔτε νυκτός, PLAT. <i>Phæd. 240</i> c ; οὔτε νυκτὸς οὔτ' ἐξ ἡμέρας, SOPH. <i>El. 780,</i> ni jour ni nuit ; οὐ νυκτός, ἀλλὰ μεθ' ἡμέρην, HDT. <i>2, 150,</i> non de nuit, mais pendant le jour ;<br><b>      2</b> durée d’un jour, <i>pour marquer le temps :</i> δι' ἡμερῶν τινων, TH. <i>H.P. 4, 3, 6,</i> pendant quelques jours ; ἐν τρισὶν ἡμέραις, LYS. <i>158, 39 ;</i> NT. <i>Joh. 2, 19,</i> en trois jours ; <i>avec le gén</i>. τριῶν ἡμερέων, HDT. <i>2, 115 ;</i> πέντε ἡμερῶν, THC. <i>7, 3 ;</i> ἡμερῶν ὀλίγων, THC. <i>4, 26,</i> dans le délai de trois jours, de cinq jours, de quelques jours ; ἀνὰ πᾶσαν ἡμ. HDT. <i>7, 198,</i> chaque jour ; ἐπ' ἡμέρης ἑκάστης, HDT. <i>5, 117 ;</i> τῆς ἑκάστης ἡμέρης, HDT. <i>2, 37 ;</i> ἑκάστης ἡμέρας, PLAT. <i>Prot. 318</i> a, <i>Conv. 172</i> c ; καθ' ἑκάστην ἡμέραν, ESCHN. <i>77, 19 ;</i> καθ' ἑκάστην τὴν ἡμέραν, ISOCR. <i>56</i> c ; καθ' ἡμέραν, THC. <i>1, 2 ;</i> τὸ καθ' ἡμέραν, PLAT. <i>Phædr. 240</i> b, chaque jour ; καθ' ἡμέραν, SOPH. <i>El. 999,</i> maintenant ; ἡμέρᾳ παρ' ἡμέραν, ANT. <i>137, 43 ; ou simpl</i>. παρ' ἡμέραν, LUC. <i>D. deor. 24, 2,</i> de jour en jour ; ἐξ ἡμερῶν εἰς ἡμέρας, SPT. <i>2Par. 21, 15,</i> de jour en jour ; ἡμέραν ἐξ ἡμέρας, SPT. <i>Gen. 39, 10 ; 2Par. 24, 11,</i> jour par jour ; ἐφ' ἡμέραν, THC. <i>4, 69 ;</i> EUR. <i>Cycl. 336 ;</i> ἐπ' ἡμέρην, HDT. <i>1, 32,</i> pour un jour, pour la durée d’un jour, au jour le jour ; τῇδ' ἡμέρᾳ, EUR. <i>Hec. 44 ;</i> τῇδε θἠμέρᾳ, SOPH. <i>O.R. 1283 ;</i> AR. <i>Av. 1072 ;</i> τῇδ' ἐν ἡμέρᾳ, SOPH. <i>O.C. 1612, etc</i>. ce jour-là, ce jour même ; μέχρι τῆς τήμερον ἡμέρας, DÉM. <i>51, 24,</i> jusqu’au jour d’aujourd’hui ; τρίτην ἡμέραν ἥκειν, THC. <i>8, 23,</i> être venu le troisième jour ; τῆς αὐτῆς ἡμέρας, ISOCR. <i>58</i> c, le même jour ;<br><b>      3</b> <i>p. ext</i>. jour, <i>pour marquer le temps en gén. :</i> αἱ μακραὶ ἡμέραι, SOPH. <i>O.C. 1216,</i> longs jours, longue vie ; παλαιὰ ἁμέρα, SOPH. <i>Aj. 623,</i> la vieillesse ; νέα ἡμέρα, EUR. <i>Ion 720,</i> la jeunesse ; τῇ πρώτῃ ἡμέρᾳ, ARSTT. <i>Rhet. 2, 12, 8,</i> dans les premiers temps de la vie, <i>càd</i>. dans la jeunesse ; <i>particul</i>. jour de naissance, DL. <i>4, 41 ;</i> τελευταία ἡμέρα, SOPH. <i>O.R. 1529 ;</i> τερμία ἡμέρα, SOPH. <i>Ant. 1331,</i> le dernier jour (de la vie), le jour de la mort ;<br><b>      4</b> <i>avec un adj. pour marquer la condition ou les événements de la vie (cf</i>. ἦμαρ) : ἐπίπονος ἡμέρα, SOPH. <i>Tr. 654 ;</i> λυπρὰ ἡ. EUR. <i>Hec. 364,</i> vie misérable ; ἐχθρὰ ἡ. EUR. <i>Ph. 540,</i> inimitié, haine.<br><span><b><span class=\"arrow\"></span></b> <i>Épq. et ion</i>. ἡμέρη, HÉS. <i>O. 102 ; dor</i>. ἁμέρα <span>[ᾱμ]</span> SOPH. <i>Aj. 623, etc. ;</i> PD. <i>I. 3, 34, etc. ;</i> THCR. <i>Idyl. 29, 7</i>.<br><span><b>Étym</b>. ἦμαρ, <i>avec élargissement ; l’aspiration p.-ê. d’après</i> ἑσπέρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημερα - ἡμέρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n387 fois dans 365 versets de 23 livres bibliques (NT)\n<ul>\n<li>Matthieu (43)</li>\n<li>Marc (27)</li>\n<li>Luc (85)</li>\n<li>Jean (30)</li>\n<li>Actes (94)</li>\n<li>Romains (11)</li>\n<li>1 Corinthiens (7)</li>\n<li>2 Corinthiens (6)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (4)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (6)</li>\n<li>2 Thessaloniciens (3)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (5)</li>\n<li>Hébreux (18)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (3)</li>\n<li>2 Pierre (12)</li>\n<li>1 Jean (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (21)</li>\n</ul>\n</td></tr>\n</table>","G2251":"<h1>hemeteros</h1>\n<p>Strong n° 2251 <i>Prononciation [hay-met'-er-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>notre, le nôtre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡμέτερος, α, ον :<br>      1</b> notre, le nôtre, IL. <i>1, 30 ; 2, 136, etc. ;</i> XÉN. <i>Cyr. 4, 3, 10 ;</i> εἰς ἡμέτερον (<i>s.-e</i>. δῶμα) OD. <i>2, 55, etc. ;</i> ἡμέτερόνδε, OD. <i>8, 39, etc. ;</i> A. RH. <i>1, 107 ;</i> ἐφ' ἡμέτερ', IL. <i>9, 619 ;</i> OD. <i>15, 88 ;</i> ἐν ἡμετέρου, HDT. <i>1, 35, etc</i>. dans notre demeure ; ἡ ἡμετέρα (<i>s.-e</i>. χώρα) THC. <i>6, 21,</i> notre pays ; τὸ ἡμέτερον, PLAT. <i>Tim. 27</i> d, <i>etc</i>. quant à ce qui nous regarde, pour notre part ; <i>avec un gén. :</i> ἡμέτερον αὐτῶν, PLAT. <i>Gorg. 514</i> b, notre propre (demeure) (<i>p</i>. ἡμῶν αὐτῶν) ;<br><b>      2</b> <i>pour</i> ἐμός, OD. <i>11, 562 ; 16, 300, 442, etc. ;</i> THCR. <i>Idyl. 2, 31 ; 16, 6</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἁμέτ- <span>[ᾱ]</span> THCR. <i>Idyl. 2, 31, etc. ; éol. acc. pl</i>. ἀμμετέρας, THCR. <i>Idyl. 28, 16</i>.<br><span><b>Étym</b>. ἡμεῖς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημετερος - ἡμέτερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2252":"<h1>emen</h1>\n<p>Strong n° 2252 <i>Prononciation [ay'-mane]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vraiment, assurément</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ἤμην</b>, <i>v</i>. .<br><br>\n➁ <b>ἥμην</b>, <i>impf. de</i> ἧμαι. (voir ci-dessous).<br><br>\n<b>ἧμαι, ἧσαι, ἧσται</b>, <i>3 pl</i>. <b>ἧνται</b> (<i>seul. prés. et impf</i>. ἥμην) :<br><b>   I</b> être assis, <i>d’où :</i><br><b>      1</b> <i>propr</i>. être assis, SOPH. <i>Tr. 24 ; avec un acc</i>. σεμνὸν σέλμα, ESCHL. <i>Ag. 183,</i> sur le banc auguste, <i>càd</i>. sur le trône des dieux ;<br><b>      2</b> <i>p. ext</i>. être placé, se tenir, <i>avec idée d’immobilité ;</i> ἐπὶ δίφρῳ, IL. <i>16, 403,</i> sur un char ; ἐπὶ κορυφῆς, IL. <i>14, 157,</i> sur le sommet d’un mont ; ἐπ' ἐσχάραις, ESCHL. <i>Eum. 806,</i> près du foyer ; παρὰ νηυσίν, IL. <i>1, 416,</i> près des navires ; <i>ou simpl. avec un dat. :</i> Ὀλύμπῳ, IL. <i>15, 524,</i> sur l’Olympe ; ἐρετμοῖς, EUR. <i>Cycl. 16,</i> près des rames ; <i>rar. avec l’acc. :</i> κοίτας φοινίας, EUR. <i>Rhes. 547,</i> dans le lit ensanglanté (du Simoïs) ; <i>fig</i>. οἱ ἐν ἀρχαῖς ἥμενοι, EUR. <i>Andr. 699,</i> ceux qui siègent dans les charges, les magistrats ; πρὸς ἐμᾷ ψυχᾷ θάρσος ἧσται, <i>avec l’inf</i>. EUR. <i>Alc. 604,</i> dans mon âme est ancrée la ferme confiance que, <i>etc. ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> demeurer immobile, rester inactif, IL. <i>2, 255 ; 18, 104, etc. ;</i> κατ' οἴκους ἐκτὸς ἧσθαι πόνων, EUR. <i>fr. 10,</i> demeurer chez soi, loin de toute fatigue ; <i>souv. avec un part. :</i> ἧμαι ὀδυρόμενος, OD. <i>14, 40,</i> je suis ici à me lamenter ; ἥμην ἐκπεπληγμένη φόϐῳ, SOPH. <i>fr. 24,</i> je restais frappée de terreur ;<br><b>      2</b> être posté, campé, <i>en parl. d’une armée,</i> IL. <i>15, 740 ; 24, 542 ;</i> πόλιν ἀμφί, IL. <i>18, 509,</i> autour de la ville ; πρόσθε τειχέων, EUR. <i>Suppl. 664,</i> en avant des murs ; <i>en parl. d’un espion,</i> IL. <i>18, 523 ;</i><br><b>      3</b> <i>en parl. de constructions :</i> τῇ ἱρὸν ἧσται, HDT. <i>9, 57,</i> là où se trouve bâti un temple ; <i>cf</i>. LUC. <i>Syr. 31 ;</i><br><b>   III</b> être bas : ἥμενος χόρτος, THCR. <i>Idyl. 13, 40,</i> vallon bas, enfoncé.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 3 pl. épq</i>. εἵαται <span>[ᾰ]</span> IL. <i>10, 100 ;</i> LUC. <i>Syr. 31 ; ion</i>. ἕαται <span>[ᾰ]</span> IL. <i>3, 134 ; part. dor</i>. ἅμενος <span>[ᾱ]</span> PD. <i>O. 10, 33. Impf. 1 pl. épq</i>. ἥμεσθα, EUR. <i>I.A. 88 ; 3 pl. épq</i>. εἵατο <span>[ᾰ]</span> IL. <i>7, 61, etc. ;</i> HÉS. <i>Th. 622 ; ion</i>. ἕατο, IL. <i>7, 414 ; 3 duel poét</i>. ἑήσθην, ORPH. <i>Arg. 818</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₁eh₁s-, être assis ; <i>cf. sscr</i>. ā́ste ; <i>l’aspiration d’après</i> ἕζομαι, ἵζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημεν - ἤμην</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Jean (3)</li>\n<li>Actes (5)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (2)</li>\n</ul>\n</td></tr>\n</table>","G2253":"<h1>hemithanes</h1>\n<p>Strong n° 2253 <i>Prononciation [hay-mee-than-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>demi-mort</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡμι·θανής, ής, ές</b> <span>[ῐᾰ]</span> à demi mort, STR. <i>98 ;</i> ANTH. <i>11, 392</i>.<br><span><b>Étym</b>. ἡμι-, θνῄσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημιθανης - ἡμιθανής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2254":"<h1>hemin</h1>\n<p>Strong n° 2254 <i>Prononciation [hay-meen']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>nous, nos, notre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡμῖν</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημιν - ἡμῖν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n175 fois dans 166 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (19)</li>\n<li>Marc (9)</li>\n<li>Luc (27)</li>\n<li>Jean (16)</li>\n<li>Actes (34)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (7)</li>\n<li>2 Corinthiens (12)</li>\n<li>Ephésiens (3)</li>\n<li>Colossiens (3)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (3)</li>\n<li>Hébreux (8)</li>\n<li>Jacques (3)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (3)</li>\n<li>1 Jean (17)</li>\n<li>2 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2255":"<h1>hemisu</h1>\n<p>Strong n° 2255 <i>Prononciation [hay'-mee-soo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>moitié</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἥμισυς, εια, υ</b>, <i>gén</i>. <b>εος</b> <span>[ῐ]</span><br><b>   I</b> demi, qui forme la moitié, <i>au sg. et au plur</i>. ἡμίσεες, IL. <i>21, 7,</i> la moitié des Troyens ; <i>au sg</i>. ὁ ἥμ. ἀριθμός, PLAT. <i>Leg. 946</i> a, la moitié du compte ; ἡμίσειαν μυριάδα, DC. <i>56, 27, 3,</i> une demi-myriade (5 000) ; τὸ ἥμισυ τεῖχος, THC. <i>2, 78,</i> la moitié du rempart ; <i>subst., avec le gén., d’ord. au nombre et au genre du subst. suiv. :</i> οἱ ἡμίσεις τῶν ἄρτων, XÉN. <i>Cyr. 4, 5, 4,</i> la moitié des pains ; αἱ ἡμίσειαι τῶν νεῶν, THC. <i>88,</i> la moitié des navires ; τῶν ἀνδραπόδων τὰ ἡμίσεα, HDT. <i>6, 23,</i> la moitié des esclaves ; <i>de même au sg</i>. ὁ ἥμισυς τοῦ ἀριθμοῦ, PLAT. <i>Phæd. 104</i> a, la moitié du nombre ; ἡ ἡμίσεια τῆς γῆς, THC. <i>5, 31,</i> la moitié de la terre ; <i>ttef. dans les inscr. att. la construct. se rencontre avec l’adj. non au même genre que le nom, mais au neutre :</i> ἐν δυοῖν καὶ ἡμίσει ἡμέρας, CIA. <i>2 add. 834, c, 73 (après 329 av. J.C</i>.) en deux jours et demi (<i>v. Meisterh. p. 129, 22</i>) ;<br><b>   II</b> <i>subst. :</i><br><b>      1</b> ἡμίσεια (<i>s.-e</i>. μοῖρα) τοῦ τιμήματος, PLAT. <i>Leg. 956</i> d, la moitié de l’amende ; ἐφ' ἡμισείᾳ, DÉM. <i>430, 8,</i> par moitié ;<br><b>      2</b> τὸ ἥμισυ (<i>s.-e</i>. μέρος) IL. <i>13, 665, etc. ; avec le gén</i>. IL. <i>9, 616, etc. ;</i> OD. <i>17, 322, etc</i>. la moitié de ; τὸ ἥμ. τοῦ στρατοῦ, THC. <i>4, 83,</i> la moitié de l’armée ; <i>avec crase :</i> θὤμισυ, HÉS. <i>O. 557 ;</i> θἤμισυ, AR. <i>Lys. 116,</i> la moitié ; <i>après un n. de nombre :</i> μνῶν δώδεκα καὶ ἡμίσους, DH. <i>4, 17,</i> de douze mines et demie ; <i>ou, sans</i> καί, μυριάδων ἑπτὰ ἡμίσους, PLUT. <i>Mar. 34,</i> sept myriades et demie ; <i>adv</i>., ἥμισυ, HÉS. <i>Th. 298 ;</i> PD. <i>N. 10, 163,</i> par moitié, à demi ; <i>gén. neutre :</i> τοῦ ἡμίσους, SPT. <i>Ex. 25, 9 ; 3Reg. 16, 9 ; Esth. 7, 2 ; 1 Macc. 10, 30, etc. ;</i> DS. <i>11, 59, etc. m. sign. ;</i><br><b>      3</b> <i>au plur</i>. τὰ ἡμίσεα, PLAT. <i>Leg. 672</i> e ; <i>ou</i> ἡμίσεα, XÉN. <i>An. 1, 9, 26,</i> la moitié ; <i>adv</i>., τὰ ἡμίσεα, PLAT. <i>Rsp. 535</i> d, à moitié.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. ion. et att</i>. ἡμίσεος, HDT. <i>2, 126 ;</i> THC. <i>2, 78 ; 4, 83 ;</i> PLAT. <i>Charm. 168</i> c, <i>Conv. 205</i> e ; DÉM. <i>691, 16 ; postér. contr</i>. ἡμίσους, DH. <i>4, 17 ;</i> PLUT. <i>Mar. 34 ;</i> JOS. <i>A.J. 3, 6 ; 8, 3 ; pl. nom. ion</i>. ἡμίσεες, IL. <i>21, 7 ;</i> OD. <i>3, 155, 157 ; gén</i>. ἡμισέων, OD. <i>24, 464 ; acc. ion. et att</i>. ἡμίσεας, HDT. <i>9, 51 ;</i> THC. <i>8, 64 ; fém. ion. et att. acc</i>. ἡμισέας, HDT. <i>8, 27 ;</i> THC. <i>8, 8 ; pl. neutre nom. et acc</i>. ἡμίσεα, XÉN. <i>An. 1, 9, 26 ;</i> PLAT. <i>Rsp. 438</i> c, <i>etc. ; par contr</i>. ἡμίση, DÉM. <i>833, 5 ; 956, 3 ; 1325, 28 ;</i> TH. <i>Char. 11 ;</i> EL. <i>V.H. 6, 1 ; postér</i>. τὰ ἡμίσεια, NT. <i>Luc. 19, 8 ;</i> A. LIB. <i>6, 28. Dor</i>. ἅμισυς, <span>[ᾱ]</span> THCR. <i>Idyl. 29, 5. Dans les inscr. att. à côté de la forme</i> ἥμισυς, <i>seule us. jusqu’au 4<sup>e</sup> siècle av. J.C</i>. CIA. <i>4, 3, a, 8 (av. 444 av. J.C.) on trouve une forme récente (à partir du 4<sup>e</sup> siècle av. J.C.) avec assimil. de l’</i> ι <i>en</i> υ : ἥμυσυ, CIA. <i>2, 17, a, 45 (378 av. J.C.) ; 794, d, 58 (356 av. J.C</i>.) ; ἥμυσυν, <i>ibid. 1055, 37 (345 av. J.C.) etc. ; toutefois l’</i> ι <i>reste lorsque la désinence n’est pas en</i> υ : ἡμίσειαν, CIA. <i>2, 600, 22 (300 av. J.C</i>.) ; ἡμίσεος, <i>794, d, 6 (356 av. J.C.), etc. ; v. Meisterh. p. 22, 5. Pour le fém. on trouve à la fois</i> ἡμίσειαν, CIA. <i>2, 600, 22 (300 av. J.C.) et</i> ἡμίσεαν, <i>1055, 16 (345 av. J.C</i>.) ; <i>1059, 14, 19 (321 av. J.C</i>.) ; <i>v. Meisterh. p. 32</i>.<br><span><b>Étym</b>. ἡμι-, <i>cf. lat</i>. sēmi-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημισυ - ἥμισυς</font>\n<br><br>idée de partition dans la liaison, avec le sens de semi-</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2256":"<h1>hemiorion</h1>\n<p>Strong n° 2256 <i>Prononciation [hay-mee-o'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la moitié d'une heure</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡμι·ώριον, ου (τὸ)</b> demi-heure, MÉN. (<i>Com. fr. 4, 314</i>) ; STR. <i>133 ;</i> GEOP. <i>15, 6, 2 ;</i> HIPPIATR. <i>p. 173, 175</i>.<br><span><b>Étym</b>. ἡμι-, ὥρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημιωρον - ἡμιώριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2257":"<h1>hemon</h1>\n<p>Strong n° 2257 <i>Prononciation [hay-mone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>notre, nos, nous ...</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ἤμων</b>, <i>impf. de</i> .<br><br>\n➁ <b>ἡμῶν</b>, <i>gén. de</i> ἡμεῖς, <i>v</i>. .<br><br>\n➂ <b>ἥμων, ονος (ὁ)</b> qui lance des javelots, IL. <i>23, 886</i>.<br><span><b>Étym</b>. ἵημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ημον - ἡμῶν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n403 fois dans 359 versets de 27 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (6)</li>\n<li>Luc (21)</li>\n<li>Jean (13)</li>\n<li>Actes (44)</li>\n<li>Romains (42)</li>\n<li>1 Corinthiens (24)</li>\n<li>2 Corinthiens (56)</li>\n<li>Galates (9)</li>\n<li>Ephésiens (12)</li>\n<li>Philippiens (5)</li>\n<li>Colossiens (6)</li>\n<li>1 Thessaloniciens (31)</li>\n<li>2 Thessaloniciens (22)</li>\n<li>1 Timothée (9)</li>\n<li>2 Timothée (4)</li>\n<li>Tite (7)</li>\n<li>Philémon (4)</li>\n<li>Hébreux (13)</li>\n<li>Jacques (3)</li>\n<li>1 Pierre (4)</li>\n<li>2 Pierre (10)</li>\n<li>1 Jean (24)</li>\n<li>2 Jean (2)</li>\n<li>3 Jean (1)</li>\n<li>Jude (5)</li>\n<li>Apocalypse (13)</li>\n</ul>\n</td></tr>\n</table>","G2258":"<h1>en</h1>\n<p>Strong n° 2258 <i>Prononciation [ane]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>j'étais, etc.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ἦν, 1</b> <i>1<sup>re</sup> ou 3<sup>e</sup> sg. impf. de</i> , être ;<br><b>2</b> <i>1<sup>re</sup> sg. impf. de</i> ἠμί.<br><br>\n<b>ἠμί</b> (<i>seul. prés. et impf</i>.) dire, <i>d’ord. en parenthèse,</i> dis-je, <i>etc. ;</i> ἦν δ' ἐγώ, PLAT. <i>Pol. 327</i> c, disais-je ; <i>la forme</i> ἦ, dit-il, <i>d’ord. sans sujet dans Hom., une fois avec sujet et suivi de</i> ῥα, IL. <i>6, 390 ; chez les Att. seul. dans le dialogue et suivi de</i> ὅς : ἦ δ' ὅς, CRAT. (<i>Com. fr. 2, 126</i>) ; AR. <i>Vesp. 795 ; ou de</i> ἥ : ἦ δ' ἥ, PLAT. <i>Conv. 205</i> c, dit-il, dit-elle ; <i>dans Théocr. touj. avec</i> ῥα : ἦ ῥα, THCR. <i>Idyl. 25, 84 ; et suivi d’un nom commun c. sujet,</i> THCR. <i>Idyl. 22, 75 ; 24, 50 ; dans Plat. suivi de</i> ὅς <i>et d’un nom :</i> ἦ δ' ὃς ὁ Σωκράτης, PLAT. <i>Phæd. 70</i> b, et, dit Socrate, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>1 sg</i>. ἠμί, AR. <i>Ran. 37 ; 2 sg</i>. ἠσί, COM. (<i>Com. fr. 2, 382), ou</i> ἦσι, SAPPH. <i>97 Bgk. Impf. 1 sg</i>. ἦν, PLAT. <i>Pol. 327</i> c, <i>328</i> a ; <i>3 sg</i>. ἦ, PLAT. <i>Pol. 327</i> e, <i>etc. ;</i> THCR. <i>Idyl. 22, 75</i>.<br><span><b>Étym</b>. <i>expression figée</i> ἦ <i>p</i>. *ἦκ-τ, <i>de indo-europ</i>. *h₁eh₁ǵ-, dire ; <i>cf</i>. ἀνώγω.</span><br><br>\n➁ <b>ἥν, 1</b> <i>acc. sg. fém. de</i> ὅς, ἥ, ὅ. ;<br><b>2</b> <i>poét. p</i>. ἑήν, <i>acc. sg. fém. de</i> ἑός.<br><br>\n➂ <b>ἤν</b>, <i>contr. de</i> .<br><br>\n➃ <b>ἤν</b>, <i>interj</i>. voici! voilà! tenez! AR. <i>Eq. 26, etc. ;</i> ἢν ἰδού, EUR. <i>H.f. 867 ;</i> AR. <i>Ran. 1390 ;</i> LUC. <i>D. mort. 10, 10, m. sign. ; avec un verbe au plur</i>. AR. <i>Pl. 75 ; cf</i>. ἠνίδε.<br><span><b>Étym</b>. <i>cf. lat</i>. ēn.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ην - ἦν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n454 fois dans 414 versets de 21 livres bibliques (NT)\n<ul>\n<li>Matthieu (37)</li>\n<li>Marc (60)</li>\n<li>Luc (101)</li>\n<li>Jean (111)</li>\n<li>Actes (81)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (6)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (7)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (8)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (6)</li>\n<li>Apocalypse (17)</li>\n</ul>\n</td></tr>\n</table>","G2259":"<h1>henika</h1>\n<p>Strong n° 2259 <i>Prononciation [hay-nee'-kah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>en ce temps là, quand</li>\n<li>toutes les fois que, aussi longtemps que</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡνίκα</b> <span>[ῐ]</span> <i>conj. corrélat. de</i> πηνίκα <i>et</i> τηνίκα, lorsque, <i>se construit :</i><br><b>A</b> <i>avec les modes suivants :</i><br><b>   I</b> <i>avec l’ind. sans</i> ἄν : ἡνίκα ξυνεσκόταζεν, THC. <i>7, 73,</i> comme la nuit commençait à venir ; <i>cf</i>. OD. <i>22, 198 (seul ex. dans Hom</i>.) ; SOPH. <i>El. 954, O.C. 768, Aj. 1144, etc. ;</i><br><b>   II</b> <i>avec</i> ἄν <i>et le sbj. lorsqu’on veut marquer :</i><br><b>      1</b> <i>une idée de temps indéterminé,</i> SOPH. <i>Ph. 880, O.R. 1492 ; postér. avec l’ind. :</i> ἡνίκα δ' ἂν ἀνέϐη, DÉM. <i>539, 23, etc</i>. lorsqu’il fut monté ; <i>cf</i>. SPT. <i>Ex. 40, 30 ;</i><br><b>      2</b> <i>un fait éventuel :</i> ἡνίκ' ἄν τις ὑμᾶς ἀδικῇ, ἡμεῖς ὑπὲρ ὑμῶν μαχούμεθα, XÉN. <i>Cyr. 4, 4, 11,</i> quand on vous fera du tort (si l’on vous en fait), nous, nous combattrons pour vous ;<br><b>      3</b> <i>une idée de répétition,</i> chaque fois que, toutes les fois que, SOPH. <i>Ph. 310 ;</i> AR. <i>Nub. 608, 612 ; Pax 1145, etc. ;</i><br><b>   III</b> <i>avec l’opt. accompagné de</i> ἄν, SOPH. <i>Tr. 163 ; ou sans</i> ἄν, SOPH. <i>Ph. 705 ;</i><span><b>B</b> <i>avec le gén</i>. ἡνίκα τοῦ χρόνου, EL. <i>N.A. 12, 35,</i> dans le temps que.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἁνίκα <span>[ᾱῐᾰ]</span> SOPH. <i>Ph. 705</i>.<br><span><b>Étym</b>. <i>th</i>. ἡ- <i>fém. de</i> ὅς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηνικα - ἡνίκα</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2260":"<h1>eper</h1>\n<p>Strong n° 2260 <i>Prononciation [ay'-per]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>que</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ἤ·περ</b>, <i>poét</i>. <b>ἠέ·περ</b>, <i>conj</i>. que, IL. <i>1, 260 ;</i> OD. <i>4, 819</i>.<br><span><b>Étym</b>. ἤ <i>ou</i> ἠέ, περ.</span><br><br>\n➁ <b>ἥπερ</b>, <i>fém. de</i> .<br><br>\n➂ <b>ᾗπερ</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηπερ - ἤπερ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2261":"<h1>epios</h1>\n<p>Strong n° 2261 <i>Prononciation [ay'-pee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>affable, bienveillant</li>\n<li>doux, aimable, noble</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἤπιος, α</b> <i>ou</i> <b>ος, ον :<br>   I</b> <i>pass</i>. bon, doux, <i>càd. :</i><br><b>      1</b> bienveillant, favorable, <i>en parl. de pers</i>. IL. <i>24, 770, etc. ;</i> OD. <i>2, 47, etc. ;</i> HÉS. <i>Th. 407 ;</i> SOPH. <i>Ph. 718 ;</i> EUR. <i>Tr. 53 ; joint à</i> ἀγανός, OD. <i>2, 230, etc. ;</i> ἤπ. τινι, IL. <i>8, 40, etc. ;</i> HÉS. <i>Th. 407,</i> bon pour qqn ; <i>en parl. de choses :</i> ἤπια εἰδέναι τινί, IL. <i>16, 73 ;</i> OD. <i>13, 405, etc</i>. vouloir du bien à qqn ; μῦθος ἤπ. OD. <i>20, 327,</i> parole bienveillante ; πρὸς τὸ ἠπιώτερον καταστῆσαι, THC. <i>2, 59,</i> amener à des sentiments plus bienveillants ; ἤπιον ἦμαρ, <i>avec l’inf</i>. HÉS. <i>O. 785,</i> jour propice pour entreprendre qqe ch. ;<br><b>      2</b> <i>en parl. du chaud et du froid,</i> adouci, moins intense, PLAT. <i>Phædr. 279</i> b, <i>etc. ;</i> ἠπιώτεραι θέρμαι, HPC. <i>1207</i> a, moments de calme de la fièvre, apaisement de la fièvre ;<br><b>   II</b> <i>act</i>. adoucissant, calmant, IL. <i>4, 218 ; 11, 515 ; p. opp. à</i> ἰσχυρός, HDT. <i>3, 130 ; cf</i>. ESCHL. <i>Pr. 482 ;</i> SOPH. <i>Ph. 698 ; particul. ép. d’Asklèpios,</i> LYC. <i>1054</i>.<br><span>•<i> Cp</i>. -ώτερος, HDT. <i>7, 142 ;</i> THC. <i>2, 59 ;</i> EUR. <i>Alc. 310 ;</i> PLAT. <i>Phædr. 279</i> b, <i>etc., Sup</i>. -ώτατος, EUR. <i>Bacch. 861 ;</i> PLUT. <i>M. 2</i> f.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, HÉS. <i>Th. 407 ;</i> EUR. <i>Tr. 53</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *h₂e-h₂p-i-, ami ; <i>cf. sscr</i>. āpí-, <i>avec la</i> R. h₂ep-, joindre, <i>cf</i>. ἅπτω¹, <i>lat</i>. aptus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηπιος - ἤπιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2262":"<h1>Er</h1>\n<p>Strong n° 2262 <i>Prononciation [ayr]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Er = « veillant »\n<ol><li>le fils de Jésus () et le père d'Elmadam</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ηρ</font> &lt; ער - <font face=\"Georgia\">Ἤρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2263":"<h1>eremos</h1>\n<p>Strong n° 2263 <i>Prononciation [ay'-rem-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tranquille, paisible, doux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἤρεμος, ος, ον</b>, <i>c</i>. ἠρεμαῖος, TH. <i>Lap. 62 dout. ;</i> LUC. <i>Trag. 207 ;</i> NT. <i>1Tim. 2, 2</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηρεμος - ἤρεμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2264":"<h1>Herodes</h1>\n<p>Strong n° 2264 <i>Prononciation [hay-ro'-dace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Hérode (Angl. Herod) = « héroïque »\n<ol><li>Nom d'une famille royale prospère parmi les Juifs du temps de Christ et des Apôtres\n<ol type=\"a\">\n<li>Hérode le Grand, fût le fils d'Antipas d'Idumée. Il fut désigné roi de Judée par le Sénat romain en 40 avant J.C. et pris possession du royaume en 37 avant J.C. surmontant de grandes oppositions. Il était courageux et habile dans la guerre, instruit et sagace mais extrêmement soupçonneux et cruel. Rendu à moitié fou par des complots, il tua sa femme, trois de ses fils, détruisit la famille royale entière des Hasmonaeans, et mis à mort plusieurs des juifs qui se sont opposés à son gouvernement. Il avait la passion des constructions grandioses. Ses cruautés ayant ôté sa popularité, il essaya de regagner la faveur des Juifs en rebâtissant magnifiquement leur ancien Temple, il contribua aussi à l'embellissement de Jérusalem.</li>\n<li>Hérode le Tétrarque, fils d'Hérode le Grand et de Malthace la Samaritaine, appelé Antipas ou Hérode. Frère d'Archélaüs et demi frère de Philippe, il n'obtint que la tétrarchie de Galilée et de Pérée. Il épousa une fille d'Arétas, roi des Arabes nabatéens, puis il épousa sa belle sœur Hérodias, femme de Philippe, ce qui provoqua la colère d'Arétas qui le vainquit. Notre Seigneur parle de lui en l'appelant \"ce renard\" et de son influence en parlant du \"levain d'Hérode\". Ennemi de Pilate, ils se réconcilièrent le jour de la crucifixion de Jésus.</li>\n<li>le roi Hérode Agrippa I, devant lequel Paul comparut. Souvent nommé simplement Agrippa. Fils d'Aristobule et de Mariamne. Il devint roi avec deux tétrarchies: celle de son oncle Philippe et celle de Lysanias, puis celle de Galilée, et plus tard la Samarie et la Galilée. Agrippas fit décapiter Jacques, frère de Jean emprisonner Pierre. Ayant accepté à Césarée des honneurs dus à Dieu, il fut frappé brusquement, rongé de vers, en 44 ap. J.C, âgé de 54 ans.</li>\n<li>Hérode Agrippa II, fils d'Hérode Agrippa I, et arrière-petit-fils d'Hérode le Grand, frère de deux femmes de mauvaise réputation, Bérénice et Drusille. A cause de son jeune âge, il ne reçut un titre de roi qu'en 48 ap. J.C., avec la tétrarchie de Philippe. Il causa du scandale par ses relations coupables avec sa sœur Bérénice. Il en était accompagné lors du procès de Paul devant Festus. Après la chute de Jérusalem il se retira avec Bérénice à Rome, avec la charge de prêteur. Il mourut en 100 ap. J.C.</li>\n</ol>\n</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἡρῴδης, ου (ὁ)</b> (<i>non</i> Ἡρώδης), Hèrôdès (Hérode) :<br><b>      1</b> <i>poète ïambique, contemporain d’Hipponax ;</i><br><b>      2</b> <i>orateur athénien,</i> LUC. <i>Demon. 24 ;</i><br><b>      3</b> <i>rhéteur grec,</i> PLUT. <i>X orat. Antiph. 21 ;</i><br><b>      4</b> <i>roi de Judée,</i> PLUT. <i>Ant. 61, etc. ;</i><br><b>      5</b> <i>autres,</i> PLUT. <i>Cic. 24, etc</i>.<br><span><b><span class=\"arrow\"></span></b> Ἡρῴδης, CIA. <i>2, 859, a, b, 12 (3<sup>e</sup> siècle av. J.C</i>.) ; <i>v. Meisterh. p. 51, 8 ; voc</i>. Ἡρῴδη, PLUT. <i>Qu. conv. 9, 14, 2 ;</i> JOS. <i>A.J. 18, 7, 1</i>.<br><span><b>Étym</b>. <i>par contract. p</i>. Ἡρωΐδης, <i>patr. de</i> Ἥρως.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ηρωδης - Ἡρῴδης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n44 fois dans 41 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (8)</li>\n<li>Luc (14)</li>\n<li>Actes (9)</li>\n</ul>\n</td></tr>\n</table>","G2265":"<h1>Herodianoi</h1>\n<p>Strong n° 2265 <i>Prononciation [hay-ro-dee-an-oy']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>Hérodiens, c'est-à-dire les partisans d'Hérode.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ηρωδιανοι - Ἡρῳδιανοί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G2266":"<h1>Herodias</h1>\n<p>Strong n° 2266 <i>Prononciation [hay-ro-dee-as']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Hérodias (Angl. Herodias) = « héroïque »\n<ol><li>fille d'Aristobule et petite-fille de Hérode le Grand. Elle fut d'abord mariée à Hérode Philippe I, fils de Hérode le Grand ; puis elle vécut un mariage illégal avec Hérode Antipas, qu'elle força à tuer Jean-Baptiste ; elle suivit Hérode lorsqu'il fut exilé en Gaule.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἡρωδιάς, άδος (ἡ)</b> Hérodiade, <i>femme d’Hérode Philippe, fils du roi juif Hérode,</i> JOS. <i>A.J. 18, 5, 1 ;</i> NT. <i>Matth. 14, 3 ; Marc. 6, 17, 22</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ηροδιας - Ἡρῳδιάς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2267":"<h1>Herodion</h1>\n<p>Strong n° 2267 <i>Prononciation [hay-ro-dee'-ohn]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Hérodion (Angl. Herodian) = « héroïque »\n<ol><li>un certain Chrétien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ηροδιων - Ἡρῳδίων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2268":"<h1>Hesaias</h1>\n<p>Strong n° 2268 <i>Prononciation [hay-sah-ee'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Esaïe (Angl. Isaiah) = « le secours de l'Eternel »\n<ol><li>un célèbre prophète Hébreu qui prophétisa sous le règne d'Ozias, Jotham, Achaz, et Ezéchias</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ησαιας</font> &lt; ישעיהו - <font face=\"Georgia\">Ἠσαΐας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 21 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (4)</li>\n<li>Actes (3)</li>\n<li>Romains (5)</li>\n</ul>\n</td></tr>\n</table>","G2269":"<h1>Esau</h1>\n<p>Strong n° 2269 <i>Prononciation [ay-sow']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Esaü = « velu, poilu »\n<ol><li>était le fils aîné d'Isaac et le frère jumeau de Jacob</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ησαυ</font> &lt; עשו - <font face=\"Georgia\">Ἠσαῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G2270":"<h1>hesuchazo</h1>\n<p>Strong n° 2270 <i>Prononciation [hay-soo-khad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rester tranquille\n<ol type=\"a\">\n<li>se reposer, cesser le travail</li>\n<li>avoir une vie calme, se dit de ceux qui ne courent pas ici et là, mais restent chez eux et réfléchissent à leurs affaires</li>\n<li>être silencieux, ne rien dire, donner la paix</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡσυχάζω</b> <span>[ῠ]</span> <span>(<i>f</i>. -άσω <i>ou</i> -άσομαι, <i>ao</i>. ἡσύχασα, <i>pf. inus</i>.)</span><br><b>   I <i>intr.</i></b> être tranquille, <i>d’où :</i><br><b>      1</b> se tenir tranquille <i>ou</i> immobile, ESCHL. <i>Pr. 327, 344 ;</i> SOPH. <i>O.R. 620 ;</i> οἱ πολέμιοι ἡσύχαζον, XÉN. <i>An. 5, 4, 16,</i> l’ennemi ne bougeait pas ; ἡσυχαζουσῶν τῶν νεῶν, THC. <i>1, 49,</i> les navires restant immobiles ;<br><b>      2</b> se tenir en repos, <i>p. opp. à</i> être agité : ἀλλ' ἡσύχαζε, EUR. <i>H.f. 98,</i> eh bien, calme-toi, reste tranquille ; τὸ ἡσυχάζον τῆς νυκτός, THC. <i>7, 83,</i> le repos de la nuit ; ὁ ἡσυχάζων λόγος, CHRYSIPP. (DL. <i>7, 197, 198</i>) ; ARR. <i>Epict. 2, 18, 18 ;</i> A. GELL. <i>1, 2,</i> le raisonnement du repos, <i>sorte de sophisme ;</i><br><b>      3</b> être tranquille, vivre en paix, <i>en parl. de la Grèce,</i> THC. <i>1, 12 ;</i><br><b>      4</b> demeurer silencieux, EUR. <i>Or. 1350 : en parl. de pers</i>. garder le silence, <i>p. opp. à</i> λαϐροστομεῖν, ESCHL. <i>Pr. 327 ;</i> EUR. <i>Med. 80 ;</i> SEXT. <i>114, 12 ; 313, 6 Bkk. ;</i><br><b>   II <i>tr.</i></b> maintenir au repos, faire demeurer tranquille, PLAT. <i>Rsp. 572</i> a ; <i>d’où, au pass., impers</i>. ἠσυχάζεται ἐπὶ τῆς γῆς, SPT. <i>Job 37, 16,</i> la tranquillité règne sur la terre.<br><span><b>Étym</b>. ἥσυχος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ησυχαζω - ἡσυχάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G2271":"<h1>hesuchia</h1>\n<p>Strong n° 2271 <i>Prononciation [hay-soo-khee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tranquillement, paisiblement\n<ol type=\"a\">\n<li>description de la vie de celui qui reste chez lui à faire son travail, et ne se mêle pas des affaires des autres</li>\n</ol>\n</li>\n<li>en silence</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡσυχία, ας (ἡ)</b> <span>[ῠ]</span><br><b>   I</b> <i>pass. :</i><br><b>      1</b> tranquillité, calme, repos, <i>p. opp. à toute agitation physique ou morale,</i> OD. <i>18, 22 ;</i> PD. <i>N. 9, 114 ;</i> μεθ' ἡσυχίας, EUR. <i>Hipp. 205 ;</i> ἐφ' ἡσυχίας, AR. <i>Vesp. 1517 ;</i> καθ' ἡσυχίαν, XÉN. <i>Hell. 6, 2, 28,</i> tranquillement, en repos, en paix ; ἡσυχίαν ἄγειν, HDT. <i>1, 66 ; 7, 150 ; rar</i>. τὴν ἡσυχίαν ἄγειν, ARR. <i>An. 1, 14, 8 ;</i> ἐν ἡσυχίᾳ ἔχειν ἑαυτόν, HDT. <i>5, 93 ;</i> ἐν ἡσυχίᾳ διατρίϐειν, HDN <i>2, 5,</i> être en repos, se tenir en repos, vivre tranquille ; ἡσυχίαν ἄγειν <i>ou</i> ἔχειν πρός τινα, LYS. <i>180, 11,</i> rester tranquille vis-à-vis de qqn ; ὑπέρ τινος, ISOCR. <i>217</i> d, au sujet de qqe ch. ;<br><b>      2</b> tranquillité, paix, <i>p. opp. à</i> πόλεμος : ἡ ἀπὸ τῆς εἰρήνης ἡσ. DÉM. <i>6, 10,</i> le calme, conséquence de la paix ; ἐν ἡσυχίᾳ, THC. <i>3, 12,</i> en état de paix ;<br><b>      3</b> loisir : καθ' ἡσυχίαν, AR. <i>Lys. 1224 ;</i> THC. <i>3, 48,</i> à loisir ; καθ' ἡσυχίην πολλήν, HDT. <i>1, 9, etc</i>. tout à fait à son aise ;<br><b>      4</b> placidité, lenteur, douceur : ἡσ. κινήσεων, PLAT. <i>Tim. 89</i> e, calme des mouvements ;<br><b>      5</b> silence, EUR. <i>Alc. 77 ; joint à</i> σιωπή, PLUT. <i>Demetr. 8 ;</i> ἡσυχίαν ἄγειν, HDT. <i>1, 92 ;</i> PLAT. <i>Ap. 37</i> c ; ἡσυχίαν ἔχειν, ISOCR. <i>116</i> a ; <i>ou avec le plur</i>. τὰς ἡσυχίας ἄγειν, ATH. <i>113</i> f, <i>ou</i> ἔχειν, ATH. <i>493</i> f, garder le silence ; ἐν ἡσυχίῃ ἔχειν τι, HDT. <i>5, 92, 3,</i> tenir une chose secrète ;<br><b>      6</b> solitude, retraite solitaire, HH. <i>Merc. 356 ;</i> XÉN. <i>Mem. 2, 1, 21 ;</i><br><b>   II</b> <i>act</i>. action de faire cesser, <i>avec le gén. :</i> ἡσ. πολιορκίας, HDT. <i>6, 135,</i> levée d’un siège.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἡσυχίη, HOM. HDT. <i>ll. cc. Dor</i>. ἁσυχία <span>[ᾱσ]</span> PD. <i>N. 1, 106 ; 9, 114, etc</i>.<br><span><b>Étym</b>. ἥσυχος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ησυχια - ἡσυχία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G2272":"<h1>hesuchios</h1>\n<p>Strong n° 2272 <i>Prononciation [hay-soo'-khee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tranquillité, tranquille, calme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡσύχιος, ος, ον</b> <span>[ῠ]</span> paisible, calme, tranquille, IL. <i>21, 598 ;</i> HDT. <i>1, 107 ;</i> PLAT. <i>Rsp. 604</i> e ; οἱ ἡσύχιοι, ANT. <i>121, 12 ;</i> PLAT. <i>Charm. 150</i> b, les gens paisibles ; τὸ ἡσ. τῆς εἰρήνης, THC. <i>1, 120,</i> le calme de la paix.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἁσύχ. <span>[ᾱ]</span> PD. <i>P. 9, 40</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ησυχιος - ἡσύχιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2273":"<h1>etoi</h1>\n<p>Strong n° 2273 <i>Prononciation [ay'-toy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>soit que, l'un ou l'autre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἤ·τοι :<br>   I</b> <i>adv. c</i>. ἦ τοι, certes, assurément, en vérité :<br><b>      1</b> <i>au commenc. d’une prop. :</i> ἤτοι ὅ γ' ὣς εἰπών, IL. <i>2, 76 ; joint à</i> μέν : ἤτοι μέν, IL. <i>3, 213 ;</i><br><b>      2</b> <i>après un ou plus. mots ; particul. après un pron. seul ou suivi d’une particule :</i> τὴν ἤτοι, IL. <i>2, 813 ;</i> τῶν ἤτοι, IL. <i>4, 237 ;</i> τόν ῥ' ἤτοι, IL. <i>18, 237 ;</i> τῷ δ' ἤτοι, HÉS. <i>O. 331 ;</i> οἱ δ' ἤτοι, IL. <i>12, 141 ; après un adv. ou une conj</i>. ἀλλ' ἤτοι, IL. <i>1, 140 ;</i> ἔνθ' ἤτοι, IL. <i>16, 399 ;</i> OD. <i>3, 126 ;</i> HÉS. <i>O. 166 ;</i> A. RH. <i>3, 1203 ;</i> OPP. <i>H. 3, 637 ;</i> καὶ νῦν ἤτοι, OD. <i>4, 151 ;</i> νῦν δ' ἤτοι, IL. <i>19, 23 ;</i> ὄφρ' ἤτοι, IL. <i>23, 52 ;</i> OD. <i>3, 419 ;</i> ὡς ἤτοι, OD. <i>5, 24 ;</i><br><b>   II</b> <i>conj. c</i>. ἤ τοι, ou en vérité : ἤτοι… ἤ, ESCHL. <i>Ch. 497 ;</i> SOPH. <i>Ant. 1142 ;</i> PLAT. <i>Phæd. 68</i> c, <i>etc</i>. ou en vérité… ou… ; <i>de même :</i> ἤτοι γε… ἤ, HDT. <i>1, 11 ;</i> THC. <i>2, 20 ; rar</i>. ἢ… ἤτοι, PD. <i>N. 6, 8 ; fr. 103 ; postér</i>. ἤτοι… ἤτοι, GAL.<br><span><b><span class=\"arrow\"></span></b> <i>Par crase</i> ἤτοι ἄν = ἠτἄν, SOPH. <i>O.C. 1366</i>.<br><span><b>Étym</b>. ἤ τοι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ητοι - ἤτοι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2274":"<h1>hettao</h1>\n<p>Strong n° 2274 <i>Prononciation [hayt-tah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rabaisser, rendre inférieur, vaincre\n<ol type=\"a\">\n<li>rendre inférieur</li>\n<li>être vaincu, avoir le dessous, être conquis par un autre, forcé de céder à quelqu'un</li>\n<li>tenir une chose pour inférieure</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἡττάω</b>, <i>v</i>. ἡσσάω.<br><br>\n<b>ἡσσάω</b>, <i>att</i>. <b>ἡττάω-ῶ</b> <span>(<i>f</i>. ἡσσήσω, <i>ao</i>. ἥσσησα, <i>pf</i>. ἥσσηκα ; <i>pass. f</i>. ἡσσηθήσομαι, <i>ao</i>. ἡσσήθην, <i>pf</i>. ἥσσημαι, <i>pl.q.pf</i>. ἡσσήμην)</span><br><b>   I</b> être inférieur à : τινος, EUR. <i>Alc. 697,</i> à qqn ; τι, XÉN. <i>Cyr. 1, 4, 5,</i> en qqe ch. ; τινός τινι, XÉN. <i>Cyr. 3, 3, 42, ou</i> ἔν τινι, <i>Cyr. 8, 2, 13,</i> à qqn en qqe ch. ; <i>avec un part. ;</i> τούτου οὐχ ἡττησόμεθα εὖ ποιοῦντες, XÉN. <i>An. 2, 3, 23,</i> nous ne nous laisserons pas vaincre par celui-ci en générosité ;<br><b>   II</b> <i>au sens pass</i>. être vaincu :<br><b>      1</b> <i>en parl. de guerre :</i> μάχῃ, HDT. <i>5, 46 ; ou</i> μάχην, DÉM. <i>444, 5,</i> dans un combat ;<br><b>      2</b> <i>devant un tribunal ou une assemblée,</i> SOPH. <i>Aj. 1242 ;</i> AR. <i>Pl. 482 ;</i> XÉN. <i>Mem. 4, 4, 17 ;</i> ἡττ. δίκην, PLAT. <i>Leg. 880</i> c ; DÉM. <i>1117, 5,</i> perdre son procès ;<br><b>      3</b> <i>en gén</i>. se laisser vaincre <i>ou</i> abattre ; ὕπνου, XÉN. <i>Cyr. 1, 5, 11 ;</i> τῶν ἡδονῶν, XÉN. <i>Ages. 5, 1,</i> par le sommeil, par le plaisir ; <i>ou avec une prép</i>. ὑπ' ἔρωτος, PLAT. <i>Phædr. 233</i> c ; πρός τινος, HDT. <i>9, 122 ;</i> πρός τι, PLAT. <i>Leg. 650</i> a, être vaincu <i>ou</i> se laisser vaincre par l’amour, par qqe ch. ; <i>d’où abs</i>. se laisser abattre : τῷ θυμῷ, τῇ γνώμῃ, HDT. <i>8, 130, etc. ;</i> τὴν γνώμην, THC. <i>6, 72,</i> céder au découragement ;<br><b>      4</b> se laisser vaincre par, s’éprendre de : τινος, ATH. <i>592</i> c ; PLUT. <i>M. 771</i> f, <i>773</i> c, d’une femme, d’une jeune fille.<br><span><b><span class=\"arrow\"></span></b> <i>Les formes att. sont en</i> ἡττ-, <i>ttef. dans un traité avec Naxos (entre 400 et 375 av. J.C.) on trouve la forme</i> ἡσσηθῇ, <i>v. Meisterh. p. 77, § 36, 2. — Act. réc</i>. ἡσσάω-ῶ, vaincre, POL. <i>1, 75, 3 ; 3, 18, 5 ;</i> DS. <i>15, 87. — Fut. moy. au sens pass</i>. ἡττήσομαι, XÉN. <i>An. 2, 3, 23 ;</i> LYS. <i>28, 9. — Formes ion. en</i> ἑ- <i>au lieu de</i> ἡ- <i>et sans augm. :</i> ἑσσοῦμαι, ἑσσώθην, ἕσσωμαι, HDT. <i>3, 106 ; 2, 169 ; 7, 10, etc</i>.<br><span><b>Étym</b>. ἧσσα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ητταω - ἡττάομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G2275":"<h1>hettema</h1>\n<p>Strong n° 2275 <i>Prononciation [hayt'-tay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une diminution, décroître, une défaite</li>\n<li>la perte, déchéance, l'amoindrissement en opposition au salut</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἥττημα, ατος (τὸ)</b> échec, défaite, SPT. <i>Esaï. 31, 9 ;</i> NT. <i>1Cor. 6, 7</i>.<br><span><b>Étym</b>. ἡττάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηττημα - ἥττημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2276":"<h1>hetton</h1>\n<p>Strong n° 2276 <i>Prononciation [hate'-ton]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>inférieur</li>\n<li>moindre, moins</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἥσσων</b>, <i>att</i>. <b>ἥττων, ων, ον</b>, <i>gén</i>. <b>ονος :<br>A</b> <i>adj. :</i><br><b>   I</b> inférieur à, moindre que, plus faible que, <i>d’où :</i><br><b>      1</b> inférieur, <i>en gén. :</i> τινός, IL. <i>16, 722,</i> inférieur à qqn, qui se laisse vaincre par qqn ; τινὸς ῥώμῃ, HDT. <i>8, 113,</i> inférieur en vigueur à qqn ; τινὸς ἔς τι, HDT. <i>3, 102,</i> inférieur en qqe ch., <i>ou avec l’acc. :</i> ἥσσων τὸν νοῦν, SOPH. <i>El. 1023,</i> (j’étais alors) trop faible de raison ; <i>avec un inf</i>. τινὸς θεῖν, HDT. <i>3, 105 ;</i> ἱππεύειν, XÉN. <i>Cyr. 1, 3, 15,</i> inférieur à qqn pour la course, pour l’équitation ; γνῶναι τὰ δέοντα, THC. <i>2, 60,</i> pour le sens des nécessités ;<br><b>      2</b> inférieur dans un combat, plus faible, vaincu, XÉN. <i>An. 5, 6, 13 ;</i> ἥ. ναυμαχίῃ, HDT. <i>5, 86,</i> vaincu dans un combat naval ;<br><b>      3</b> qui se laisse vaincre <i>ou</i> abattre : γαστρὸς ἢ οἴνου ἢ ἀφροδισίων ἢ πόνου ἢ ὕπνου, XÉN. <i>Mem. 1, 5, 1,</i> par la gourmandise ou par le vin ou par les plaisirs des sens ou par la fatigue ou par le sommeil ; ἥττων τῶν ἡδονῶν, PLAT. <i>Prot. 353</i> c ; τοῦ ἔρωτος, SOPH. <i>Tr. 489,</i> qui se laisse vaincre par les plaisirs, par l’amour ; τὸ ἧσσον, EUR. <i>Suppl. 379,</i> le mal ; <i>d’où</i> incapable de résister : τῶν πόνων, XÉN. <i>Hipp. 1, 3,</i> à la fatigue, <i>en parl. de chevaux ;</i> νόσων καὶ γήρως, LYS. <i>198, 5,</i> aux maladies et à la vieillesse ;<br><b>   II</b> <i>avec idée de quantité,</i> moins nombreux, ZÉNON (DL. <i>7, 23</i>) ;<br><b>B</b> <i>neutre adv</i>. ἧσσον, moins ; ἧσσόν τι, THC. <i>3, 75,</i> un peu moins ; οὐχ ἧσσον, ESCHL. <i>Ch. 181 ;</i> SOPH. <i>Aj. 672, etc. ;</i> THC. <i>1, 8 ;</i> οὐδὲν ἧσσον <i>ou</i> ἧττον, ESCHL. <i>Ag. 1391 ;</i> SOPH. <i>Aj. 276,</i> non moins, néanmoins ; καὶ μᾶλλον καὶ ἧττον, PLAT. <i>Prot. 356</i> a, plus ou moins ; οὐθ' ἧττον οὔτε μᾶλλον, PLAT. <i>Pol. 275</i> c, ni plus ni moins ; αἱ μὲν μᾶλλον, αἱ δὲ ἧττον, ARSTT. <i>Pol. 5, 7, 6,</i> les unes plus, les autres moins ; <i>qqf. avec un cp. :</i> ἧττον ἀκριϐέστερον, ARSTT. <i>Probl. 31, 2,</i> moins exact ; μοχθηρότερον ἧττον, PLAT. <i>Leg. 852</i> e, moins pénible ; <i>cf</i>. DH. <i>3, 43</i>.<br><span><b>Étym</b>. <i>Compar. de</i> ἦκα, <i>cf</i>. ἥκιστα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηττον - ἥσσων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2277":"<h1>eto</h1>\n<p>Strong n° 2277 <i>Prononciation [ay'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>qu'il soit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ητο - ἤτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2278":"<h1>echeo</h1>\n<p>Strong n° 2278 <i>Prononciation [ay-kheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>résonner, retentir\n<ol type=\"a\">\n<li>utilisé pour le bruit de la mer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἠχέω-ῶ :<br>      1</b> résonner, retentir, <i>en parl. du tonnerre,</i> HÉS. <i>Th. 42 ; de la mer,</i> MOSCH. <i>5, 4 ; d’un bouclier d’airain,</i> HDT. <i>4, 200 ; de plaques d’airain,</i> PLAT. <i>Prot. 329</i> a ; <i>particul</i>. résonner, chanter, <i>en parl. de la cigale,</i> THCR. <i>Idyl. 16, 96 ; ou de la lyre,</i> AR. <i>Th. 327 ;</i><br><b>      2 <i>tr.</i></b> faire retentir, faire résonner : χαλκέον, THCR. <i>Idyl. 2, 36,</i> des cymbales d’airain ; μέλος, EUR. <i>Ion 883,</i> un chant ; κωκυτόν, SOPH. <i>Tr. 866 ;</i> γόους, SOPH. <i>fr. 469,</i> des lamentations, des gémissements ; <i>au pass</i>. être émis, <i>en parl. d’un son, d’où</i> retentir, SOPH. <i>O.C. 1500 ;</i><br><b><i>Moy.</i></b> faire retentir les louanges de : τινα, PD. <i>fr. 45, 18,</i> de qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. 3 sg. poét</i>. ἤχεε, HÉS. <i>Th. 835 ; impf. itér. 3 sg</i>. ἠχέεσκε, HDT. <i>4, 200. Dor</i>. ἀχέω <span>[ᾱ]</span> PD. THCR. MOSCH. <i>ll. cc</i>.<br><span><b>Étym</b>. ἦχος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηχεω - ἠχέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2279":"<h1>echos</h1>\n<p>Strong n° 2279 <i>Prononciation [ay'-khos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un son, un bruit, un éclat\n<ol type=\"a\">\n<li>se dit pour le bruit des vagues</li>\n</ol>\n</li>\n<li>rumeur, rapport</li>\n<li>renommée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἦχος, ου (ὁ) :<br>      1</b> bruit, son, ARSTT. <i>Aud. 67 ;</i> THCR. <i>Idyl. 27, 56 ; en parl. d’une flûte,</i> MOSCH. <i>2, 98 ; d’une source,</i> MOSCH. <i>5, 12 ; du son de la voix,</i> LUC. <i>Nigr. 7 ; ttef. distinct de</i> φωνή, PLUT. <i>M. 903</i> a ; οἱ ἦχοι, les sons, <i>p. opp. aux lettres</i> (τὰ γράμματα) D. PHAL. <i>§ 71 ;</i><br><b>      2</b> <i>particul</i>. bourdonnement dans les oreilles, <i>sg. et pl</i>. HPC. <i>68</i> g, <i>144</i> a, <i>149</i> c ; ARÉT. <i>p. 1, 24 ; 32, 38 ;</i><br><b>      3</b> écho, ARSTT. <i>Probl. 11, 8 ;</i> PLUT. <i>M. 903</i> a.<br><span><b>Étym</b>. <i>cf</i>. ἠχώ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ηχος - ἦχος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2280":"<h1>Thaddaios</h1>\n<p>Strong n° 2280 <i>Prononciation [thad-dah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Thaddée (Angl. Thaddaeus) = « grand cœur, courageux »\n<ol>\n<li>un des douze apôtres, surnom de Jude (Judas) non l'Iscariot (<a class=\"ref\" data-r=\"JUD1.1\">Jude 1.1</a>)</li>\n<li>appelé également Lebbée (voir définition )</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Θαδδαιος - Θαδδαῖος</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2281":"<h1>thalassa</h1>\n<p>Strong n° 2281 <i>Prononciation [thal'-as-sah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la mer\n<ol type=\"a\">\n<li>pour la mer en général</li>\n<li>en particulier la Méditerranée ou la Mer Rouge</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θάλασσα</b>, <i>att</i>. <b>θάλαττα, ης (ἡ)</b> <span>[ᾰ]</span><br><b>   I</b> mer :<br><b>      1</b> <i>propr</i>. la mer : εὐρύπορος, vaste, OD. <i>4, 432 ;</i> ἀτρύγετος, inféconde, stérile, IL. <i>14, 204 ;</i> πολιά, blanche, PD. <i>O. 7, 113 ;</i> πολιαινομένη, blanchissante, ESCHL. <i>Pers. 109 ;</i> ἁλμυρά, salée, EUR. <i>Tr. 438, etc. ; p. opp. à</i> γαῖα, HÉS. <i>O. 101 ; à</i> γῆ, PLAT. <i>Soph. 234</i> a ; PLUT. <i>M. 340</i> f ; <i>à</i> χέρσος, ESCHL. <i>Eum. 240 ; à</i> μεσόγεια, DÉM. <i>69, 2, 3 ; à</i> χθών, ESCHL. <i>Ag. 576, etc. ;</i> κατὰ θάλασσαν, par mer, <i>p. opp. à</i> πεζῇ (par terre) HDT. <i>5, 63 ; à</i> κατὰ γῆς, THC. <i>7, 28 ; à</i> κατὰ γῆν, PLAT. <i>Menex. 241</i> a ; οἱ περὶ τὴν θάλ. ARSTT. <i>H.A. 8, 13, 12,</i> les hommes de mer ; <i>avec la locut</i>. τὸ παρὰ θάλασσαν, « le littoral », <i>le nom du lieu dont on mentionne le littoral se place d’ord. par inversion avant cette locut. :</i> Αἰγύπτου τὸ παρὰ θάλασσαν, HDT. <i>2, 6 et 9 ;</i> Ἀραϐίης τὸ παρὰ θάλασσαν, HDT. <i>2, 12 ;</i> τῆς Συρίης τὸ παρὰ θάλασσαν, HDT. <i>7, 89 ;</i> le littoral de l’Égypte, de l’Arabie, de la Syrie ; <i>rar. après :</i> τὸ παρὰ θάλασσαν αὐτῆς, HDT. <i>2, 15,</i> le littoral de ce pays ; <i>cf</i>. STR. <i>1134 ;</i> D. SIC. <i>1, 55 ;</i> SCYL. <i>1, 43 Geogr. min. Didot) ; particul. dans Hom</i>. la Méditerranée (<i>p. opp. à l’</i>Océan) ; <i>cf</i>. ἥδε ἡ θάλασσα (<i>cf. lat</i>. nostrum mare) HDT. <i>1, 1 ; 4, 39, etc. ;</i> APP. <i>Pr. 2, etc. ;</i> ἡ καθ' ἡμᾶς θάλ. POL. <i>1, 3, 9 ;</i> ἡ θάλ. ἡ καθ' ἡμᾶς, D. CHR. <i>Or. 32, p. 372 ;</i> ἡ παρ' ἡμῖν θάλ. PLAT. <i>Phæd. 113</i> a, cette mer-ci, la mer de notre pays, <i>càd</i>. la Méditerranée ; ἡ ἐντὸς θάλ. APP. <i>Pr. 5 ; Mithr. 93, 94 ;</i> ἡ ἔσω θάλ. ARSTT. <i>Mund. 3, 8,</i> la mer intérieure, <i>càd</i>. la Méditerranée ; ἡ ἔξω θάλ. ARSTT. <i>Meteor. 13, 14 ;</i> POL. <i>3, 57, 2 ; 16, 29, 9 ;</i> ἡ μεγάλη θάλ. PLUT. <i>Alex. 73,</i> la mer extérieure, la grande mer, <i>càd</i>. l’Océan ;<br><b>      2</b> <i>fig</i>. κακῶν θάλ. ESCHL. <i>Sept. 758,</i> une mer de maux ;<br><b>   II</b> eau de mer, MOSCHION HIST. (ATH. <i>208</i> a) ; POL. <i>16, 5, 4 ; d’où</i> l’eau salée, <i>en gén</i>. DIPH. (ATH. <i>121</i> d) ; <i>cf</i>. DIOSC. <i>2, 105 ;</i><br><b>   III</b> <i>p. ext</i>. source d’eau salée dans l’Erekhtheion, <i>à Athènes,</i> HDT. <i>8, 55 ; appelée aussi</i> θ. Ἐρεχθηΐς, APD. <i>3, 14</i>.<br><span><b><span class=\"arrow\"></span></b> ATT. θάλαττα (XÉN. PLAT. DÉM. <i>ll. cc., etc., mais non dans Thucydide). Ion., poét. et anc. att</i>. θάλασσα (HOM. HÉS. HDT. ESCHL. THC. <i>ll. cc. etc.) ; ttef. la forme</i> θάλασσα, <i>remplacée très anciennement en att. par</i> θάλαττα, <i>dont les ex. se rencontrent dès le 5<sup>e</sup> siècle av. J.C</i>. (CIA. <i>1, 40, 19, de 424 av. J.C., etc. ; v. Meisterh. p. 77, § 77, 2, note 728) s’est conservée dans un serment des Athéniens au temps d’Alexandre le Grand,</i> CIA. <i>2, 160, 6 (336 av. J.C.) ; dans les serments par lesquels les peuples étrangers s’engageaient avec les Athéniens, par ex. dans un serment des Corcyréens,</i> CIA. <i>2, add. 48, 28 (375 av. J.C.) ; v. Meisterh. p. 77, § 36, 2</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαλασσα - θάλασσα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n92 fois dans 83 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (17)</li>\n<li>Marc (19)</li>\n<li>Luc (3)</li>\n<li>Jean (9)</li>\n<li>Actes (10)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (26)</li>\n</ul>\n</td></tr>\n</table>","G2282":"<h1>thalpo</h1>\n<p>Strong n° 2282 <i>Prononciation [thal'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chauffer, garder au chaud</li>\n<li>chérir d'un tendre amour, prendre particulièrement soin, soigner tendrement avec affection</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θάλπω</b> <span>(<i>f</i>. θάλψω, <i>ao</i>. ἔθαλψα, <i>pf. inus. ; pass. ao. part</i>. θαλφθείς)</span><br><b>   I <i>tr</i>.<br>      1</b> chauffer, échauffer, <i>acc</i>. OD. <i>21, 179, 184, 246 ;</i> SOPH. <i>Tr. 697 ; au pass</i>. être chauffé, SOPH. <i>Ph. 38 ;</i> κασσίτερος θαλφθείς, HÉS. <i>Th. 864,</i> étain qui a été chauffé ; <i>en parl. de la chaleur du soleil, de l’été,</i> SOPH. <i>Ant. 417 ;</i> XÉN. <i>Cyr. 1, 5, 11 ;</i> AR. <i>Av. 1092 ; en parl. de la chaleur du corps :</i> θάλπειν ᾠά, GEOP. <i>14, 1, 4, ou abs</i>. θάλπειν, GEOP. <i>14, 1, 3,</i> faire éclore des œufs par la chaleur de l’incubation ;<br><b>      2</b> chauffer au soleil, faire sécher : ἁλίῳ πέπλους, EUR. <i>Hel. 183,</i> des habits au soleil ;<br><b>      3</b> <i>fig</i>. échauffer, enflammer (de passion, de désir, <i>etc.) particul. chez les Trag</i>. ESCHL. <i>Pr. 590, etc. ;</i> θ. ἱμέρου βέλει, ESCHL. <i>Pr. 650 ;</i> πυρί, SOPH. <i>El. 888,</i> brûler des traits du désir, du feu (d’une joie insensée) ; ἐμὲ οὐδὲν θάλπει ἡ δόξα, ALCIPHR. <i>2, 2,</i> l’amour de la gloire, ne m’enflamme en rien ;<br><b>      4</b> réchauffer de son affection THCR. <i>Idyl. 14, 38 ;</i> ALCIPHR. <i>2, 4 ; d’où</i> réjouir, consoler, SYN. <i>Ep. 19 ;</i><br><b>   II</b> <i>intr. (ou s.-e</i>. ἑαυτόν) :<br><b>      1</b> se réchauffer (au soleil) <i>en parl. d’un vieillard,</i> ANTH. <i>7, 731 ;</i><br><b>      2</b> se tenir chaud, <i>càd</i>. rester vigoureux, ARSTT. <i>Probl. 4, 25</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. prés. 2 sg. ion. et dor</i>. θάλπεαι, THCR. <i>Idyl. 5, 31</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαλπω - θάλπω</font>\n<br><br>probablement parent de 'thallo' (chauffer)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G2283":"<h1>Thamar</h1>\n<p>Strong n° 2283 <i>Prononciation [tham'-ar]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Thamar (Angl. Tamar) = « palmier »\n<ol>\n<li>épouse de Juda, qui engendra Pharès et Zara</li>\n<li>voir également Tamar, épouse des fils de Juda, Er et Onan.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Θαμαρ</font> &lt; תמר - <font face=\"Georgia\">Θαμάρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2284":"<h1>thambeo</h1>\n<p>Strong n° 2284 <i>Prononciation [tham-beh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être étonné</li>\n<li>étonner, terrifier\n<ol type=\"a\">\n<li>être stupéfait</li>\n<li>être effrayé, frapper d'effroi, être saisi de crainte</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θαμϐέω-ῶ</b> <span>(<i>impf</i>. ἐθάμϐουν, <i>f. inus., ao</i>. ἐθάμϐησα, <i>pf</i>. τεθάμϐηκα ; <i>pass. ao</i>. ἐθαμϐήθην, <i>pf</i>. τεθάμϐημαι)</span><br><b>      1</b> être frappé, d’étonnement, de stupeur, IL. <i>8, 77 ;</i> OD. <i>4, 638 ;</i> SOPH. <i>Ant. 1246 ;</i> τι, OD. <i>2, 155 ;</i> ESCHL. <i>Suppl. 570 ;</i> PD. <i>N. 3, 48 ;</i> EUR. <i>Ion 1205 ;</i> PLUT. <i>Æmil. 34,</i> regarder qqe ch. avec étonnement <i>ou</i> stupeur ;<br><b>      2 <i>tr.</i></b> frapper de stupeur <i>ou</i> d’effroi, SPT. <i>2Reg. 22, 5 ; d’où au pass</i>. être frappé de stupeur <i>ou</i> d’effroi, PLUT. <i>Brut. 20 ;</i> διά τινος, PLUT. <i>Cæs. 45,</i> par qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. poét</i>. ἐθάμϐεον, OD. <i>4, 638 ; 17, 367 ; ao. poét. 3 sg</i>. θάμϐησεν, IL. <i>24, 483 ;</i> EUR. <i>Ion 1205 ; 3 pl. poét</i>. θάμϐησαν, IL. <i>23, 728 ; 24, 484</i>.<br><span><b>Étym</b>. θάμϐος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαμβεω - θαμβέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (3)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2285":"<h1>thambos</h1>\n<p>Strong n° 2285 <i>Prononciation [tham'-bos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>figer de peur, immobiliser</li>\n<li>stupeur, épouvante, saisissement, crainte (sacrée)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>θάμϐος, εος-ους (τὸ)</b> effroi, étonnement, stupeur, <i>d’où particul</i>. admiration, IL. <i>4, 79 ;</i> OD. <i>3, 372 ;</i> PLAT. <i>Phædr. 254</i> c, <i>etc. ; avec un gén</i>. THC. <i>6, 31 ;</i> PLUT. <i>Cæs. 32, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén</i>. ép. θάμϐευς, OD. <i>24, 394</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span><br><br>\n➁ <b>θάμϐος, ου (ὁ)</b> <i>c</i>. θάμϐος SIM. <i>fr. 238 ;</i> SPT. <i>Eccl. 12:5, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαμβος - θάμβος</font>\n<br><br>parent du mot désuet 'tapho' (abasourdir)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2286":"<h1>thanasimos</h1>\n<p>Strong n° 2286 <i>Prononciation [than-as'-ee-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui donne la mort, mortel (accident, malheur)</li>\n<li>qui concerne la mort</li>\n<li>qui est près de la mort, moribond, mourant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θανάσιμος, ος, ον</b> <span>[ᾰᾰ]</span><br><b>   I</b> qui donne la mort, mortel (accident, malheur, SOPH. <i>Aj. 1033, O.R. 560 ;</i> tunique de Nessus, SOPH. <i>Tr. 758</i>) ; φάρμακα θ. EUR. <i>Ion 616,</i> poisons mortels ; θηρία, POL. <i>1, 56, 4,</i> reptiles dont le venin est mortel ; θανάσιμα δάκνειν, DS. <i>1, 87,</i> faire une morsure qui cause la mort ;<br><b>   II</b> qui concerne la mort, <i>càd. :</i><br><b>      1</b> de mort ; θ. μόρος, EUR. <i>Hec. 1135 ;</i> θ. τύχαι, ESCHL. <i>Ag. 1276,</i> la mort ; γόος θ. ESCHL. <i>Ag. 1445,</i> gémissement de mort ;<br><b>      2</b> qui est près de la mort, moribond, mourant, SOPH. <i>Ph. 819 ;</i> PLAT. <i>Rsp. 408</i> c ;<br><b>      3</b> mort, SOPH. <i>Aj. 517, O.R. 959</i>.<br><span><b>Étym</b>. θάνατος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θανασιμος - θανάσιμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2287":"<h1>thanatephoros</h1>\n<p>Strong n° 2287 <i>Prononciation [than-at-ay'-for-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>apportant la mort, mortel</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θανατη·φόρος, ος, ον</b> <span>[ᾰᾰ]</span><br><b>      1</b> qui porte <i>ou</i> donne la mort, ESCHL. <i>Ch. 369 ;</i> SOPH. <i>O.R. 181 ;</i> XÉN. <i>Hell. 2, 3, 17, etc. ;</i><br><b>      2</b> <i>p. suite,</i> de mort, ANTH. <i>11, 186</i>.<br><span><b>Étym</b>. θάνατος, φέρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θανατηφορος - θανατηφόρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2288":"<h1>thanatos</h1>\n<p>Strong n° 2288 <i>Prononciation [than'-at-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la mort du corps\n<ol type=\"a\">\n<li>cette séparation (naturelle ou violente) de l'âme et du corps par laquelle se termine la vie sur la terre</li>\n<li>avec l'idée implicite de misère future en enfer\n<ol>\n<li>le pouvoir de la mort</li>\n</ol>\n</li>\n<li>le monde souterrain, la demeure de la mort, était représenté comme très noir, l'équivalent de la région des épaisses ténèbres, région enveloppée de l'obscurité de l'ignorance et du péché</li>\n</ol>\n</li>\n<li>métaph., la perte de la vie terrestre\n<ol type=\"a\">\n<li>misère de l'âme coupable de péché, qui commence sur la terre mais continue et s'accroît après la mort du corps, en enfer</li>\n</ol>\n</li>\n<li>l'état misérable du méchant en enfer</li>\n<li>dans un sens plus large, la mort qui inclue toutes les misères provenant du péché, tant la mort physique que la négation d'une vie consacrée à Dieu, bénie par lui sur terre, et qui sera suivie de misère en enfer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θάνατος, ου (ὁ)</b> <span>[ᾰᾰ]</span><br><b>   I</b> la mort, <i>càd. :</i><br><b>      1</b> mort naturelle <i>ou</i> autre, OD. <i>12, 446, etc. ; p. opp. à</i> βίος, SOPH. <i>Aj. 802 ; à</i> ζωά, PD. <i>N. 9, 68, ou</i> ζωή, PLAT. <i>Leg. 904</i> e ; <i>plur. au sens du sg</i>. θανάτοις αὐθένταισι, ESCHL. <i>Ag. 1572,</i> par une mort volontaire, par un suicide ; <i>fig</i>. θάνατος τάδ' ἀκούειν, SOPH. <i>O.C. 529,</i> c’est une mort d’entendre cela ;<br><b>      2</b> peine de mort : περὶ θανάτου διώκειν, XÉN. <i>Hell. 7, 5, 6,</i> poursuivre pour une cause capitale ; θανάτου κρίνεσθαι, THC. <i>3, 57 ;</i> XÉN. <i>Cyr. 1, 2, 14,</i> être jugé pour une affaire capitale ; κρίνεσθαι τὴν ἐπὶ θανάτῳ (<i>s.-e</i>. δίκην) ATH. <i>590</i> d, <i>m. sign. ;</i> θάνατον καταγιγνώσκειν τινός, THC. <i>3, 81,</i> prononcer contre qqn la peine de mort ; θάνατος ἡ ζημία ἐπίκειται, ISOCR. <i>169</i> c, la pénalité est la mort ; <i>avec la locut</i>. ἡ ἐπὶ θανάτῳ, <i>on sous-entend un subst. de même sens que le verbe :</i> δεῖν τὴν ἐπὶ θανάτῳ (<i>s.-e</i>. δέσιν) HDT. <i>3, 119, ou</i> καταδεῖν, HDT. <i>5, 72,</i> lier qqn pour le mener au supplice ; <i>fig. ou p. anal</i>. ὁ δεύτερος θάνατος, la seconde mort, <i>càd</i>. la perdition, au sens religieux, NT. <i>Apoc. 2, 11 ; mais, dans Plutarque,</i> la séparation de l’intelligence, νοῦς, d’avec l’âme, ψυχή (la première mort étant la séparation de l’âme, ψυχή, d’avec le corps, σῶμα, PLUT. <i>M. 942</i> f) ;<br><b>   II</b> corps mort, ANTH. <i>9, 439 ;</i><br><b>   III</b> <i>plur</i>. οἱ θάνατοι :<br><b>      1</b> genres de mort, OD. <i>12, 341 ;</i><br><b>      2</b> meurtre de plusieurs personnes, ESCHL. <i>Ch. 53 ;</i> SOPH. <i>O.R. 1200 ;</i> EUR. <i>Her. 629 ; ou</i> d’une seule, SOPH. <i>O.R. 496, El. 206 ; cf</i>. PLAT. <i>Rsp. 399</i> a ;<br><b>      3</b> peine de mort : πολλῶν θανάτων ἄξιος καὶ οὐχ ἑνός, DÉM. <i>521, 24,</i> qui mérite mille morts et non pas une seule ; <i>cf</i>. DÉM. <i>545, 25 ;</i> AR. <i>Pl. 483</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *d<sup>h</sup>(u)enh₂-, mourir ; <i>cf</i>. θνῄσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θανατος - θάνατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n119 fois dans 106 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (6)</li>\n<li>Luc (7)</li>\n<li>Jean (8)</li>\n<li>Actes (8)</li>\n<li>Romains (22)</li>\n<li>1 Corinthiens (7)</li>\n<li>2 Corinthiens (9)</li>\n<li>Philippiens (6)</li>\n<li>Colossiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (10)</li>\n<li>Jacques (2)</li>\n<li>1 Jean (6)</li>\n<li>Apocalypse (19)</li>\n</ul>\n</td></tr>\n</table>","G2289":"<h1>thanatoo</h1>\n<p>Strong n° 2289 <i>Prononciation [than-at-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre à mort</li>\n<li>métaph.\n<ol type=\"a\">\n<li>faire mourir, c.à.d détruire, éteindre</li>\n<li>être libéré, comme par la mort, de l'esclavage de toute chose, littéralement être mort à quelque chose</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θανατόω-ῶ</b> <span>[ᾰᾰ]</span><br><b>   I <i>tr. :</i><br>      1</b> faire mourir, <i>acc</i>. HDT. <i>1, 113 ;</i> ESCHL. <i>Pr. 1053 ; en parl. du bourreau,</i> PLAT. <i>Leg. 872</i> c ;<br><b>      2</b> condamner à mort, XÉN. <i>An. 2, 6, 4 ;</i> PLAT. <i>Leg. 868</i> c, <i>etc. ;</i><br><b>      3</b> mortifier (la chair) NT. <i>Rom. 8, 13 ;</i><br><b>   II <i>intr.</i></b> être mort, SPT. <i>Eccl. 10, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy. opt. 3 sg. au sens pass</i>. θανατώσοιτο, XÉN. <i>Cyr. 7, 5, 31 ; fut. pass. réc</i>. θανατωθήσομαι, SPT. <i>Lev. 27, 29, etc</i>.<br><span><b>Étym</b>. θάνατος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θανατοω - θανατόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Romains (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2290":"<h1>thapto</h1>\n<p>Strong n° 2290 <i>Prononciation [thap'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>enterrer, ensevelir, mettre au tombeau, donner la sépulture</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θάπτω</b> <span>(<i>f</i>. θάψω, <i>ao</i>. ἔθαψω, <i>pf. inus. ; pass. f. 2</i> ταφήσομαι, <i>ao.1</i> ἐθάφθην, <i>ao.2</i> ἐτάφην, <i>pf</i>. τέθαμμαι, <i>f. antér</i>. τεθάψομαι)</span><br><b>   I</b> rendre les honneurs funèbres à, <i>acc</i>. IL. <i>21, 323 ;</i> OD. <i>12, 12, etc. ;</i> HÉS. <i>Sc. 472 ;</i> HDT. <i>2, 41 ;</i> THC. <i>8, 84 ;</i> ESCHL. <i>Sept. 1008, etc. ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> enterrer, OD. <i>11, 52 ;</i><br><b>      2</b> mettre un corps sur le bûcher : πυρὶ θ. PLUT. <i>M. 286</i> e, brûler un corps.<br><span><b><span class=\"arrow\"></span></b> <i>ao.1 pass. ion. et rare</i> ἐθάφθην, SIM. <i>fr. 168 Bgk ;</i> HDT. <i>2, 81 ; 3, 55 ; 7, 228. Dans les inscr. att. seul. inf. ao.2 pass</i>. ταφῆναι (<i>non</i> θαφθῆναι) <i>v. Meisterh. p. 150, 71. Pf. 3 pl. ion</i>. τεθάφαται, HDT. <i>6, 103</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *d<sup>h</sup>emb<sup>h</sup>-, creuser, ensevelir ; <i>cf</i>. τάφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαπτω - θάπτω</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (3)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2291":"<h1>Thara</h1>\n<p>Strong n° 2291 <i>Prononciation [thar'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Thara (Angl. Terah) = « halte, délai, retard »\n<ol><li>le père d'Abraham</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Θαρα</font> &lt; תרח - <font face=\"Georgia\">Θάρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2292":"<h1>tharrheo</h1>\n<p>Strong n° 2292 <i>Prononciation [thar-hreh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir un bon courage, plein de confiance, être résolu, courageux</li>\n<li>être hardi, audacieux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θαρρέω</b>, <i>ion. et anc. att</i>. <b>θαρσέω-ῶ</b>, avoir confiance, être résolu, hardi, courageux :<br><b>      1</b> <i>en b. part, se construit abs</i>. IL. <i>1, 92, etc. ;</i> THC. <i>3, 25 ;</i> θάρσει, IL. <i>24, 171 ;</i> θάρσει, ESCHL. <i>Suppl. 732, etc. ;</i> SOPH. <i>El. 173, etc</i>. bon courage ! aie confiance ; θάρρει, PLAT. <i>Menex. 249</i> c ; LUC. <i>D. mort. 17 fin,</i> sois tranquille (je ne dirai rien ou ne ferai rien contre toi ; tu n’as rien à craindre, <i>etc.) ; qqf. entre parenthèses :</i> ὥστε, θάρρει, <i>etc</i>. PLAT. <i>Prot. 311</i> a, ainsi, sois tranquille ; θαρσήσας μάλα εἰπέ, IL. <i>1, 85,</i> aie confiance et dis (nous) ; λέγε θαρρῶν, PLAT. <i>Phædr. 243</i> e, parle avec confiance ; τὸ τεθαρρηκός, PLUT. <i>Fab. 16 ;</i> τὸ θαρροῦν, PLUT. <i>Cato mi. 44,</i> la confiance ; <i>avec</i> θάρρος <i>et un adj. :</i> ἀνόητον θάρρος θαρρεῖν, PLAT. <i>Phæd. 95</i> c, avoir une confiance insensée ; <i>avec un dat. :</i> θ. τινι, HDT. <i>3, 76,</i> avoir confiance en qqn <i>ou</i> qqe ch. ; <i>avec un acc. de pers. ou de ch. :</i> τινα, XÉN. <i>Cyr. 5, 5, 42 ;</i> DÉM. <i>30, 16 ;</i> DC. <i>51, 11,</i> avoir confiance en qqn ; τι, OD. <i>8, 197 ;</i> HDT. <i>7, 50 ;</i> XÉN. <i>An. 3, 2, 20 ;</i> PLAT. <i>Phæd. 88</i> b, <i>etc</i>. affronter résolûment qqe ch. (la mort, un combat, <i>etc.) ; avec une prép. :</i> τινὸς ἕνεκα, ESCHL. <i>Suppl. 993 ;</i> PLAT. <i>Soph. 242</i> b ; περί τινος, SOPH. <i>Aj. 780 ;</i> ISOCR. <i>125</i> e ; ὑπέρ τινος, XÉN. <i>Cyr. 7, 1, 17 ;</i> PLAT. <i>Rsp. 566</i> b ; ἐπί τινι, ISOCR. <i>128</i> d ; πρός τι, PLAT. <i>Prot. 350</i> b ; διά τι, ISOCR. <i>38</i> c, avoir confiance au sujet de qqn <i>ou</i> de qqe ch. ; <i>avec</i> ὅτι, THC. <i>1, 81,</i> avoir confiance que ; <i>avec une prop. inf</i>. SOPH. <i>Ant. 668,</i> avoir la confiance que ; <i>au pass</i>. être l’objet de la confiance, inspirer confiance, PHILSTR. <i>788 ;</i><br><b>      2</b> <i>en mauv. part,</i> être hardi, audacieux, THC. <i>2, 65 ;</i> PLAT. <i>Men. 88</i> b, <i>Theæt. 189</i> d.<br><span><b><span class=\"arrow\"></span></b> θαρρέω <i>att</i>. (XÉN. PLAT. AR. LUC. <i>etc. ll. cc</i>.) ; θαρσέω <i>ion</i>. HDT. <i>3, 76, et anc. att</i>. THC. <i>3, 25, etc. ; (ttef</i>. θαρρέω <i>très ancien, comme on peut le supposer d’après le n. propre Θαρρίας conservé dans une inscr. att</i>. CIA. <i>1, 445, milieu du 5<sup>e</sup> siècle av. J.C. ; v. Meisterh. p. 76, 5) ; épq</i>. HOM. <i>ll. cc., et usité chez les Trag</i>. ESCHL. SOPH. <i>ll. cc</i>.<br><span><b>Étym</b>. θάρρος, <i>cf</i>. θέρσημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαρρεω - θαρρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (5)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2293":"<h1>tharseo</h1>\n<p>Strong n° 2293 <i>Prononciation [thar-seh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avoir du courage, avoir confiance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θαρσέω</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαρσεω - θαρσέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2294":"<h1>tharsos</h1>\n<p>Strong n° 2294 <i>Prononciation [thar'-sos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>courage, confiance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θάρσος</b>, <i>v</i>. θάρρος.<br><br>\n<b>θάρρος</b>, <i>ion. et anc. att</i>. <b>θάρσος, εος-ους (τὸ) :<br>   I</b> <i>pass</i>. confiance, résolution, assurance, hardiesse ; <i>différ. de</i> ἀνδρεία, PLAT. <i>Prot. 351</i> a ; <i>p. opp. à</i> φόϐος, PLAT. <i>Leg. 644</i> c ; ARSTT. <i>Nic. 3, 6 :</i><br><b>      1</b> <i>en b. part,</i> HOM. (<i>v. ci-dessous</i>) ; ATT. (<i>v. ci-dessous) ; au plur</i>. EUR. <i>I.T. 1282 ;</i> PLAT. <i>Prot. 360</i> b ; τινός, confiance en vue de qqe ch. ESCHL. <i>Ch. 91, etc. ou</i> τινός, en face de qqn, contre qqn, PLAT. <i>Leg. 647</i> b ; πρός τινα, XÉN. <i>Cyr. 4, 2, 15,</i> en face de qqn ; θάρσος ἐμπνεῖν, OD. <i>9, 381,</i> inspirer de la hardiesse ; ἐν κραδίῃ θάρσος βάλλειν, IL. <i>21, 547,</i> jeter de la hardiesse dans le cœur ; ἐνὶ φρεσὶ θάρσος θῆκε, OD. <i>3, 76, ou</i> ἐνὶ στήθεσσιν ἐνῆκεν, IL. <i>17, 570,</i> il (ou elle) jeta dans son âme l’audace ; θάρρος ἐμποιεῖν, XÉN. <i>An. 6, 3, 17 ; ou</i> παρασχεῖν τινι, THC. <i>6, 68,</i> donner bon courage à qqn, inspirer de la confiance à qqn ; θάρσος λαμϐάνει τινά, THC. <i>2, 92 ;</i> ἐγγίγνεται, XÉN. <i>Cyr. 4, 2, 15 ;</i> ἐμφύεταί τινι, XÉN. <i>Cyr. 5, 2, 32 ; ou</i> ἐμπίπτει τινί, XÉN. <i>Hell. 7, 1, 21,</i> la confiance s’empare de qqn ;<br><b>      2</b> <i>rar. en mauv. part,</i> hardiesse, audace (<i>en ce sens d’ord</i>. θράσος) IL. <i>17, 570 ; 21, 395 ; joint à</i> ὀργή, ARSTT. <i>Rhet. 2, 10 ;</i><br><b>   II</b> <i>act</i>. ce qui donne confiance <i>ou</i> bon courage, ESCHL. <i>Sept. 270 ; au plur</i>. EUR. <i>I.T. 1283 ;</i> PLAT. <i>Prot. 360</i> b.<br><span><b><span class=\"arrow\"></span></b> θάρσος <i>et ses dérivés sont plutôt ion. et dor. ; usités chez les Trag. et dans Thucydide ; θάρρος et ses dérivés sont propres au dialecte attique</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *d<sup>h</sup>ers-, audacieux ; <i>cf. sscr</i>. dhr̥ṣṇú-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαρσος - θάρσος</font>\n<br><br>parent (par transp.) de 'thrasos' (audacieux)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2295":"<h1>thauma</h1>\n<p>Strong n° 2295 <i>Prononciation [thos'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une chose merveilleuse, une merveille, objet d'étonnement</li>\n<li>être étonné\n<ol type=\"a\">\n<li>s'étonner très fortement</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θαῦμα, ατος (τὸ) :<br>   I</b> objet d’étonnement <i>ou</i> d’admiration, <i>en b. ou en mauv. part, càd. :</i><br><b>      1</b> objet merveilleux <i>ou</i> monstrueux (<i>en b. part,</i> OD. <i>11, 287 ; en mauv. part,</i> OD. <i>9, 190</i>) ; ATT. ; θαῦμα ἰδεῖν, HÉS. <i>Sc. 318 ;</i> θαῦμα ἀκοῦσαι, PD. <i>P. 1, 50 ;</i> PLAT. <i>Leg. 656</i> d, chose merveilleuse à voir, à entendre ; θαῦμ' ὅτι, THCR. <i>Idyl. 15, 2,</i> il est étrange que ; οὐ θαῦμα, PD. <i>N. 10, 94 ;</i> θαῦμά γ' οὐδέν, SOPH. <i>O.R. 1319 ;</i> AR. <i>Pl. 99 ;</i> οὐδέν γε θαῦμα, SOPH. <i>O.R. 1132,</i> il n’y a pas de quoi s’étonner, il n’y a rien d’étonnant ; <i>avec une prop. inf</i>. τὸ μὴ πείθεσθαι τοὺς πολλοὺς θαῦμα οὐδέν, PLAT. <i>Rsp. 498</i> d, que la foule ne se laisse pas persuader, il n’y a là rien d’étonnant ; <i>poét. au plur</i>. θαυμάτων κρείσσονα, EUR. <i>Bacch. 666 ;</i> θαυμάτων πέρα, EUR. <i>Hec. 714,</i> choses extraordinaires et qui passent les bornes ;<br><b>      2</b> <i>particul. au plur</i>. τὰ θαύματα, tours de force <i>ou</i> d’adresse, tours prestigieux, XÉN. <i>Conv. 2, 1 ;</i> PLAT. <i>Rsp. 514</i> b ; ATH. <i>22 ; d’où</i> le lieu, la baraque où les charlatans font leurs tours, TH. <i>Char. 6, 4 ;</i> ATH. <i>452</i> f ;<br><b>      3</b> <i>postér. au sens chrétien,</i> miracle, NYSS. <i>3, 904, 933 ;</i> CHRYS. <i>7, 6 ; 9 ; 432, 585 ;</i><br><b>   II</b> étonnement, admiration, surprise : θαῦμά μ' ἔχει, OD. <i>10, 326 ;</i> SOPH. <i>Ph. 687 ;</i> PLAT. <i>Phil. 36</i> d ; λαμϐάνει, AR. <i>Av. 511, ou</i> ὑποδύεται, SOPH. <i>El. 928,</i> l’étonnement me saisit, m’envahit ; θαῦμα ἔχω, SOPH. <i>El. 897,</i> je suis étonné ; ἐν θαύματι εἶναι, HDT. <i>1, 68 ;</i> THC. <i>8, 14 ; ou</i> γενέσθαι, HDT. <i>3, 3 ;</i> ἐν θωύματι ἔχεσθαι, HDT. <i>8, 135 ; ou</i> ἐνέχεσθαι, HDT. <i>7, 128,</i> être saisi d’étonnement ; θῶυμα ποιεῖσθαί τι, τινος <i>ou</i> περί τινος, HDT. <i>1, 68 ; 3, 23 ;</i> ἐν θαύματι ποιεῖσθαι, PLUT. <i>Pomp. 14,</i> s’étonner <i>ou</i> s’émerveiller de qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. θῶμα <i>ou</i> θῶυμα, HDT. <i>1, 68, 93, etc</i>.<br><span><b>Étym</b>. <i>pré-grec ; cf</i>. θάμϐος, τέθηπα <i>et p.-ê</i>. θεάομαι, contempler.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαυμα - θαῦμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2296":"<h1>thaumazo</h1>\n<p>Strong n° 2296 <i>Prononciation [thou-mad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étonner, étonné de, étonnement, merveille</li>\n<li>être dans l'admiration, admirer, vénérer, honorer</li>\n<li>flatter les personnes, d'après l'hébreu « adoucir la face »</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θαυμάζω</b> <span>(<i>f</i>. -άσομαι, <i>rar</i>. -άσω, <i>ao</i>. ἐθαύμασα, <i>pf</i>. τεθαύμακα ; <i>pass. ao</i>. ἐθαυμάσθην, <i>pf</i>. τεθαύμασμαι)</span><br><b>   I</b> <i>act</i>. s’étonner, voir avec étonnement <i>ou</i> admiration, admirer, vénérer, honorer :<br><b>      1</b> <i>abs</i>. IL. <i>24, 394 ;</i> HDT. <i>1, 68, etc. ;</i><br><b>      2</b> <i>avec un seul rég. : acc. de pers. ou de ch. :</i> τινά, IL. <i>5, 601. ;</i> ESCHL. <i>Ag. 853 ;</i> SOPH. <i>Aj. 1072, etc. ;</i> qqn : τι, IL. <i>13, 11 ;</i> OD. <i>4, 655 ; 16, 203 ;</i> HDT. <i>3, 80 ;</i> ESCHL. <i>Sept. 772 ;</i> SOPH. <i>Aj. 1093 ;</i> EUR. <i>El. 519,</i> qqe ch. ; μηδὲν θαυμάζειν, PLUT. <i>M. 44</i> b, ne s’étonner de rien (<i>cf. lat</i>. nil admirari) ; <i>avec un gén. de pers</i>. θ. τῶν ἐθελόντων, ISOCR. <i>Archid. 93,</i> admirer ceux qui veulent, <i>etc. ; avec un gén. de chose :</i> θαυμ. τινός, ISOCR. <i>137</i> d, <i>ou un dat</i>. θαυμ. τινί, THC. <i>4, 85 ; 7, 63 ;</i> s’étonner de qqe ch., admirer qqe ch. ;<br><b>      3</b> <i>avec double rég. :</i> τινὰ ἐπί τινι, XÉN. <i>Mem. 1, 4, 2 ;</i> PLAT. <i>Theæt. 161</i> c ; τινὰ περί τινος, PLAT. <i>Tim. 80</i> c ; τινὰ διά τι, ISOCR. <i>52</i> c ; τινὰ ἀπό τινος, PLUT. <i>Rom. 7,</i> qqn au sujet de qqe ch., par suite de qqe ch. ; <i>particul. avec un acc. de chose et un gén. de pers. ou inversement :</i> τί τινος, SOPH. <i>Ph. 1362 ;</i> PLAT. <i>Theæt. 161</i> b, <i>etc. ;</i> τινά τινος, THC. <i>6, 36, etc</i>. admirer qqn pour qqe ch. ; <i>avec un double gén. de pers. et de chose :</i> τινὸς τῆς διανοίας, LYS. <i>100, 16,</i> admirer l’intelligence <i>ou</i> la pensée de qqn ; <i>avec un gén. de pers. accompagné d’un part. :</i> θαυμάζω τῶν ταύτην τὴν γνώμην ἐχόντων, ISOCR. <i>27</i> b, j’admire ceux qui ont une pareille opinion ; <i>cf</i>. PLAT. <i>Prot. 329</i> b, <i>etc. ; avec un gén. de pers. suivi d’une conj. :</i> τινὸς ὅτι, ISOCR. <i>41</i> a ; τινὸς εἰ, XÉN. <i>Hell. 2, 3, 52 ;</i> ISOCR. <i>76</i> b, s’étonner que qqn, <i>etc. ; avec une prop. inf</i>. EUR. <i>Med. 268 ; avec une prop. précédée d’une des conj. :</i> εἰ, HDT. <i>1, 155 ;</i> SOPH. <i>O.C. 1140 ;</i> PLAT. <i>Rsp. 348</i> e, <i>Phæd. 95</i> a ; ὅτι, PLAT. <i>Rsp. 489</i> a, <i>Theæt. 142</i> a ; ὡς, OD. <i>19, 229 ;</i> THC. <i>1, 90 ;</i> XÉN. <i>Cyr. 1, 4, 20,</i> s’étonner que ; <i>avec un relat</i>. θαύμαζ' Ἀχιλῆα, ὅσσος ἔην οἷός τε, IL. <i>24, 629,</i> il admirait combien Achille était grand et quel il était ; Τηλέμαχον θαύμαζον, ὃ θαρσαλέως ἀγόρευεν, OD. <i>1, 382, etc</i>. ils admiraient que Télémaque parlât si hardiment ; θαυμάζειν ὅστις, <i>etc</i>. THC. <i>3, 38 ;</i> τί, <i>etc</i>. XÉN. <i>Hell. 2, 3, 17 (cf</i>. XÉN. <i>Cyr. 1, 4, 18</i>) se demander <i>ou</i> voir avec étonnement qui, <i>etc. ;</i> ce que, <i>etc. ;</i><br><b>   II</b> <i>au pass. :</i><br><b>      1</b> être un objet d’étonnement, HDT. <i>4, 28 ;</i> θαυμάζεται μὴ παρών, SOPH. <i>O.R. 289,</i> je m’étonne qu’il ne soit pas présent ;<br><b>      2</b> être un objet d’admiration, HDT. <i>3, 82 ;</i> être honoré, THC. <i>1, 38</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf. poét</i>. θαύμαζον, OD. <i>1, 382. Impf. itér</i>. θαυμάζεσκον, OD. <i>19, 229 ;</i> THCR. <i>Idyl. 25, 186. Fut. épq</i>. θαυμάσσομαι, IL. <i>18, 467. Fut. pass. au sens moy. 3 pl</i>. θαυμασθήσονται, NT. <i>Apoc. 17, 8. — Les formes ion. sont en</i> θωυμ- <i>ou</i> θωμ- ; <i>impf</i>. ἐθώμαζον <i>ou</i> ἐθώυμαζον, HDT. <i>1, 68, etc. ; ao</i>. ἐθώμασα <i>ou</i> ἐθώυμασα, HDT. <i>9, 16, etc</i>.<br><span><b>Étym</b>. θαῦμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαυμαζω - θαυμάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n47 fois dans 46 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (6)</li>\n<li>Luc (13)</li>\n<li>Jean (6)</li>\n<li>Actes (5)</li>\n<li>Galates (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Jean (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G2297":"<h1>thaumasios</h1>\n<p>Strong n° 2297 <i>Prononciation [thow-mas'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>merveilleux, étonnant, admirable</li>\n<li>faits merveilleux, étonnement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θαυμάσιος, α</b> <i>ou</i> <b>ος, ον</b> <span>[ᾰσ]</span><br><b>      1</b> admirable, étonnant, merveilleux, HH. <i>Merc. 443 ;</i> HÉS. <i>Th. 584 ;</i> PLAT. <i>Ap. 35</i> a, <i>etc. ;</i> θαυμάσια, HDT. <i>2, 35, etc</i>. des choses merveilleuses ; <i>avec un acc</i>. θαυμάσιος τὸ κάλλος, XÉN. <i>An. 2, 3, 9,</i> merveilleux de beauté ; <i>avec un inf</i>. θ. προσιδέσθαι, PD. <i>P. 1, 1, 49,</i> merveilleux à voir ; θαυμάσιον ὅσον, PLAT. <i>Conv. 217</i> a, <i>ou</i> θαυμάσι' ἡλίκα, DÉM. <i>348, 28,</i> merveilleusement (<i>lat</i>. mirum quantum) ; <i>souv. dans la conversation :</i> ὦ θαυμάσιε, PLAT. <i>Rsp. 435</i> c, mon admirable, ami ! <i>ironiq</i>. ὦ θαυμασιώτατε ἄνθρωπε, XÉN. <i>An. 3, 1, 27,</i> très admirable ami ;<br><b>      2</b> <i>en mauv. part,</i> θαυμάσιον καὶ ἄλογον, PLAT. <i>Gorg. 496</i> a, étrange et absurde,<br>-ώτερος, PLAT. <i>Euthyd. 299</i> e, MENEX. <i>235</i> b. <i>• Sup</i>. -ώτατος, XÉN. <i>l. c. ;</i> PLAT. <i>Rsp. 364</i> b ; ESCHN. <i>75, 17 ;</i> DS. <i>1, 63</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, LUC. <i>Im. 19. Épq. fém</i>. θαυμασίη, HÉS. <i>Th. 584. Ion</i>. θωμάσιος, HDT. <i>2, 35 ; cp. fém</i>. θωμασιωτέρη, HDT. <i>2, 21</i>.<br><span><b>Étym</b>. θαῦμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαυμασιος - θαυμάσιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2298":"<h1>thaumastos</h1>\n<p>Strong n° 2298 <i>Prononciation [thow-mas-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>merveilleux, étonnant\n<ol type=\"a\">\n<li>digne d'une pieuse admiration, admirable, excellent</li>\n<li>dépassant la compréhension humaine</li>\n<li>causant de l'étonnement joint à de la terreur</li>\n<li>merveilleux\n<ol>\n<li>extraordinaire, frappant, surprenant</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>θαυμαστός, ή, όν :<br>      1</b> étonnant, merveilleux, extraordinaire, HH. <i>Cer. 10 ;</i> HDT. <i>1, 1, etc. ;</i> ATT. ; οὐδὲν τούτων θαυμαστὸν ἐμοί, SOPH. <i>Ph. 191,</i> rien de tout cela ne m’étonne ; θαυμαστὰ δρᾶν, PLAT. <i>Conv. 151</i> a, faire des choses étonnantes ; θαυμαστὸν ποιεῖς ὅτι, XÉN. <i>Mem. 2, 7, 43,</i> tu fais une chose étonnante en ce que ; θαυμαστὸς τὸ κάλλος, PLAT. <i>Phæd. 110</i> c, merveilleux de beauté ; <i>ou</i> θαυμαστός τινος, PLUT. <i>Popl. 14, Per. 39 ; ou</i> τινι, PLUT. <i>Cæs. 6. ; ou</i> πρός τι, PLUT. <i>M. 980</i> d, merveilleux en qqe ch. ; θαυμαστὸν εἰ, XÉN. <i>Conv. 4, 3,</i> il est étonnant que ; οὐδὲν θαυμαστὸν εἰ, PLAT. <i>Rsp. 390</i> a, il n’y a rien d’étonnant à ce que ; θαυμαστὸν ὅσον, PLAT. <i>Theæt. 150</i> d ; θαυμαστὸν ὡς, SOPH. <i>fr. 963,</i> EUR. <i>I.A. 943 ; avec un plur</i>. θαυμαστὰ ὅσα, PLAT. <i>Hipp. ma. 282</i> c ; <i>ou</i> θαυμαστὸν ἡλίκον, DÉM. <i>738, 20, (lat</i>. mirum quantum) étonnamment, merveilleusement ;<br><b>      2</b> admirable, excellent, <i>en parl. de pers. et de ch</i>. PD. <i>P. 3, 126, etc. ;</i> SOPH. <i>O.C. 1664 ; ironiq</i>. ESCHL. <i>Pers. 212 ; particul. dans le dialogue :</i> ὦ θαυμαστέ, PLAT. <i>Pol. 265</i> a, admirable ami ; <i>cf</i>. XÉN. <i>An. 7, 7, 10, p. suite,</i> honoré, EUR. <i>Hipp. 106 ;</i><br><b>      3</b> <i>en mauv. part,</i> θαυμαστὰ καὶ γελοῖα, PLAT. <i>Theæt. 145</i> b, choses étranges et risibles.<br><span>•<i> Cp</i>. -ότερος, PLAT. <i>Theæt. 142</i> b, <i>Parm. 135</i> b, <i>etc.</i> <i>• Sup</i>. -ότατος, XÉN. <i>l. c. ;</i> PLAT. <i>Conv. 220</i> a. <i>Ion</i>. θωυμαστός, HDT. <i>l. c. et</i> θωμαστός, HDT. <i>9, 122</i>.<br><span><b>Étym</b>. θαυμάζω, <i>cf</i>. θαύματος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θαυμαστος - θαυμαστός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2299":"<h1>thea</h1>\n<p>Strong n° 2299 <i>Prononciation [theh-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une déesse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>θεά, ᾶς :<br>      1</b> <i>adj. f</i>. divine, IL. <i>1, 280 ; 24, 615 ;</i> ESCHL. <i>Suppl. 695 ;</i> SOPH. <i>Ant. 1184 ;</i><br><b>      2</b> <i>subst</i>. ἡ, θεά, déesse ; <i>p. opp. à une femme mortelle</i> (γυνή) IL. <i>14, 315 ;</i> joint au nom de la déesse : Παλλάδος θεᾶς, SOPH. <i>Ant. 1184,</i> de la déesse Pallas ; <i>cf</i>. EUR. <i>Andr. 135 ;</i> θεοὶ θεαί τε, ESCHL. <i>Sept. 86,</i> les dieux et les déesses ; αἱ σεμναὶ θεαί, SOPH. <i>O.C. 458 ;</i> AR. <i>Th. 224 ;</i> PLUT. <i>Sol. 12,</i> les déesses augustes, <i>càd</i>. les Érynies, <i>à Athènes, appelées aussi</i> ἔμφοϐοι θεαί, SOPH. <i>O.C. 40 ;</i> δειναὶ θεαί, EUR. <i>El. 1270 ;</i> θεαὶ ἀνώνυμοι, EUR. <i>I.T. 944,</i> les déesses terribles <i>ou</i> sans nom ; μεγάλαι θεαί, SOPH. <i>O.C. 683 ;</i> δύο τὼ θεά, PLAT. <i>Conv. 180</i> d, les grandes déesses, les deux déesses, <i>càd</i>. Dèmèter et Perséphonè.<br><span><b><span class=\"arrow\"></span></b> <span>[θεά <i>monosyll. par syniz. dans</i> πότνια θεά, OD. <i>5, 215 ; 13, 391 ; 20, 61 ;</i> EUR. <i>Andr. 978</i>]</span>. — <i>Dans les inscript. att. lorsqu’on parle de</i> « déesses » <i>sans parler en même temps de</i> « dieux », <i>le seul mot usuel dans la période classique est</i> ἡ θεός, CIA. <i>4, b, 27, b, 4, etc. (439 av. J.C.) en parl. d’Athèna (v. de nombreux exemples dans Meisterh. p. 98, 4, note 928</i>) ; τὼ θεώ, les deux déesses, <i>càd</i>. Dèmèter et Perséphonè (<i>v. Meisterh. ibid.) ; mais on lit :</i> τῷ θεῷ καὶ τῇ θεᾷ, CIA. <i>4, b, 27, b, 39 (439 av. J.C.) en parl. de Pluton et de Perséphonè ;</i> τοῖς δώδεκα θεοῖς καὶ ταῖς σεμναῖς θεαῖς, CIA. <i>2, add. 57, b, 8-9 (362 av. J.-C) ; ce n’est qu’à partir au 3<sup>e</sup> siècle av. J.C. qu’on trouve</i> θεά, <i>même quand on ne parle que de déesses (inscr. de 282 av. J.C.) v. Meisterh. p. 98, 4. — Épq. réc</i>. θεή, A. RH. <i>3, 252, 549, etc. ;</i> CALL. <i>Dian. 119, 152 ; dans Hom. seul. au dat. pl</i>. θεῇσ’, IL. <i>3, 158 ;</i> θεῇσιν, IL. <i>8, 305. Lac</i>. σιά, AR. <i>Lys. 1263</i>.<br><span><b>Étym</b>. <i>fém. de</i> θεός.</span><br><br>\n➁ <b>θέα, ας (ἡ) :<br>   I</b> <i>act</i>. action de regarder, de contempler, contemplation : θέης ἄξιος, HDT. <i>1, 25,</i> digne d’être vu ; εἰς θέαν τινὸς ἔρχεσθαι, EUR. <i>I.A. 427, ou</i> ἐπὶ θέαν ἐλθεῖν, PLAT. <i>Lach. 179</i> e, venir pour voir qqe ch. ; ἐπὶ τῇ θέᾳ τινός, XÉN. <i>Cyr. 1, 4, 24,</i> à la vue de qqe ch. ;<br><b>   II</b> <i>pass. :</i><br><b>      1</b> aspect : διαπρεπὴς τὴν θέαν, EUR. <i>I.A. 1588,</i> d’un aspect distingué ; ἀπὸ τῆς θέας εἰκάζειν, LUC. <i>V.H. 1, 11,</i> ressembler par l’air ;<br><b>      2</b> objet de contemplation, spectacle, ESCHL. <i>Pr. 241 ;</i> SOPH. <i>El. 1455 ;</i> EUR. <i>Hipp. 809 ; au plur</i>. PLAT. <i>Rsp. 615</i> a ; <i>particul</i>. spectacle au théâtre, ESCHN. <i>35, 10 ;</i> TH. <i>Char. 9, 2 ; d’où au pl</i>. αἱ θέαι, PLUT. <i>Brut. 21 ;</i> HDN <i>1, 15, 1 ; 3, 10, 3,</i> jeux, fêtes, spectacles ; <i>joint à</i> ἑστιάσεσι, PLUT. <i>Cæs. 55 ; à</i> ἑορταῖς, HDN <i>2, 8, 16 ;</i><br><b>      3</b> lieu d’où l’on regarde, <i>particul</i>. partie du théâtre occupée par les spectateurs, place à un spectacle, ESCHN. <i>35, 11 ; cf</i>. DÉM. <i>234, 24 ;</i> θέαν καταλαμϐάνειν, DÉM. <i>572, 12,</i> occuper une place au théâtre ; θέαν ἔχειν ἐν θεάτρῳ, PLUT. <i>Flam. 19,</i> avoir une place dans un théâtre.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. θέη, HDT. <i>l. c. etc</i>.<br><span><b>Étym</b>. <i>pré-grec ; cf</i>. θαῦμα, θάμϐος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">θεα - θεά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>"};
